import { Crown } from 'lucide-react';
import { cn } from '@/lib/utils';

interface VvipBadgeProps {
  className?: string;
  size?: 'sm' | 'md' | 'lg';
  text?: string;
}

export default function VvipBadge({ className, size = 'sm', text }: VvipBadgeProps) {
  const sizeClasses = {
    sm: 'text-[10px] px-1.5 py-0.5 gap-0.5',
    md: 'text-xs px-2 py-0.5 gap-1',
    lg: 'text-sm px-2.5 py-1 gap-1',
  };
  const iconSizes = {
    sm: 'w-3 h-3',
    md: 'w-3.5 h-3.5',
    lg: 'w-4 h-4',
  };

  return (
    <span
      className={cn(
        'inline-flex items-center rounded-full font-semibold',
        'bg-yellow-500/15 text-yellow-500 border border-yellow-500/30',
        sizeClasses[size],
        className,
      )}
    >
      <Crown className={iconSizes[size]} fill="currentColor" />
      {text || '皇牌'}
    </span>
  );
}
