import { StrictMode } from "react";
import { createRoot } from "react-dom/client";

// 捕獲 async / unhandled 錯誤，避免白屏；同時留線索方便排查
if (typeof window !== "undefined") {
  window.addEventListener("error", (e) => {
    console.error("[global-error]", e.message);
  });
  window.addEventListener("unhandledrejection", (e) => {
    console.error("[unhandledrejection]", e.reason);
  });
}
import { BrowserRouter, HashRouter } from "react-router-dom";
import { ErrorBoundary } from "react-error-boundary";
import { AppContainer, ErrorRender, logger } from "@/lib/standalone-shim";
import App from "./app";
import "./index.css";

// APK / 離線打包版用 HashRouter（VITE_HASH_ROUTER=true），網頁版照舊 BrowserRouter
const useHashRouter = import.meta.env.VITE_HASH_ROUTER === 'true';
const Router = useHashRouter ? HashRouter : BrowserRouter;
// 根域名部署直接用 '/'，唔好用 ((typeof window !== "undefined" && window.__BASENAME__) || "")（部署環境會塞 {{basename}} 字面字串搞到白頁）
const basename = useHashRouter ? undefined : "/";

// PWA: 註冊 Service Worker（生產環境先註冊；APK 內 WebView 註冊失敗唔影響使用）
if ('serviceWorker' in navigator && import.meta.env.PROD && !useHashRouter) {
  window.addEventListener('load', () => {
    navigator.serviceWorker
      .register('/sw.js')
      .then(() => {
        logger.info('PWA ServiceWorker registered');
      })
      .catch((err) => {
        logger.warn('PWA ServiceWorker registration failed:', String(err));
      });
  });
}

createRoot(document.getElementById("root")!).render(
  <StrictMode>
    <Router basename={basename}>
      <AppContainer>
        <ErrorBoundary
          fallbackRender={({ error, resetErrorBoundary }) => (
            <ErrorRender error={error} resetErrorBoundary={resetErrorBoundary} />
          )}
        >
          <App />
        </ErrorBoundary>
      </AppContainer>
    </Router>
  </StrictMode>,
);
