import { scopedStorage, logger } from '@/lib/standalone-shim';

// Dev 模式直接指向本地 Express 後端（繞過 Vite proxy 限制）
// Production 預設同源 /api；打包「連網版 APK」時用 VITE_API_BASE 指定雲端後端地址
// （例如：VITE_API_BASE=https://dikdou.onrender.com bash scripts/build-standalone.sh）
const API_BASE = (import.meta.env.VITE_API_BASE as string | undefined) || (import.meta.env.DEV ? 'http://localhost:3001' : '');

// ========== 輕量 fetch 客戶端（代替 axios：喺 Capacitor/standalone 環境 100% 穩定）==========
const DEFAULT_TIMEOUT = 15000;

async function request(method: 'GET' | 'POST' | 'PUT' | 'DELETE', url: string, data?: any, cfg?: any) {
  const controller = new AbortController();
  const timeoutMs = cfg?.timeout ?? DEFAULT_TIMEOUT;
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  const token = scopedStorage.getItem('dikdou_token');
  try {
    const res = await fetch(`${API_BASE}/api${url}`, {
      method,
      headers: {
        'Content-Type': 'application/json',
        ...(token ? { Authorization: `Bearer ${token}` } : {}),
      },
      body: data !== undefined ? JSON.stringify(data) : undefined,
      credentials: 'include',
      signal: controller.signal,
    });
    clearTimeout(timer);
    const text = await res.text();
    let json: any = null;
    try {
      json = text ? JSON.parse(text) : null;
    } catch {
      json = text;
    }
    if (!res.ok) {
      // 401：登入失效——清 token 並跳轉去對應登入頁（避免司機一直卡喺「0 張新單」誤導）
      // 但「在線續期／心跳」呢類 keep-alive call 用 silentAuth，遇到 401 唔登出，
      // 避免 server 一時返 401（或心跳失敗）就將司機踢走——真失效會由業務 API（fetchActive 等）發現
      if (res.status === 401 && token && !cfg?.silentAuth) {
        // 完整登出（清埋 user/role），避免「token 冇咗但 user 仲留喺 storage」嘅半登出狀態
        clearAuth();
        const hash = (typeof window !== 'undefined' && window.location.hash) || '';
        const target = hash.includes('/driver') ? '/driver/login'
          : hash.includes('/passenger') ? '/passenger/login'
          : hash.includes('/admin') ? '/admin/login' : '';
        if (target && !hash.includes('/login') && typeof window !== 'undefined') {
          window.location.hash = target;
        }
      }
      const err: any = new Error(json?.error || `HTTP ${res.status}`);
      err.response = { status: res.status, data: json };
      err.config = { url };
      throw err;
    }
    return { data: json, status: res.status, statusText: res.statusText };
  } catch (e: any) {
    clearTimeout(timer);
    if (e?.name === 'AbortError') {
      const err: any = new Error('timeout of ' + timeoutMs + 'ms exceeded');
      err.response = undefined;
      err.config = { url };
      throw err;
    }
    // 統一錯誤日誌
    const msg = String(e?.message || e);
    if (msg.includes('Failed to fetch') || msg.includes('Network Error')) {
      logger.warn('API network error (expected in demo mode):', msg);
    } else {
      logger.error('API error:', msg);
    }
    throw e;
  }
}

// 兼容 axios 嘅 api instance shape（caller 用 api.get/api.post + res.data）
const api = {
  get: (url: string, cfg?: any) => request('GET', url, undefined, cfg),
  post: (url: string, data?: any, cfg?: any) => request('POST', url, data, cfg),
  put: (url: string, data?: any, cfg?: any) => request('PUT', url, data, cfg),
  delete: (url: string, cfg?: any) => request('DELETE', url, undefined, cfg),
};

// ========== Auth Storage ==========
const TOKEN_KEY = 'dikdou_token';
const USER_KEY = 'dikdou_user';
const ROLE_KEY = 'dikdou_role';

// 連線測試：確認 app 有冇真係連到雲端後端（用嚟顯示「雲端已連接/離線單機」狀態）
export async function testBackendConnection(): Promise<boolean> {
  try {
    const res = await api.get('/health', { timeout: 8000 });
    return !!(res.data && res.data.ok);
  } catch {
    return false;
  }
}

export function getToken() {
  return scopedStorage.getItem(TOKEN_KEY) || '';
}

export function setAuth(token: string, user: any, role: 'passenger' | 'driver' | 'admin') {
  scopedStorage.setItem(TOKEN_KEY, token);
  scopedStorage.setItem(USER_KEY, JSON.stringify(user));
  scopedStorage.setItem(ROLE_KEY, role);
  // 同時存 raw token 到 localStorage，俾 SSE query param 用（scopedStorage 有 appId 前綴）
  if (role === 'driver') localStorage.setItem('hktaxi_driverToken', token);
  if (role === 'admin') localStorage.setItem('hktaxi_adminToken', token);
  if (role === 'passenger') localStorage.setItem('hktaxi_passengerToken', token);
}

export function clearAuth() {
  scopedStorage.removeItem(TOKEN_KEY);
  scopedStorage.removeItem(USER_KEY);
  scopedStorage.removeItem(ROLE_KEY);
  localStorage.removeItem('hktaxi_driverToken');
  localStorage.removeItem('hktaxi_adminToken');
  localStorage.removeItem('hktaxi_passengerToken');
}

// 更新已登入 user 嘅 storage 快照（司機設定改名／電話後即時持久化，reload 唔會打回原形）
export function persistUser(user: any) {
  scopedStorage.setItem(USER_KEY, JSON.stringify(user));
}

export function getStoredUser(): any {
  const raw = scopedStorage.getItem(USER_KEY);
  if (!raw) return null;
  try { return JSON.parse(raw); } catch { return null; }
}

export function getStoredRole(): string {
  return scopedStorage.getItem(ROLE_KEY) || '';
}

