import { useState, useMemo } from 'react';
import { motion } from 'framer-motion';
import {
  Receipt,
  X,
  Copy,
  Share2,
  MapPin,
  Navigation,
  Check,
  Info,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import { useI18n } from '@/lib/i18n';
import { useTheme } from '@/lib/theme-context';

export interface ReceiptData {
  receiptNo: string;
  paidAt: number;
  pickupName: string;
  destinationName: string;
  fare: number;
  tip: number;
  discountRate?: number; // e.g. 0.85 for 15% off
  total: number;
  paymentMethod: string;
  paymentMethodLabel?: string;
  carType: string;
  taxiTypeName?: string;
  plate?: string;
  driverName?: string;
  distanceKm?: number;
  durationMin?: number;
  flagfall?: number;
  mileage?: number;
  surcharge?: number;
  luggage?: number;
  tunnel?: number;
  waiting?: number;
  orderId?: string;
}

interface ReceiptModalProps {
  open: boolean;
  onClose: () => void;
  data: ReceiptData | null;
}

const PAYMENT_LABEL_MAP: Record<string, string> = {
  octopus: '八達通 Octopus',
  fps: 'FPS 轉數快',
  alipayhk: 'AlipayHK',
  wechat: 'WeChat Pay HK',
  credit: '信用卡 Credit Card',
  applepay: 'Apple Pay',
  googlepay: 'Google Pay',
  cash: '現金 Cash',
};

export default function ReceiptModal({ open, onClose, data }: ReceiptModalProps) {
  const { t } = useI18n();
  const { theme } = useTheme();
  const [copied, setCopied] = useState(false);

  const receiptText = useMemo(() => {
    if (!data) return '';
    const d = new Date(data.paidAt);
    const dateStr = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')} ${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
    const lines = [
      '==============================',
      '   的道 DikDou 電子收據',
      '==============================',
      `收據編號：${data.receiptNo}`,
      `日期時間：${dateStr}`,
      '------------------------------',
      `上車地點：${data.pickupName}`,
      `目的地：${data.destinationName}`,
      `車型：${data.taxiTypeName || data.carType}`,
      `車牌：${data.plate || '-'}`,
      `司機：${data.driverName || '-'}`,
      `里程：${(data.distanceKm ?? 0).toFixed(1)} km`,
      `時間：${data.durationMin ?? 0} 分鐘`,
      '------------------------------',
      `車費：HK$${data.fare.toFixed(2)}`,
      data.tip > 0 ? `貼士：HK$${data.tip.toFixed(2)}` : null,
      data.discountRate && data.discountRate < 1
        ? `折扣 (${Math.round((1 - data.discountRate) * 100)}% OFF)：-HK$${(data.fare * (1 - data.discountRate)).toFixed(2)}`
        : null,
      '------------------------------',
      `總金額：HK$${data.total.toFixed(2)}`,
      `付款方式：${PAYMENT_LABEL_MAP[data.paymentMethod] || data.paymentMethodLabel || data.paymentMethod}`,
      '==============================',
    ].filter(Boolean) as string[];
    return lines.join('\n');
  }, [data]);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(receiptText);
      setCopied(true);
      toast.success(t.receipt.copied);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      toast.error('複製失敗');
    }
  };

  const handleShare = async () => {
    if (!data) return;
    if (navigator.share) {
      try {
        await navigator.share({
          title: '的道 電子收據',
          text: receiptText,
        });
      } catch {
        // user cancelled
      }
    } else {
      handleCopy();
      toast.info('已複製收據到剪貼簿（瀏覽器唔支援分享）');
    }
  };

  if (!open || !data) return null;

  const d = new Date(data.paidAt);
  const dateStr = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
  const timeStr = `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}:${String(d.getSeconds()).padStart(2, '0')}`;

  const discountAmount = data.discountRate && data.discountRate < 1
    ? data.fare * (1 - data.discountRate)
    : 0;

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="fixed inset-0 z-[100] bg-black/50 backdrop-blur-sm flex items-end justify-center"
      onClick={onClose}
    >
      <motion.div
        initial={{ y: '100%' }}
        animate={{ y: 0 }}
        exit={{ y: '100%' }}
        transition={{ type: 'spring', damping: 28, stiffness: 320 }}
        className="w-full max-w-md bg-white rounded-t-3xl max-h-[85vh] overflow-y-auto"
        onClick={(e) => e.stopPropagation()}
      >
        {/* 頂部 handle */}
        <div className="sticky top-0 bg-white pt-2 pb-1 z-10">
          <div className="w-10 h-1 bg-slate-300 rounded-full mx-auto" />
        </div>

        <div className="px-5 pb-6">
          {/* Header */}
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-2">
              <div className={`size-9 rounded-xl flex items-center justify-center ${
                theme === 'green' ? 'bg-emerald-100 text-emerald-600' : 'bg-red-100 text-red-600'
              }`}>
                <Receipt className="size-5" />
              </div>
              <div>
                <h3 className="text-lg font-black text-foreground">{t.receipt.title}</h3>
                <p className="text-[11px] text-muted-foreground font-mono">{data.receiptNo}</p>
              </div>
            </div>
            <button
              onClick={onClose}
              className="size-8 rounded-full bg-slate-100 flex items-center justify-center hover:bg-slate-200 transition-colors"
            >
              <X className="size-4 text-slate-500" />
            </button>
          </div>

          {/* 免責：網上預計價錢 */}
          <div className="flex items-start gap-2 bg-amber-50 border border-amber-200/60 rounded-xl px-3 py-2 mb-3">
            <Info className="size-4 text-amber-500 shrink-0 mt-0.5" />
            <p className="text-[11px] leading-snug text-amber-700">
              以上為<b>網上預計價錢</b>（預算），實際情況按<b>香港政府法定收費</b>計算，以司機車上錶為準。
            </p>
          </div>

          {/* 收據卡 */}
          <div className="bg-gradient-to-br from-slate-50 to-slate-100 rounded-2xl p-5 relative overflow-hidden border border-slate-200/50">
            {/* 裝飾 */}
            <div className="absolute top-0 right-0 size-24 bg-primary/5 rounded-full -translate-y-1/2 translate-x-1/2" />

            {/* 金額 */}
            <div className="text-center mb-4">
              <div className="text-xs text-muted-foreground mb-1">{t.receipt.total}</div>
              <div className={`text-4xl font-black tabular-nums tracking-tight ${
                theme === 'green' ? 'text-emerald-600' : 'text-red-600'
              }`}>
                HK${data.total.toFixed(2)}
              </div>
            </div>

            {/* 起訖 */}
            <div className="bg-white rounded-xl p-3 mb-3">
              <div className="flex items-center gap-3 pb-2 border-b border-dashed border-slate-200">
                <MapPin className="size-4 text-emerald-500 shrink-0" />
                <div className="flex-1 min-w-0">
                  <div className="text-[10px] text-emerald-600 font-medium uppercase">{t.receipt.from}</div>
                  <div className="text-sm font-medium text-foreground truncate">{data.pickupName}</div>
                </div>
              </div>
              <div className="flex items-center gap-3 pt-2">
                <Navigation className="size-4 text-red-500 shrink-0" />
                <div className="flex-1 min-w-0">
                  <div className="text-[10px] text-red-600 font-medium uppercase">{t.receipt.to}</div>
                  <div className="text-sm font-medium text-foreground truncate">{data.destinationName}</div>
                </div>
              </div>
            </div>

            {/* 收據資料 */}
            <div className="bg-white rounded-xl p-3 space-y-2">
              <div className="flex items-center justify-between text-xs">
                <span className="text-muted-foreground">{t.receipt.receiptNo}</span>
                <span className="font-mono text-foreground font-medium">{data.receiptNo}</span>
              </div>
              <div className="flex items-center justify-between text-xs">
                <span className="text-muted-foreground">{t.receipt.date}</span>
                <span className="text-foreground font-medium">{dateStr} {timeStr}</span>
              </div>
              {data.driverName && (
                <div className="flex items-center justify-between text-xs">
                  <span className="text-muted-foreground">{t.receipt.driver}</span>
                  <span className="text-foreground font-medium">{data.driverName}</span>
                </div>
              )}
              {data.plate && (
                <div className="flex items-center justify-between text-xs">
                  <span className="text-muted-foreground">{t.receipt.plate}</span>
                  <span className="font-mono text-foreground font-medium">{data.plate}</span>
                </div>
              )}
              <div className="flex items-center justify-between text-xs">
                <span className="text-muted-foreground">{t.receipt.distance}</span>
                <span className="text-foreground font-medium">{(data.distanceKm ?? 0).toFixed(1)} km</span>
              </div>
              <div className="flex items-center justify-between text-xs">
                <span className="text-muted-foreground">{t.receipt.duration}</span>
                <span className="text-foreground font-medium">{data.durationMin ?? 0} {t.common.minute}</span>
              </div>
            </div>

            {/* 收據明細 */}
            <div className="bg-white rounded-xl p-3 mt-3 space-y-2">
              <div className="text-xs font-bold text-foreground mb-1">{t.receipt.fare}</div>
              {data.flagfall !== undefined && (
                <div className="flex items-center justify-between text-xs">
                  <span className="text-muted-foreground">{t.receipt.flagfall}</span>
                  <span className="text-foreground">HK${data.flagfall.toFixed(2)}</span>
                </div>
              )}
              {data.mileage !== undefined && (
                <div className="flex items-center justify-between text-xs">
                  <span className="text-muted-foreground">{t.receipt.mileage}</span>
                  <span className="text-foreground">HK${data.mileage.toFixed(2)}</span>
                </div>
              )}
              {data.waiting !== undefined && data.waiting > 0 && (
                <div className="flex items-center justify-between text-xs">
                  <span className="text-muted-foreground">{t.receipt.waiting}</span>
                  <span className="text-foreground">HK${data.waiting.toFixed(2)}</span>
                </div>
              )}
              {data.tunnel !== undefined && data.tunnel > 0 && (
                <div className="flex items-center justify-between text-xs">
                  <span className="text-muted-foreground">{t.receipt.tunnel}</span>
                  <span className="text-foreground">HK${data.tunnel.toFixed(2)}</span>
                </div>
              )}
              {data.luggage !== undefined && data.luggage > 0 && (
                <div className="flex items-center justify-between text-xs">
                  <span className="text-muted-foreground">{t.receipt.luggage}</span>
                  <span className="text-foreground">HK${data.luggage.toFixed(2)}</span>
                </div>
              )}
              {data.tip > 0 && (
                <div className="flex items-center justify-between text-xs text-emerald-600">
                  <span>{t.receipt.tip} +</span>
                  <span className="font-medium">HK${data.tip.toFixed(2)}</span>
                </div>
              )}
              {discountAmount > 0 && (
                <div className="flex items-center justify-between text-xs text-orange-500">
                  <span className="flex items-center gap-1">
                    <Badge variant="outline" className="h-4 text-[9px] border-orange-300 text-orange-500">
                      {t.receipt.discount}
                    </Badge>
                    {t.receipt.discount85} -
                  </span>
                  <span className="font-medium">HK${discountAmount.toFixed(2)}</span>
                </div>
              )}
              <div className="border-t border-dashed border-slate-200 pt-2 mt-2">
                <div className="flex items-center justify-between">
                  <span className="text-sm font-bold text-foreground">{t.receipt.total}</span>
                  <span className={`text-lg font-black ${
                    theme === 'green' ? 'text-emerald-600' : 'text-red-600'
                  }`}>
                    HK${data.total.toFixed(2)}
                  </span>
                </div>
              </div>
            </div>

            {/* 付款方式 */}
            <div className="bg-white rounded-xl p-3 mt-3">
              <div className="flex items-center justify-between text-xs">
                <span className="text-muted-foreground">{t.receipt.paymentMethod}</span>
                <Badge variant="secondary" className="text-xs font-medium">
                  {PAYMENT_LABEL_MAP[data.paymentMethod] || data.paymentMethodLabel || data.paymentMethod}
                </Badge>
              </div>
            </div>

            {/* 底部提示 */}
            <div className="mt-3 flex items-center gap-1.5 text-[10px] text-muted-foreground justify-center">
              <Info className="size-3" />
              呢個係電子收據，歡迎隨時查閱同分享
            </div>
          </div>

          {/* 操作按鈕 */}
          <div className="grid grid-cols-2 gap-3 mt-4">
            <Button
              variant="secondary"
              className="h-12 rounded-xl font-semibold"
              onClick={handleCopy}
            >
              {copied ? (
                <>
                  <Check className="size-4 mr-1.5" />
                  {t.receipt.copied}
                </>
              ) : (
                <>
                  <Copy className="size-4 mr-1.5" />
                  {t.receipt.copy}
                </>
              )}
            </Button>
            <Button
              className="h-12 rounded-xl font-semibold"
              onClick={handleShare}
            >
              <Share2 className="size-4 mr-1.5" />
              {t.receipt.share}
            </Button>
          </div>
        </div>
      </motion.div>
    </motion.div>
  );
}
