import { useEffect, useRef, useState } from 'react';
import { AlertTriangle } from 'lucide-react';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import { MOCK_LANDMARKS } from '@/data/landmarks';
import { useI18n } from '@/lib/i18n';
import type { IDriver } from '@/data/drivers';

interface AMapViewProps {
  pickupName?: string;
  destinationName?: string;
  pickupLat?: number;
  pickupLng?: number;
  destLat?: number;
  destLng?: number;
  driverLat?: number;
  driverLng?: number;
  passengerLat?: number;
  passengerLng?: number;
  nearbyDrivers?: IDriver[];
  showRoute?: boolean;
  routePath?: Array<[number, number]>; // [lng, lat] pairs
  height?: string;
  centerLat?: number;
  centerLng?: number;
  zoom?: number;
}

const HK_CENTER: [number, number] = [22.3080, 114.1729];

// Leaflet divIcon（HTML marker，唔使外部圖片，跨平台一定顯示）
function divIcon(html: string, size = 28, anchor = 0) {
  const a = anchor || size / 2;
  return L.divIcon({
    html,
    className: 'tx-divicon',
    iconSize: [size, size],
    iconAnchor: [a, a],
    popupAnchor: [0, -size / 2],
  });
}

const PIN_START = (name: string) =>
  `<div style="width:26px;height:34px;position:relative;"><div style="position:absolute;left:50%;top:50%;transform:translate(-50%,-100%);width:22px;height:22px;border-radius:50% 50% 50% 0;background:#10b981;border:3px solid #fff;transform:translate(-50%,-100%) rotate(-45deg);box-shadow:0 2px 8px rgba(0,0,0,.3);"><span style="position:absolute;inset:0;transform:rotate(45deg);display:flex;align-items:center;justify-content:center;color:#fff;font-size:10px;font-weight:bold;">出</span></div></div>`;

const PIN_END = (name: string) =>
  `<div style="width:26px;height:34px;position:relative;"><div style="position:absolute;left:50%;top:50%;width:22px;height:22px;border-radius:50% 50% 50% 0;background:#ef4444;border:3px solid #fff;transform:translate(-50%,-100%) rotate(-45deg);box-shadow:0 2px 8px rgba(0,0,0,.3);"><span style="position:absolute;inset:0;transform:rotate(45deg);display:flex;align-items:center;justify-content:center;color:#fff;font-size:10px;font-weight:bold;">到</span></div></div>`;

const DOT_DRIVER =
  '<div style="width:28px;height:28px;border-radius:50%;background:#ef4444;border:2px solid #fff;display:flex;align-items:center;justify-content:center;box-shadow:0 2px 8px rgba(0,0,0,.3);font-size:14px;">🚕</div>';
const DOT_PULSE =
  '<div style="width:36px;height:36px;border-radius:50%;background:#ef4444;border:3px solid #fff;display:flex;align-items:center;justify-content:center;box-shadow:0 0 0 0 rgba(239,68,68,.5);animation:txpulse 2s infinite;font-size:16px;">🚕</div>';
const DOT_PASSENGER =
  '<div style="width:32px;height:32px;border-radius:50%;background:#3b82f6;border:3px solid #fff;display:flex;align-items:center;justify-content:center;box-shadow:0 0 0 0 rgba(59,130,246,.5);animation:txpulse 2s infinite;font-size:14px;">👤</div>';

function latLng(name?: string, lat?: number, lng?: number): [number, number] | null {
  const num = (v: number | undefined) => typeof v === 'number' && isFinite(v);
  if (num(lat) && num(lng)) return [lat!, lng!];
  if (name) {
    const lm = MOCK_LANDMARKS.find((l) => l.name === name);
    if (lm) return [lm.lat, lm.lng];
  }
  return null;
}

// 高德底圖（香港資料齊）；失敗自動 fallback OSM
function addTiles(map: L.Map) {
  const hk = L.tileLayer('https://webrd0{s}.is.autonavi.com/appmaptile?lang=zh_cn&size=1&scale=1&style=8&x={x}&y={y}&z={z}', {
    subdomains: '1234',
    maxZoom: 18,
    attribution: '© 高德地圖',
  });
  hk.addTo(map);
  let fell = false;
  hk.on('tileerror', () => {
    if (fell) return;
    fell = true;
    try {
      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        maxZoom: 19,
        attribution: '© OpenStreetMap',
      }).addTo(map);
    } catch { /* ignore */ }
  });
  return hk;
}

// OSRM 路線（免費，海外 work）
function fetchRoute(p1: [number, number], p2: [number, number]): Promise<[number, number][]> {
  const url = `https://router.project-osrm.org/route/v1/driving/${p1[1]},${p1[0]};${p2[1]},${p2[0]}?overview=full&geometries=geojson`;
  return fetch(url)
    .then((r) => r.json())
    .then((d) => (d.code === 'Ok' && d.routes?.[0]?.geometry?.coordinates
      ? d.routes[0].geometry.coordinates.map((c: number[]) => [c[0], c[1]] as [number, number])
      : []))
    .catch(() => []);
}

export default function AMapView({
  pickupName,
  destinationName,
  pickupLat,
  pickupLng,
  destLat,
  destLng,
  driverLat,
  driverLng,
  passengerLat,
  passengerLng,
  nearbyDrivers = [],
  showRoute = false,
  routePath,
  height = 'auto',
  centerLat,
  centerLng,
  zoom = 13,
}: AMapViewProps) {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<L.Map | null>(null);
  const markersRef = useRef<Record<string, L.Marker | undefined>>({});
  const routeLineRef = useRef<L.Polyline | null>(null);
  const [isReady, setIsReady] = useState(false);
  const [loadError, setLoadError] = useState('');
  const { t } = useI18n();

  // 初始化地圖
  useEffect(() => {
    if (!mapContainerRef.current || mapRef.current) return;
    let cancelled = false;

    const num = (v: number | undefined) => typeof v === 'number' && isFinite(v);
    let lat = num(centerLat) ? centerLat! : HK_CENTER[0];
    let lng = num(centerLng) ? centerLng! : HK_CENTER[1];
    const p = latLng(pickupName, pickupLat, pickupLng);
    if (p) { lat = p[0]; lng = p[1]; }

    const map = L.map(mapContainerRef.current, {
      zoom,
      center: [lat, lng],
      scrollWheelZoom: false,
      zoomControl: true,
      attributionControl: false,
    });
    addTiles(map);
    mapRef.current = map;
    // Leaflet 喺容器尺寸未定（動畫/tab）時 marker 位置計算會出 `_leaflet_pos` 錯誤，等 ready 後重算尺寸
    map.whenReady(() => {
      setTimeout(() => {
        try { if (mapRef.current) mapRef.current.invalidateSize(); } catch { /* ignore */ }
      }, 50);
    });
    if (!cancelled) setIsReady(true);

    return () => {
      cancelled = true;
      const m = mapRef.current;
      mapRef.current = null;
      markersRef.current = {};
      routeLineRef.current = null;
      // 同步移除：唔可以 setTimeout(0) 延遲——StrictMode 雙 mount／導航返嚟
      // 嘅第二次 L.map() 會撞上未移除嘅 container，Leaflet 會 throw
      // "Map container is already initialized" 令 ErrorBoundary 白屏
      if (m) {
        try { m.remove(); } catch { /* 節點可能已移除 */ }
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // 更新中心／縮放
  useEffect(() => {
    if (!isReady || !mapRef.current) return;
    const num = (v: number | undefined) => typeof v === 'number' && isFinite(v);
    const p = latLng(pickupName, pickupLat, pickupLng);
    const d = latLng(destinationName, destLat, destLng);
    if (p && d && showRoute) {
      const b = L.latLngBounds(p, d);
      try { mapRef.current.fitBounds(b.pad(0.3), { padding: [40, 40] }); } catch { /* ignore */ }
    } else if (p) {
      mapRef.current.setView(p, zoom, { animate: false });
    } else if (num(centerLat) && num(centerLng)) {
      mapRef.current.setView([centerLat!, centerLng!], zoom, { animate: false });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isReady, pickupName, destinationName, pickupLat, pickupLng, destLat, destLng, showRoute, centerLat, centerLng, zoom]);

  // 上車點 marker
  useEffect(() => {
    if (!isReady || !mapRef.current) return;
    const map = mapRef.current;
    if (markersRef.current.pickup) { map.removeLayer(markersRef.current.pickup); markersRef.current.pickup = undefined; }
    const p = latLng(pickupName, pickupLat, pickupLng);
    if (p) {
      markersRef.current.pickup = L.marker(p, {
        icon: divIcon(PIN_START(pickupName || ''), 26, 26),
        zIndexOffset: 100,
        title: `${t.common.amap.pickupPoint}：${pickupName || ''}`,
      }).addTo(map);
    }
  }, [isReady, pickupName, pickupLat, pickupLng]);

  // 目的地 marker
  useEffect(() => {
    if (!isReady || !mapRef.current) return;
    const map = mapRef.current;
    if (markersRef.current.destination) { map.removeLayer(markersRef.current.destination); markersRef.current.destination = undefined; }
    const d = latLng(destinationName, destLat, destLng);
    if (d) {
      markersRef.current.destination = L.marker(d, {
        icon: divIcon(PIN_END(destinationName || ''), 26, 26),
        zIndexOffset: 90,
        title: `${t.common.amap.destination}：${destinationName || ''}`,
      }).addTo(map);
    }
  }, [isReady, destinationName, destLat, destLng]);

  // 附近司機 markers
  useEffect(() => {
    if (!isReady || !mapRef.current) return;
    const map = mapRef.current;
    if (markersRef.current.nearby) {
      (markersRef.current.nearby as L.LayerGroup).clearLayers();
      markersRef.current.nearby = undefined;
    }
    const valid = (nearbyDrivers || []).filter((d: any) => d && typeof d?.currentLng === 'number' && typeof d?.currentLat === 'number');
    if (valid.length === 0) return;
    const group = L.layerGroup(
      valid.map((d: any) => L.marker([d.currentLat, d.currentLng], {
        icon: divIcon(DOT_DRIVER, 28),
        zIndexOffset: 50,
        title: d.name || t.common.amap.nearbyDriver,
      })),
    );
    group.addTo(map);
    markersRef.current.nearby = group;
  }, [isReady, nearbyDrivers]);

  // 接單司機位置 marker
  useEffect(() => {
    if (!isReady || !mapRef.current) return;
    const map = mapRef.current;
    if (markersRef.current.driver) { map.removeLayer(markersRef.current.driver); markersRef.current.driver = undefined; }
    const num = (v: number | undefined) => typeof v === 'number' && isFinite(v);
    if (num(driverLat) && num(driverLng)) {
      markersRef.current.driver = L.marker([driverLat!, driverLng!], {
        icon: divIcon(DOT_PULSE, 36),
        zIndexOffset: 150,
        title: t.common.amap.yourDriver,
      }).addTo(map);
    }
  }, [isReady, driverLat, driverLng]);

  // 乘客位置 marker
  useEffect(() => {
    if (!isReady || !mapRef.current) return;
    const map = mapRef.current;
    if (markersRef.current.passenger) { map.removeLayer(markersRef.current.passenger); markersRef.current.passenger = undefined; }
    const num = (v: number | undefined) => typeof v === 'number' && isFinite(v);
    if (num(passengerLat) && num(passengerLng)) {
      markersRef.current.passenger = L.marker([passengerLat!, passengerLng!], {
        icon: divIcon(DOT_PASSENGER, 32),
        zIndexOffset: 120,
        title: t.common.amap.passengerLocation,
      }).addTo(map);
    }
  }, [isReady, passengerLat, passengerLng]);

  // 路線 polyline
  useEffect(() => {
    if (!isReady || !mapRef.current) return;
    const map = mapRef.current;
    let cancelled = false;
    const clear = () => {
      if (routeLineRef.current) { map.removeLayer(routeLineRef.current); routeLineRef.current = null; }
    };
    clear();
    if (!showRoute) return;

    if (Array.isArray(routePath) && routePath.length > 1) {
      const pts = routePath.filter((pt) => Array.isArray(pt) && pt.length >= 2).map((pt) => [pt[0], pt[1]] as [number, number]);
      routeLineRef.current = L.polyline(pts.map((p) => [p[1], p[0]] as [number, number]), {
        color: '#ef4444', weight: 5, opacity: 0.8,
      }).addTo(map);
      return;
    }

    const p = latLng(pickupName, pickupLat, pickupLng);
    const d = latLng(destinationName, destLat, destLng);
    if (!p || !d) return;
    fetchRoute(p, d).then((coords) => {
      if (cancelled || !mapRef.current) return;
      try {
        if (coords.length > 1) {
          routeLineRef.current = L.polyline(coords.map((c) => [c[1], c[0]] as [number, number]), {
            color: '#ef4444', weight: 5, opacity: 0.8,
          }).addTo(mapRef.current);
        } else {
          // 路線攞唔到都畫條直線兜底
          routeLineRef.current = L.polyline([[p[0], p[1]], [d[0], d[1]]], {
            color: '#ef4444', weight: 4, opacity: 0.6, dashArray: '6 8',
          }).addTo(mapRef.current);
        }
      } catch { /* Leaflet 內部 marker 定位偶發 error，忽略 */ }
    });
    return () => { cancelled = true; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isReady, showRoute, routePath, pickupName, destinationName, pickupLat, pickupLng, destLat, destLng]);

  if (loadError) {
    return (
      <div className={`relative w-full overflow-hidden rounded-2xl border border-slate-200/60 flex items-center justify-center bg-slate-900 ${height === 'auto' ? 'h-64' : height}`}>
        <div className="text-center px-6">
          <div className="size-12 rounded-full bg-red-500/10 flex items-center justify-center mx-auto mb-3">
            <AlertTriangle className="size-6 text-red-500" />
          </div>
          <p className="text-sm font-medium text-white mb-1">{t.common.amap.unavailable}</p>
          <p className="text-xs text-slate-400 max-w-xs mx-auto">{loadError}</p>
        </div>
      </div>
    );
  }

  return (
    <div
      ref={mapContainerRef}
      className={`relative w-full overflow-hidden rounded-2xl border border-slate-200/60 bg-slate-800 ${height === 'auto' ? 'h-64' : height}`}
      style={{ minHeight: '200px' }}
    >
      {!isReady && (
        <div className="absolute inset-0 flex items-center justify-center bg-slate-900 z-10">
          <div className="text-center">
            <div className="size-8 border-2 border-white/20 border-t-primary rounded-full animate-spin mx-auto mb-2" />
            <p className="text-xs text-slate-400">{t.common.amap.loading}</p>
          </div>
        </div>
      )}
      <style>{`.tx-divicon{background:transparent;border:none;}@keyframes txpulse{0%{box-shadow:0 0 0 0 rgba(0,0,0,0);}70%{box-shadow:0 0 0 14px rgba(239,68,68,0)}100%{box-shadow:0 0 0 0 rgba(0,0,0,0);}}`}</style>
    </div>
  );
}
