import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  ArrowLeft,
  Wallet,
  CreditCard,
  Building2,
  Check,
  Clock,
  X,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { toast } from 'sonner';
import { useI18n } from '@/lib/i18n';
import { useOrder } from '@/lib/order-context';

interface WithdrawRecord {
  id: string;
  amount: number;
  method: 'fps' | 'bank';
  status: 'pending' | 'success' | 'failed';
  date: string;
}

const MOCK_RECORDS: WithdrawRecord[] = [
  { id: 'WD001', amount: 3000, method: 'fps', status: 'success', date: '2026-09-20' },
  { id: 'WD002', amount: 2500, method: 'bank', status: 'success', date: '2026-09-12' },
  { id: 'WD003', amount: 1800, method: 'fps', status: 'pending', date: '2026-09-26' },
];

export default function DriverWalletPage() {
  const navigate = useNavigate();
  const { t, lang } = useI18n();
  const { historyOrders } = useOrder();
  const [withdrawOpen, setWithdrawOpen] = useState(false);
  const [withdrawMethod, setWithdrawMethod] = useState<'fps' | 'bank'>('fps');
  const [withdrawAmount, setWithdrawAmount] = useState('');
  const [withdrawing, setWithdrawing] = useState(false);

  const totalEarnings = 18560;
  const availableBalance = 2380;
  const totalOrders = historyOrders.length || 126;

  const handleWithdraw = async () => {
    const amt = parseFloat(withdrawAmount);
    if (!withdrawAmount || isNaN(amt) || amt <= 0) {
      toast.error(lang === 'zh-Hant' ? '請輸入有效金額' : lang === 'ja' ? '有効な金額を入力してください' : 'Please enter a valid amount');
      return;
    }
    if (amt > availableBalance) {
      toast.error(lang === 'zh-Hant' ? '提現金額超過可提現餘額' : lang === 'ja' ? '出金可能残高を超えています' : 'Amount exceeds available balance');
      return;
    }
    setWithdrawing(true);
    try {
      await new Promise((r) => setTimeout(r, 900));
      toast.success(t.driverWallet.withdrawSuccess);
      setWithdrawOpen(false);
      setWithdrawAmount('');
    } catch {
      toast.error(t.driverWallet.withdrawFailed);
    } finally {
      setWithdrawing(false);
    }
  };

  const methodLabel = (m: 'fps' | 'bank') =>
    m === 'fps' ? t.driverWallet.fps : t.driverWallet.bankAccount;

  const statusBadge = (s: 'pending' | 'success' | 'failed') => {
    if (s === 'success') {
      return (
        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-green-500/15 text-green-400 text-xs font-bold border border-green-500/30">
          <Check className="size-3" />
          {t.driverWallet.statusSuccess}
        </span>
      );
    }
    if (s === 'pending') {
      return (
        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-yellow-500/15 text-yellow-400 text-xs font-bold border border-yellow-500/30">
          <Clock className="size-3" />
          {t.driverWallet.statusPending}
        </span>
      );
    }
    return (
      <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-red-500/15 text-red-400 text-xs font-bold border border-red-500/30">
        <X className="size-3" />
        {t.driverWallet.statusFailed}
      </span>
    );
  };

  return (
    <div className="min-h-screen bg-black text-white flex flex-col">
      {/* 頂部導航 */}
      <div className="sticky top-0 z-40 bg-black/80 backdrop-blur-md border-b border-zinc-800">
        <div className="flex items-center h-14 px-4">
          <button
            onClick={() => navigate(-1)}
            className="size-10 rounded-full flex items-center justify-center hover:bg-zinc-800 transition-colors -ml-2"
            aria-label={t.common.back}
          >
            <ArrowLeft className="size-5 text-white" />
          </button>
          <h1 className="flex-1 text-center text-lg font-black -ml-10">
            {t.driverWallet.title}
          </h1>
          <div className="w-10" />
        </div>
      </div>

      <div className="px-4 py-5 space-y-5 flex-1">
        {/* 餘額大卡 */}
        <div className="rounded-2xl bg-gradient-to-br from-yellow-600 via-yellow-700 to-yellow-900 p-5 text-white shadow-xl">
          <div className="flex items-center gap-2 text-yellow-100 text-sm font-bold mb-2">
            <Wallet className="size-4" />
            {t.driverWallet.availableBalance}
          </div>
          <div className="text-4xl font-black tabular-nums mb-5">
            HK${availableBalance.toLocaleString()}
          </div>
          <div className="grid grid-cols-2 gap-4 pt-4 border-t border-yellow-400/20">
            <div>
              <div className="text-xs text-yellow-100/80 font-medium">{t.driverWallet.totalEarnings}</div>
              <div className="text-lg font-black tabular-nums mt-0.5">
                HK${totalEarnings.toLocaleString()}
              </div>
            </div>
            <div>
              <div className="text-xs text-yellow-100/80 font-medium">{t.driverWallet.totalOrders}</div>
              <div className="text-lg font-black tabular-nums mt-0.5">{totalOrders}</div>
            </div>
          </div>
        </div>

        {/* 提現按鈕 */}
        <Dialog open={withdrawOpen} onOpenChange={setWithdrawOpen}>
          <DialogTrigger asChild>
            <Button className="w-full h-12 rounded-2xl bg-yellow-500 hover:bg-yellow-400 text-black font-black text-base">
              {t.driverWallet.withdrawBtn}
            </Button>
          </DialogTrigger>
          <DialogContent className="bg-zinc-900 border border-zinc-700 text-white max-w-sm rounded-2xl">
            <DialogHeader>
              <DialogTitle className="text-xl font-bold text-white">
                {t.driverWallet.withdrawTitle}
              </DialogTitle>
              <DialogDescription className="text-zinc-400 text-sm">
                {t.driverWallet.availableBalance}: HK${availableBalance.toLocaleString()}
              </DialogDescription>
            </DialogHeader>

            <div className="space-y-4">
              {/* 提現方式 */}
              <div>
                <label className="text-sm font-bold text-zinc-300 mb-2 block">
                  {t.driverWallet.withdrawMethod}
                </label>
                <div className="grid grid-cols-2 gap-2">
                  <button
                    type="button"
                    onClick={() => setWithdrawMethod('fps')}
                    className={`flex items-center justify-center gap-2 py-3 rounded-xl border-2 font-bold transition-colors ${
                      withdrawMethod === 'fps'
                        ? 'border-yellow-500 bg-yellow-500/10 text-yellow-400'
                        : 'border-zinc-700 text-zinc-400 hover:border-zinc-600'
                    }`}
                  >
                    <CreditCard className="size-4" />
                    {t.driverWallet.fps}
                  </button>
                  <button
                    type="button"
                    onClick={() => setWithdrawMethod('bank')}
                    className={`flex items-center justify-center gap-2 py-3 rounded-xl border-2 font-bold transition-colors ${
                      withdrawMethod === 'bank'
                        ? 'border-yellow-500 bg-yellow-500/10 text-yellow-400'
                        : 'border-zinc-700 text-zinc-400 hover:border-zinc-600'
                    }`}
                  >
                    <Building2 className="size-4" />
                    {t.driverWallet.bankAccount}
                  </button>
                </div>
              </div>

              {/* 金額 */}
              <div>
                <label className="text-sm font-bold text-zinc-300 mb-2 block">
                  {t.driverWallet.withdrawAmount}
                </label>
                <Input
                  type="number"
                  value={withdrawAmount}
                  onChange={(e) => setWithdrawAmount(e.target.value)}
                  placeholder={t.driverWallet.amountPlaceholder}
                  className="bg-zinc-800 border-zinc-700 text-white h-12 font-bold text-lg"
                />
                <button
                  type="button"
                  onClick={() => setWithdrawAmount(String(availableBalance))}
                  className="text-xs text-yellow-400 font-bold mt-1.5 hover:text-yellow-300"
                >
                  {t.driverWallet.allIn}
                </button>
              </div>

              {/* 手續費 */}
              <div className="flex items-center justify-between text-sm text-zinc-400">
                <span>{t.driverWallet.fee}</span>
                <span className="text-green-400 font-bold">{t.driverWallet.feeFree}</span>
              </div>
            </div>

            <DialogFooter className="gap-2 sm:gap-2">
              <Button
                variant="outline"
                onClick={() => setWithdrawOpen(false)}
                className="bg-zinc-800 border-zinc-700 text-white hover:bg-zinc-700 mt-2 sm:mt-0"
              >
                {t.common.cancel}
              </Button>
              <Button
                onClick={handleWithdraw}
                disabled={withdrawing}
                className="bg-yellow-500 hover:bg-yellow-400 text-black"
              >
                {withdrawing ? t.driverWallet.withdrawing : t.driverWallet.confirmWithdraw}
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>

        {/* 提現記錄 */}
        <div>
          <h2 className="text-base font-bold text-white mb-3">
            {t.driverWallet.historyTitle}
          </h2>
          <div className="rounded-2xl bg-zinc-900 border border-zinc-800 overflow-hidden">
            {MOCK_RECORDS.map((r, i) => (
              <div
                key={r.id}
                className={`flex items-center gap-3 px-4 py-3.5 ${
                  i !== MOCK_RECORDS.length - 1 ? 'border-b border-zinc-800' : ''
                }`}
              >
                <div className="size-9 rounded-full bg-zinc-800 flex items-center justify-center shrink-0">
                  {r.method === 'fps' ? (
                    <CreditCard className="size-4 text-yellow-400" />
                  ) : (
                    <Building2 className="size-4 text-blue-400" />
                  )}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="text-sm font-bold text-white">
                    {methodLabel(r.method)}
                  </div>
                  <div className="text-xs text-zinc-500 mt-0.5">{r.date}</div>
                </div>
                <div className="text-right">
                  <div className="text-base font-black text-white tabular-nums">
                    -HK${r.amount.toLocaleString()}
                  </div>
                  <div className="mt-1">{statusBadge(r.status)}</div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}
