import { Star } from 'lucide-react';
import { useState } from 'react';
import { motion } from 'framer-motion';
import { useI18n } from '@/lib/i18n';

interface StarRatingProps {
  value: number;
  onChange?: (value: number) => void;
  size?: number;
  readonly?: boolean;
}

export default function StarRating({
  value,
  onChange,
  size = 32,
  readonly = false,
}: StarRatingProps) {
  const [hover, setHover] = useState(0);
  const { t } = useI18n();
  const display = hover || value;

  return (
    <div className="flex items-center gap-1">
      {[1, 2, 3, 4, 5].map((n) => (
        <button
          key={n}
          type="button"
          disabled={readonly}
          onMouseEnter={() => !readonly && setHover(n)}
          onMouseLeave={() => !readonly && setHover(0)}
          onClick={() => !readonly && onChange?.(n)}
          className={`${readonly ? 'cursor-default' : 'cursor-pointer'} transition-transform hover:scale-110 active:scale-95`}
          aria-label={t.common.starCount.replace('{count}', String(n))}
        >
          <motion.div
            key={display >= n ? `filled-${n}` : `empty-${n}`}
            initial={{ scale: 0.8, rotate: -10 }}
            animate={{ scale: 1, rotate: 0 }}
            transition={{ type: 'spring', stiffness: 400, damping: 15 }}
          >
            <Star
              size={size}
              className={
                display >= n
                  ? 'fill-amber-400 text-amber-400 stroke-amber-400'
                  : 'text-slate-300 stroke-slate-300'
              }
            />
          </motion.div>
        </button>
      ))}
    </div>
  );
}
