// Convert API order shape to local IOrder shape
/** 訂單校驗：舊版殘留／缺欄位資料一律補齊，防止出單後 crash */
function sanitizeOrder(raw: any): IOrder | null {
  if (!raw || typeof raw !== 'object') return null;
  const base: IOrder = {
    id: raw.id || `order_mock_${Date.now()}`,
    status: (raw.status as OrderStatus) || 'searching',
    pickup: {
      name: raw.pickup?.name || '上車點',
      lat: typeof raw.pickup?.lat === 'number' ? raw.pickup.lat : 0,
      lng: typeof raw.pickup?.lng === 'number' ? raw.pickup.lng : 0,
    },
    destination: {
      name: raw.destination?.name || '目的地',
      lat: typeof raw.destination?.lat === 'number' ? raw.destination.lat : 0,
      lng: typeof raw.destination?.lng === 'number' ? raw.destination.lng : 0,
    },
    carType: raw.carType === '6-seater' ? '6-seater' : '4-seater',
    carModel: raw.carModel,
    tip: raw.tip ?? 0,
    estimatedFare: raw.estimatedFare,
    actualFare: raw.actualFare,
    discount85: !!raw.discount85,
    passengerNotes: raw.passengerNotes,
    etaMinutes: raw.etaMinutes,
    distanceKm: raw.distanceKm,
    createdAt: raw.createdAt,
    taxiType: raw.taxiType === 'green' ? 'green' : 'red',
    fareExtras: raw.fareExtras,
    passengerCurrentLocation: raw.passengerCurrentLocation,
    messages: Array.isArray(raw.messages) ? raw.messages : [],
    driver: raw.driver
      ? {
          id: raw.driver.id ?? '',
          name: raw.driver.name ?? '司機',
          plate: raw.driver.plate ?? '',
          carModel: raw.driver.carModel,
          rating: raw.driver.rating,
          currentLat: raw.driver.currentLat,
          currentLng: raw.driver.currentLng,
          imageUrl: raw.driver.imageUrl ?? '',
          isVvip: raw.driver.isVvip,
        }
      : undefined,
    passenger: raw.passenger,
    dispatchPhase: raw.dispatchPhase,
    dispatchPhaseStartedAt: raw.dispatchPhaseStartedAt,
    dispatchUnlockedAt: raw.dispatchUnlockedAt,
    bookingTime: raw.bookingTime,
  };
  return base;
}

function apiOrderToLocal(apiOrder: any): IOrder {
  if (!apiOrder) return {} as IOrder;
  const carType: CarType = apiOrder.carType === '6pax' || apiOrder.carType === '6-seater' ? '6-seater' : '4-seater';
  const safePlace = (p: any) => ({
    name: p?.name || '上車點',
    lat: typeof p?.lat === 'number' ? p.lat : 0,
    lng: typeof p?.lng === 'number' ? p.lng : 0,
  });
  const pickup = apiOrder.pickup ? safePlace(apiOrder.pickup) : { name: '上車點', lat: 0, lng: 0 };
  const destination = apiOrder.destination ? safePlace(apiOrder.destination) : { name: '目的地', lat: 0, lng: 0 };
  const driver = apiOrder.driver
    ? {
        id: apiOrder.driver.id ?? '',
        name: apiOrder.driver.name ?? '司機',
        plate: apiOrder.driver.plate ?? '',
        carModel: apiOrder.driver.carModel,
        rating: apiOrder.driver.rating,
        currentLat: apiOrder.driver.currentLat,
        currentLng: apiOrder.driver.currentLng,
        imageUrl: '',
        isVvip: apiOrder.driver.isVvip,
      }
    : undefined;
  return {
    id: apiOrder.id,
    status: apiOrder.status as OrderStatus,
    pickup,
    destination,
    carType,
    carModel: apiOrder.carModel,
    tip: apiOrder.tipAmount ?? 0,
    estimatedFare: apiOrder.estimatedFare,
    actualFare: apiOrder.actualFare,
    discount85: apiOrder.hasDiscount,
    driver,
    passenger: apiOrder.passenger,
    etaMinutes: apiOrder.etaMinutes,
    distanceKm: apiOrder.distanceKm,
    createdAt: apiOrder.createdAt,
    driverRating: apiOrder.driverRating,
    passengerRating: apiOrder.passengerRating,
    taxiType: apiOrder.taxiType as 'red' | 'green',
    passengerNotes: apiOrder.passengerNotes,
    passengerCurrentLocation: apiOrder.passengerCurrentLocation,
    createdByDriver: !!apiOrder.createdByDriver,
    passengerPhone: apiOrder.passengerPhone ?? apiOrder.passenger?.phone,
    ownerDriverPhone: apiOrder.ownerDriverPhone || undefined,
    messages: [],
    dispatchPhase: apiOrder.dispatchPhase,
    dispatchPhaseStartedAt: apiOrder.dispatchPhaseStartedAt,
    dispatchUnlockedAt: apiOrder.dispatchUnlockedAt,
  };
}

export function OrderProvider({ children }: { children: ReactNode }) {
  const [order, setOrder] = useState<IOrder | null>(null);
  const [floodAlerts, setFloodAlerts] = useState<IFloodAlert[]>([]);
  const [hallOrders, setHallOrders] = useState<IOrder[]>([]);
  const [hallStats, setHallStats] = useState<{ rating?: number; acceptCount?: number; rejectCount?: number; rejectRate?: number } | null>(null);
  const [driverPostedOrders, setDriverPostedOrders] = useState<IOrder[]>([]);
  const [driverOnline, setDriverOnlineState] = useState<boolean>(() => {
    return scopedStorage.getItem(DRIVER_ONLINE_KEY) === 'true';
  });
  const [currentRole, setCurrentRoleState] = useState<'passenger' | 'driver' | 'admin'>(() => readRole());
  const [driverVerified, setDriverVerifiedState] = useState<boolean>(() => {
    return scopedStorage.getItem(DRIVER_VERIFIED_KEY) === 'true';
  });
  const [driverApplication, setDriverApplicationState] = useState<IDriverApplication | null>(() => readDriverApplication());
  const [driverApplications, setDriverApplicationsState] = useState<IDriverApplication[]>(() => readDriverApplications());
  const [driverIsVvip, setDriverIsVvip] = useState<boolean>(() => !!getStoredUser()?.is_vvip);
  const [driverVvipExpiresAt, setDriverVvipExpiresAt] = useState<number | null>(() => {
    const u = getStoredUser();
    return u?.vvip_expires_at ?? null;
  });
  const [driverLevel, setDriverLevel] = useState<'normal' | 'vip' | 'vvip'>(() => {
    const u = getStoredUser();
    return u?.is_vvip ? 'vvip' : u?.is_vip ? 'vip' : 'normal';
  });
  const [vvipApplied, setVvipApplied] = useState<boolean>(() => !!getStoredUser()?.vvip_applied);
  const [historyOrders, setHistoryOrders] = useState<IOrder[]>([]);
  // Boot 由 storage 還原 user（登入後 reload 唔會再變返 placeholder／「未完成驗證」）
  const [user, setUser] = useState<any>(() => getStoredUser());
  const [isLoggedIn, setIsLoggedIn] = useState<boolean>(!!getToken());

  const sseRef = useRef<EventSource | null>(null);
  const hallSseRef = useRef<EventSource | null>(null);

  // Sync role across tabs
  useEffect(() => {
    const syncRole = () => setCurrentRoleState(readRole());
    const syncApplication = () => setDriverApplicationState(readDriverApplication());
    const syncApplications = () => setDriverApplicationsState(readDriverApplications());
    window.addEventListener('hktaxi-role-updated', syncRole);
    window.addEventListener('hktaxi-application-updated', syncApplication);
    window.addEventListener('hktaxi-applications-updated', syncApplications);
    window.addEventListener('storage', (e) => {
      if (e.key?.includes('hktaxi_currentRole')) syncRole();
      if (e.key?.includes('hktaxi_driverApplication')) syncApplication();
      if (e.key?.includes('hktaxi_driverApplications')) syncApplications();
    });
    return () => {
      window.removeEventListener('hktaxi-role-updated', syncRole);
      window.removeEventListener('hktaxi-application-updated', syncApplication);
      window.removeEventListener('hktaxi-applications-updated', syncApplications);
    };
  }, []);

  // 司機心跳：喺線上狀態下每 60 秒更新 last_seen，令管理員後台「在線」判斷準確
  useEffect(() => {
    if (currentRole !== 'driver' || !driverOnline) return;
    let stopped = false;
    const tick = () => {
      if (stopped) return;
      import('@/lib/api').then(({ driverHeartbeat }) => driverHeartbeat());
    };
    tick();
    const t = window.setInterval(tick, 60000);
    return () => { stopped = true; window.clearInterval(t); };
  }, [currentRole, driverOnline]);

  // SSE subscription for order updates
  useEffect(() => {
    if (!order || order.status === 'finished' || order.status === 'cancelled') {
      if (sseRef.current) {
        sseRef.current.close();
        sseRef.current = null;
      }
      return;
    }

    // 訂閱要跟訂單走：換咗單就關舊 stream 再訂新嘅，避免訂咗舊單 stream，
    // 收到舊單事件將新單 order state 覆蓋返舊單（放棄 A → 接 B，畫面彈返 A 嘅 bug）
    if (sseRef.current && (sseRef.current as any).__orderId !== order.id) {
      sseRef.current.close();
      sseRef.current = null;
    }
    if (sseRef.current) return; // 已經訂緊同一張單
    try {
      const es = createOrderStream(order.id);
      (es as any).__orderId = order.id;
      sseRef.current = es;

      es.addEventListener('order-accepted', (e: any) => {
        const data = JSON.parse(e.data);
        setOrder((prev) => {
          if (prev && prev.id !== data.order?.id) return prev; // 唔准用錯單覆蓋
          return {
            ...apiOrderToLocal(data.order),
            messages: prev?.messages ?? [],
          };
        });
      });
      es.addEventListener('order-picked-up', (e: any) => {
        const data = JSON.parse(e.data);
        setOrder((prev) => {
          if (prev && prev.id !== data.order?.id) return prev;
          return {
            ...apiOrderToLocal(data.order),
            messages: prev?.messages ?? [],
          };
        });
      });
      es.addEventListener('order-completed', (e: any) => {
        const data = JSON.parse(e.data);
        setOrder((prev) => {
          if (prev && prev.id !== data.order?.id) return prev;
          return {
            ...apiOrderToLocal(data.order),
            messages: prev?.messages ?? [],
          };
        });
      });
      es.addEventListener('order-paid', (e: any) => {
        const data = JSON.parse(e.data);
        setOrder((prev) => {
          if (prev && prev.id !== data.order?.id) return prev;
          return {
            ...apiOrderToLocal(data.order),
            messages: prev?.messages ?? [],
          };
        });
      });
      es.addEventListener('order-cancelled', (e: any) => {
        const data = JSON.parse(e.data);
        setOrder((prev) => {
          // 只清同一張單；其他單取消唔會影響當前單
          if (prev && data.order && prev.id === data.order.id) return null;
          return prev;
        });
      });
      es.addEventListener('driver-location', (e: any) => {
        const data = JSON.parse(e.data);
        setOrder((prev) => {
          if (!prev || !prev.driver) return prev;
          // 位置冇變就唔重繪，避免畫面不停跳
          if (prev.driver.currentLat === data.lat && prev.driver.currentLng === data.lng) return prev;
          return {
            ...prev,
            driver: { ...prev.driver, currentLat: data.lat, currentLng: data.lng },
          };
        });
      });
      es.addEventListener('passenger-location', (e: any) => {
        // passenger location update - update UI if needed
        logger.info('passenger location update:', e.data);
      });
      es.addEventListener('new-message', (e: any) => {
        const data = JSON.parse(e.data);
        setOrder((prev) => {
          if (!prev) return prev;
          const msgs = prev.messages ?? [];
          if (msgs.some((m) => m.id === data.message.id)) return prev;
          return { ...prev, messages: [...msgs, data.message] };
        });
      });
      es.addEventListener('driver-rated', () => {
        refreshCurrentOrder();
      });
      es.addEventListener('passenger-rated', () => {
        refreshCurrentOrder();
      });
      es.addEventListener('flood-alert', (e: any) => {
        try {
          const alert: IFloodAlert = JSON.parse(e.data);
          setFloodAlerts((prev) => {
            if (prev.some((a) => a.id === alert.id)) return prev;
            const next = [...prev, alert];
            // 每段消息停留 1 分鐘後自動消失
            window.setTimeout(() => {
              setFloodAlerts((cur) => cur.filter((a) => a.id !== alert.id));
            }, 60000);
            return next;
          });
        } catch {
          // ignore malformed alert
        }
      });

       es.onerror = () => {
         // reconnect on error - EventSource auto-reconnects
       };
     } catch (err) {
       logger.warn('SSE connect failed, using localStorage polling fallback:', String(err));
     }

      // 本地 mock 兜底：定期輪詢 localStorage 中的訂單狀態（後端掛咗都可以雙端同步）
      const pollTimer = window.setInterval(() => {
        try {
          const raw = scopedStorage.getItem('hktaxi_currentOrder');
          if (raw) {
            const parsed = JSON.parse(raw) as IOrder;
            const updated = sanitizeOrder(parsed);
            if (!updated) return;
            // v2.0.85 修復「確認完成無限彈卡」：localStorage 殘留嘅已完成單唔會復活
            // （SSE fallback 唔應該將 paid/completed 舊單重新推返出嚟彈完成卡）
            if (updated.status === 'paid' || updated.status === 'completed') {
              try { scopedStorage.removeItem('hktaxi_currentOrder'); } catch { /* ignore */ }
              return;
            }
            setOrder((prev) => {
              // 只在狀態或關鍵字段變化時更新
              if (!prev) return updated;
              if (prev.id !== updated.id) return updated;
              // 唔准倒退：localStorage 多數係出單時寫入嘅舊 searching，
              // 唔好因為讀到舊 state 就將已 accepted/picked_up 嘅單覆蓋返 searching（導致乘客端收唔到接單）
              const prevStable = prev && (prev.status === 'accepted' || prev.status === 'picked_up' || prev.status === 'completed' || prev.status === 'paid');
              if (prevStable && updated.status === 'searching') return prev;
              if (prev.status !== updated.status) return updated;
              if (updated.driver && (!prev.driver || prev.driver.currentLat !== updated.driver.currentLat)) return updated;
              const prevMsgs = prev.messages?.length ?? 0;
              const updatedMsgs = updated.messages?.length ?? 0;
              if (updatedMsgs !== prevMsgs) return updated;
              return prev;
            });
          }
        } catch {
          // ignore
        }
      }, 1500);

     return () => {
       window.clearInterval(pollTimer);
       if (sseRef.current) {
         sseRef.current.close();
         sseRef.current = null;
       }
     };
   }, [order?.id, order?.status]);

  const refreshCurrentOrder = useCallback(async () => {
    try {
      const role = getStoredRole() || currentRole;
      let apiOrder: any = null;
      if (role === 'passenger') {
        apiOrder = await apiPassengerCurrent();
      } else if (role === 'driver') {
        apiOrder = await apiDriverCurrent();
      }
      if (apiOrder) {
        const local = apiOrderToLocal(apiOrder);
        // load messages
        try {
          const msgs = await getOrderMessages(local.id);
          local.messages = msgs;
        } catch { /* ignore */ }
        // 唔准倒退／唔准跳單：已 accepted/picked_up（接緊緊單），只准 refresh 同一張單，
        // 唔會因為 polling 攞到另一張（舊嘅 paid/completed 單）而覆蓋跳去「完成/評分」→ 無限彈
        setOrder((prev) => {
          if (prev && (prev.status === 'accepted' || prev.status === 'picked_up')) {
            return local.id === prev.id ? local : prev;
          }
          const stable = prev && (prev.status === 'completed' || prev.status === 'paid');
          if (stable && local.status === 'searching') return prev;
          return local;
        });
      } else {
        setOrder((prev) => {
          const stable = prev && (prev.status === 'accepted' || prev.status === 'picked_up' || prev.status === 'completed' || prev.status === 'paid');
          return stable ? prev : null;
        });
      }
    } catch (err) {
      logger.warn('refresh order failed, trying local fallback:', String(err));
      // 本地 mock 兜底：從 localStorage 讀當前訂單
      try {
        const raw = scopedStorage.getItem('hktaxi_currentOrder');
        if (raw) {
          const parsed = JSON.parse(raw) as IOrder;
          const local = sanitizeOrder(parsed);
          // v2.0.85 修復：fallback 都唔復活 paid/completed 已完成單（防止彈返完成卡）
          if (local.status === 'paid' || local.status === 'completed') {
            try { scopedStorage.removeItem('hktaxi_currentOrder'); } catch { /* ignore */ }
            return;
          }
          setOrder((prev) => {
            if (prev && (prev.status === 'accepted' || prev.status === 'picked_up')) {
              return local.id === prev.id ? local : prev;
            }
            const stable = prev && (prev.status === 'completed' || prev.status === 'paid');
            if (stable && local.status === 'searching') return prev;
            return local;
          });
        } else {
          setOrder((prev) => {
            const stable = prev && (prev.status === 'accepted' || prev.status === 'picked_up' || prev.status === 'completed' || prev.status === 'paid');
            return stable ? prev : null;
          });
        }
      } catch {
        setOrder((prev) => {
          const stable = prev && (prev.status === 'accepted' || prev.status === 'picked_up' || prev.status === 'completed' || prev.status === 'paid');
          return stable ? prev : null;
        });
      }
    }
  }, [currentRole]);

  // Polling 兜底：即使 SSE 斷咗，訂單狀態都定期同 server 同步，唔會「接咗單但 UI 卡死」
  useEffect(() => {
    if (!order || order.status === 'finished' || order.status === 'cancelled' || order.status === 'paid') return;
    const t = window.setInterval(() => { refreshCurrentOrder(); }, 12000);
    return () => window.clearInterval(t);
  }, [order?.id, order?.status, refreshCurrentOrder]);

  const refreshHallOrders = useCallback(async () => {
    // 先讀本地派單池（司機自己出嘅單一定喺度）
    let localList: IOrder[] = [];
    try {
      const raw = scopedStorage.getItem(LOCAL_HALL_KEY);
      if (raw) {
        localList = JSON.parse(raw).filter((o: IOrder) => o.status === 'searching');
      }
    } catch {
      localList = [];
    }

    // 過濾本地已拒絕嘅單（server 記咗 + 本地兜底，雙保險）
    let rejectedIds: string[] = [];
    try {
      const raw = scopedStorage.getItem('dikdou_rejected_orders');
      rejectedIds = raw ? JSON.parse(raw) : [];
    } catch { rejectedIds = []; }

    try {
      const data = await getDriverHallOrders();
      const apiOrders: IOrder[] = (data.orders || [])
        // 防禦：server 有機會返 null／undefined 元素，唔可以畀佢 crash 大廳
        .filter((o: any) => o && typeof o === 'object')
        .map(apiOrderToLocal)
        .filter((o: IOrder) => !rejectedIds.includes(o.id));
      // 合併 API 訂單 + 本地派單池，按 id 去重（本地優先）
      const merged = [...apiOrders];
      const seenIds = new Set(merged.map((o) => o.id));
      for (const lo of localList) {
        if (!seenIds.has(lo.id)) {
          merged.push(lo);
          seenIds.add(lo.id);
        }
      }
      setHallOrders(merged);
      // v2.0.78：順帶更新司機統計（評分/接單/拒單/拒單率）
      try { setHallStats(data.stats || null); } catch { /* ignore */ }
    } catch (err) {
      logger.warn('refresh hall failed, using local fallback:', String(err));
      setHallOrders(localList);
    }
  }, []);

  const refreshPostedOrders = useCallback(async () => {
    try {
      // 連網模式：讀 server「我出嘅單」（真實數據，唔會重複顯示）
      if (getToken()) {
        try {
          const serverOrders = await getDriverPostedOrders();
          const mapped = serverOrders.map((o: any) => apiOrderToLocal(o));
          // server 先係唯一真相——唔 merge localStorage（嗰啲可能係舊 fallback 假單，會誤導顯示重複）
          setDriverPostedOrders(mapped.sort((a: any, b: any) => b.createdAt - a.createdAt));
          return;
        } catch {
          // server 讀唔到就落返本地
        }
      }
      // 本地 mock 模式（離線/示範）
      const raw = scopedStorage.getItem(LOCAL_POSTED_KEY);
      if (raw) {
        const list: IOrder[] = JSON.parse(raw);
        // 24 小時後自動刪除過期單（淨係清 searching 未接嘅單）
        const expireBefore = Date.now() - 24 * 60 * 60 * 1000;
        const valid = list.filter((o) => (o.createdAt || 0) >= expireBefore);
        setDriverPostedOrders(valid.sort((a, b) => b.createdAt - a.createdAt));
        if (valid.length !== list.length) {
          scopedStorage.setItem(LOCAL_POSTED_KEY, JSON.stringify(valid));
        }
      } else {
        setDriverPostedOrders([]);
      }
    } catch {
      setDriverPostedOrders([]);
    }
  }, []);

  const createPostedOrder = useCallback(
    async (data: {
      pickup: ILatLng;
      destination: ILatLng;
      estimatedFare: number;
      carType: CarType;
      taxiType: 'red' | 'green';
      carModel?: CarModel;
      passengerNotes?: IPassengerNotes;
      passengerPhone?: string;
      bookingTime?: number;
      isDirect: 'standard' | 'discount85' | 'teishoku';
      tip?: number;
      dispatchPhase?: number;
      teishokuPrice?: number;
      distanceKm?: number; // 真實道路距離（公里），有就直接用，冇就用直線 × ROUTE_FACTOR 兜底
    }) => {
      // 優先用 caller 傳入嘅道路距離（通常係高德 Driving 返嘅真實距離）
      // 冇傳先至用 haversine 直線 × ROUTE_FACTOR 估算兜底
      const distanceKm = data.distanceKm && data.distanceKm > 0
        ? data.distanceKm
        : haversineKm(data.pickup, data.destination) * ROUTE_FACTOR;
      const newOrder: IOrder = {
        id: 'POST' + Math.random().toString(36).slice(2, 8).toUpperCase(),
        status: 'searching',
        pickup: data.pickup,
        destination: data.destination,
        carType: data.carType,
        carModel: data.carModel,
        tip: data.tip ?? 0,
        estimatedFare: data.estimatedFare,
        discount85: data.isDirect === 'discount85',
        passengerNotes: data.passengerNotes,
        taxiType: data.taxiType,
        createdAt: Date.now(),
        distanceKm,
        etaMinutes: Math.max(3, Math.round(distanceKm * 3)),
        createdByDriver: true,
        driverPostedFrom: user?.id || 'demo_driver',
        passengerPhone: data.passengerPhone,
        bookingTime: data.bookingTime,
        isDirect: data.isDirect,
        teishoku: data.isDirect === 'teishoku',
        teishokuPrice: data.teishokuPrice,
        dispatchPhase: data.dispatchPhase ?? (data.isDirect === 'discount85' ? 2 : data.isDirect === 'teishoku' ? 4 : 3),
        dispatchPhaseStartedAt: Date.now(),
        messages: [],
      };

      // 連網模式：有司機 token 就試吓上雲端（其他司機先接到；失敗就淨係本地）
      let finalOrder = newOrder;
      let cloudOk = false;
      if (getToken()) {
        try {
          const cloud = await postDriverOrder({
            pickup: {
              name: (data.pickup as any).name || '上車點',
              lat: data.pickup.lat,
              lng: data.pickup.lng,
            },
            destination: {
              name: (data.destination as any).name || '目的地',
              lat: data.destination.lat,
              lng: data.destination.lng,
            },
            carType: data.carType === '6-seater' ? '6pax' : '4pax',
            carModel: data.carModel,
            estimatedFare: data.estimatedFare,
            taxiType: data.taxiType,
            isDirect: data.isDirect,
            tip: data.tip ?? 0,
            dispatchPhase: data.dispatchPhase,
            teishokuPrice: data.teishokuPrice,
            passengerPhone: data.passengerPhone,
            passengerNotes: data.passengerNotes,
            distanceKm,
            etaMinutes: newOrder.etaMinutes,
          });
          if (cloud && cloud.id) {
            finalOrder = { ...newOrder, ...apiOrderToLocal(cloud), messages: [] };
            cloudOk = true;
          }
        } catch (err) {
          const msg = String((err as any)?.response?.data?.error || err);
          // server 擋咗重複出單（3分鐘防重）→ 唔好 fallback 寫本地假單，直接話俾司機知
          if (/唔可以重複|3分鐘|已經出過|重複出/.test(msg)) {
            throw new Error(msg);
          }
          // 其他 server 錯誤 → 本地兜底（離線/server down 都出到單）
          logger.warn('post driver order failed, local only:', msg);
        }
      }

      // 1. 寫入本地出貨記錄
      try {
        const raw = scopedStorage.getItem(LOCAL_POSTED_KEY);
        const list: IOrder[] = raw ? JSON.parse(raw) : [];
        list.push(finalOrder);
        scopedStorage.setItem(LOCAL_POSTED_KEY, JSON.stringify(list));
        setDriverPostedOrders((prev) => [finalOrder, ...prev]);
      } catch {
        setDriverPostedOrders((prev) => [finalOrder, ...prev]);
      }

      // 2. 同時寫入大廳，俾其他司機接（本地 mock 模式）
      //    server 成功（cloudOk）就唔寫——server 會自己廣播，避免本地大廳出現重複假單
      if (!cloudOk) {
        try {
          const raw = scopedStorage.getItem(LOCAL_HALL_KEY);
          const list: IOrder[] = raw ? JSON.parse(raw) : [];
          list.push(finalOrder);
          scopedStorage.setItem(LOCAL_HALL_KEY, JSON.stringify(list));
          setHallOrders((prev) => [...prev, finalOrder]);
          window.dispatchEvent(new CustomEvent('hktaxi-new-hall-order', { detail: finalOrder }));
        } catch {
          // ignore
        }
      }

      // v2.0.82：出貨成功後即刻同 server 對一次「我出嘅單」，
      // 確保「我出嘅單」列表即時顯示啱啱出嘅單（唔會停留喺 0）
      refreshPostedOrders().catch(() => { /* ignore */ });

      return finalOrder;
    },
    [user]
  );

  const cancelPostedOrder = useCallback(async (orderId: string) => {
    // 連網模式：順便取消雲端單（失敗都唔阻礙本地移除）
    if (getToken()) {
      try {
        await cancelPostedDriverOrder(orderId);
      } catch (err) {
        logger.warn('cancel posted order API failed:', String(err));
      }
    }
    // 從本地出貨記錄移除
    try {
      const raw = scopedStorage.getItem(LOCAL_POSTED_KEY);
      const list: IOrder[] = raw ? JSON.parse(raw) : [];
      const updated = list.filter((o) => o.id !== orderId);
      scopedStorage.setItem(LOCAL_POSTED_KEY, JSON.stringify(updated));
      setDriverPostedOrders(updated);
    } catch {
      setDriverPostedOrders((prev) => prev.filter((o) => o.id !== orderId));
    }
    // 同時從大廳移除
    try {
      const raw = scopedStorage.getItem(LOCAL_HALL_KEY);
      const list: IOrder[] = raw ? JSON.parse(raw) : [];
      const updated = list.filter((o) => o.id !== orderId);
      scopedStorage.setItem(LOCAL_HALL_KEY, JSON.stringify(updated));
      setHallOrders((prev) => prev.filter((o) => o.id !== orderId));
    } catch {
      setHallOrders((prev) => prev.filter((o) => o.id !== orderId));
    }
  }, []);

  const refreshHistory = useCallback(async () => {
    try {
      const role = getStoredRole() || currentRole;
      if (role === 'passenger') {
        const list = await getPassengerHistory();
        setHistoryOrders(list.map(apiOrderToLocal));
      } else if (role === 'driver') {
        // 用 /driver/history（含乘客電話，可以打返俾客）；攞唔到先跌返收入列表
        let list = [];
        try {
          list = await getDriverHistory();
        } catch {
          list = await getDriverEarnings();
        }
        setHistoryOrders(list.map(apiOrderToLocal));
      }
    } catch (err) {
      logger.warn('refresh history failed (expected in demo mode):', String(err));
    }
  }, [currentRole]);

  const createOrder = useCallback(
    async (
      pickup: ILatLng, destination: ILatLng, estimatedFare: number,
      carType: CarType, tip: number,
      extras?: { luggageCount: number; taxiTypeName: string; fareBreakdown?: IOrder['fareExtras']['fareBreakdown'] },
      discount85?: boolean,
      taxiType?: 'red' | 'green',
      carModel?: CarModel,
      passengerNotes?: IPassengerNotes,
      passengerGps?: { lat: number; lng: number },
      bookingTime?: number,
    ) => {
      try {
        const apiCarType = carType === '6-seater' ? '6pax' : '4pax';
        // 出單前計真實道路距離同 ETA（高德 Driving 無權限會 fallback OSRM；再唔得用直線 × ROUTE_FACTOR 兜底）
        let routeDist = 0;
        let routeEta = 0;
        try {
          const rr = await getDrivingRoute(pickup, destination);
          routeDist = Math.max(0.5, rr.distanceKm);
          routeEta = Math.max(3, Math.round(rr.durationSec / 60));
        } catch {
          routeDist = Math.max(0.5, haversineKm(pickup, destination) * ROUTE_FACTOR);
          routeEta = Math.max(3, Math.round(routeDist * 1.5));
        }
        const apiOrder = await apiRequestOrder({
          pickup, destination,
          carType: apiCarType,
          carModel,
          passengerNotes,
          hasDiscount: !!discount85,
          tipAmount: tip,
          estimatedFare,
          distanceKm: routeDist,
          etaMinutes: routeEta,
          taxiType: taxiType || 'red',
        });
        const local = apiOrderToLocal(apiOrder);
        if (extras) {
          local.fareExtras = {
            luggageCount: extras.luggageCount,
            taxiTypeName: extras.taxiTypeName,
            fareBreakdown: extras.fareBreakdown,
          };
        }
        if (carModel) local.carModel = carModel;
        if (passengerNotes) local.passengerNotes = passengerNotes;
        if (passengerGps) {
          local.passengerCurrentLocation = {
            lat: passengerGps.lat,
            lng: passengerGps.lng,
            usedGps: true,
            lastUpdated: Date.now(),
          };
        }
        setOrder(local);
        // 寫入 localStorage，雙端輪詢同步
        try {
          scopedStorage.setItem('hktaxi_currentOrder', JSON.stringify(local));
        } catch {
          // ignore
        }
      } catch (err: any) {
        // 已有進行中訂單：唔好 fallback mock，攞返 server 真實單令乘客端同 server 同步
        // （否則司機接咗 server 單，但乘客端停留喺 mock searching 永遠唔 update）
        const apiErr = err?.response?.data?.error || '';
        if (apiErr.includes('進行中')) {
          try {
            const active = await apiPassengerCurrent();
            if (active) {
              const local = apiOrderToLocal(active);
              setOrder(local);
              try { scopedStorage.setItem('hktaxi_currentOrder', JSON.stringify(local)); } catch { /* ignore */ }
              // 明確話畀用戶知係「進行中嘅單」而唔係派返上一個司機
              const dName = active.driver?.name || '';
              toast.error(`你已經有一單進行中${dName ? `（司機${dName}已接單）` : ''}，先完成或取消先可以再叫車`);
            }
          } catch { /* ignore */ }
          return;
        }
        // 用戶要求「唔可以有假數」：只要 server 有回應（任何 4xx/5xx，包括 401/400/500）都
        // 唔好 fallback mock 單，否則假單會入大廳派單池俾司機睇到、司機一接仲會 400。
        // 淨係真正網絡斷開（冇 server 回應，offline demo 模式）先行 mock 兜底。
        if (err?.response) {
          toast.error(apiErr || '叫車失敗，請稍後再試');
          return;
        }
        logger.warn('createOrder failed, falling back to local mock:', String(err));
        // 本地 mock 兜底：後端掛咗都可以正常叫車體驗
        const distanceKm = haversineKm(pickup, destination) * ROUTE_FACTOR;
        const mockOrder: IOrder = {
          id: `order_mock_${Date.now()}`,
          status: 'searching',
          pickup,
          destination,
          carType,
          carModel,
          tip,
          estimatedFare,
          discount85: !!discount85,
          passengerNotes,
          etaMinutes: Math.max(2, Math.round(distanceKm * 2)),
          distanceKm: Number(distanceKm.toFixed(1)),
          createdAt: Date.now(),
          taxiType: taxiType || 'red',
          fareExtras: extras
            ? {
                luggageCount: extras.luggageCount,
                taxiTypeName: extras.taxiTypeName,
                fareBreakdown: extras.fareBreakdown,
              }
            : undefined,
          passengerCurrentLocation: passengerGps
            ? {
                lat: passengerGps.lat,
                lng: passengerGps.lng,
                usedGps: true,
                lastUpdated: Date.now(),
              }
            : undefined,
          messages: [],
          bookingTime,
        };
        setOrder(mockOrder);
        // 本地 mock 模式：將訂單寫入 localStorage，雙端輪詢同步 + 大廳派單池
        try {
          scopedStorage.setItem('hktaxi_currentOrder', JSON.stringify(mockOrder));
          const raw = scopedStorage.getItem(LOCAL_HALL_KEY);
          const list: IOrder[] = raw ? JSON.parse(raw) : [];
          list.push(mockOrder);
          scopedStorage.setItem(LOCAL_HALL_KEY, JSON.stringify(list));
          // 通知其他頁面有新訂單
          window.dispatchEvent(new CustomEvent('hktaxi-new-hall-order', { detail: mockOrder }));
        } catch {
          // ignore
        }
      }
    },
    []
  );

  const acceptOrder = useCallback(
    async (driverId: string, orderId?: string) => {
      if (!hallOrders.length) {
        // 大廳列表已空：單可能已經俾人接走，明確報錯，唔好無聲 return（否則後續會 blind 導航去 riding 而嗰頁無單→彈走）
        throw new Error('張單可能已經俾人接咗，請重新整理');
      }
      // Find the target order by id, or fall back to first searching
      const target = orderId
        ? hallOrders.find((o) => o.id === orderId)
        : hallOrders.find((o) => o.status === 'searching');
      if (!target) {
        throw new Error('張單可能已經俾人接咗，請重新整理');
      }
      try {
        const apiOrder = await apiAcceptOrder(target.id);
        const local = apiOrderToLocal(apiOrder);
        setOrder(local);
        // Remove from hall
        setHallOrders((prev) => prev.filter((o) => o.id !== target.id));
      } catch (err) {
        // 連唔到 server 或 server 拒絕：一律唔用假司機 fallback，直接報錯（真實反映接單結果，唔會顯示「已接單」嘅假狀態）
        throw err;
      }
    },
    [hallOrders]
  );

  const rejectOrder = useCallback(async (orderId?: string) => {
    if (!hallOrders.length && !orderId) return;
    const target = orderId
      ? hallOrders.find((o) => o.id === orderId)
      : hallOrders[0];
    if (!target) return;

    // 1) 通知 server 記低拒單（之後唔會再派返俾我）
    try {
      await apiRejectOrder(target.id);
    } catch {
      logger.warn('rejectOrder notify failed, keeping local state:', String(err));
    }

    // 2) 本地永久記低：就算 refresh 都唔會再彈返出嚟
    const REJECT_KEY = 'dikdou_rejected_orders';
    try {
      const raw = scopedStorage.getItem(REJECT_KEY);
      const list: string[] = raw ? JSON.parse(raw) : [];
      if (!list.includes(target.id)) {
        list.push(target.id);
        scopedStorage.setItem(REJECT_KEY, JSON.stringify(list));
      }
    } catch { /* ignore */ }

    // 3) 即時移除大廳
    setHallOrders((prev) => prev.filter((o) => o.id !== target.id));
  }, [hallOrders]);

  const updateDriverPosition = useCallback((lat: number, lng: number, etaMinutes: number) => {
    // Update locally immediately for responsiveness
    setOrder((prev) => {
      if (!prev || !prev.driver) return prev;
      const updated = {
        ...prev,
        driver: { ...prev.driver, currentLat: lat, currentLng: lng },
        etaMinutes,
      };
      // 同步到 localStorage 供乘客端輪詢
      try { scopedStorage.setItem('hktaxi_currentOrder', JSON.stringify(updated)); } catch {}
      return updated;
    });
    // Fire-and-forget to server
    import('@/lib/api').then(({ updateDriverLocation }) => {
      updateDriverLocation(lat, lng, order?.id).catch(() => {});
    });
  }, [order?.id]);

  const markPickedUp = useCallback(async () => {
    try {
      const apiOrder = await driverArrivePickup();
      setOrder(apiOrderToLocal(apiOrder));
    } catch (err) {
      logger.warn('markPickedUp failed, falling back to local mock:', String(err));
      // 本地 mock 兜底
      setOrder((prev) => {
        if (!prev) return prev;
        const updated = { ...prev, status: 'picked_up' as const };
        try { scopedStorage.setItem('hktaxi_currentOrder', JSON.stringify(updated)); } catch {}
        return updated;
      });
    }
  }, []);

  const markCompleted = useCallback(async (actualFare: number) => {
    try {
      const apiOrder = await driverComplete(actualFare);
      setOrder(apiOrderToLocal(apiOrder));
    } catch (err) {
      logger.warn('markCompleted failed, falling back to local mock:', String(err));
      // 本地 mock 兜底
      setOrder((prev) => {
        if (!prev) return prev;
        const updated = {
          ...prev,
          status: 'completed' as const,
          actualFare,
        };
        try { scopedStorage.setItem('hktaxi_currentOrder', JSON.stringify(updated)); } catch {}
        return updated;
      });
    }
  }, []);

  const markPaid = useCallback(async (method: string) => {
    if (!order) return;
    const receiptNo = 'RCP' + Date.now().toString().slice(-10) + Math.random().toString(36).slice(2, 5).toUpperCase();
    const paidAt = Date.now();
    try {
      const apiOrder = await payOrder(order.id, method);
      const local = apiOrderToLocal(apiOrder);
      if (order.fareExtras) {
        local.fareExtras = { ...order.fareExtras, paymentMethod: method };
      }
      local.receiptNo = receiptNo;
      local.paidAt = paidAt;
      setOrder(local);
      // refresh history
      refreshHistory();
    } catch (err) {
      logger.warn('markPaid failed, falling back to local mock:', String(err));
      // 本地 mock 兜底
      setOrder((prev) => {
        if (!prev) return prev;
        const updated = {
          ...prev,
          status: 'paid' as const,
          fareExtras: prev.fareExtras ? { ...prev.fareExtras, paymentMethod: method } : undefined,
          receiptNo,
          paidAt,
        };
        try { scopedStorage.setItem('hktaxi_currentOrder', JSON.stringify(updated)); } catch {}
        return updated;
      });
    }
  }, [order, refreshHistory]);

  const markDriverCashPaid = useCallback(async (actualFare: number) => {
    if (!order) return;
    const receiptNo = 'RCP' + Date.now().toString().slice(-10) + Math.random().toString(36).slice(2, 5).toUpperCase();
    const paidAt = Date.now();
    try {
      const apiOrder = await driverCashPaid(order.id, actualFare);
      const local = apiOrderToLocal(apiOrder);
      local.receiptNo = receiptNo;
      local.paidAt = paidAt;
      setOrder(local);
      refreshHistory();
    } catch (err) {
      logger.warn('markDriverCashPaid failed, falling back to local mock:', String(err));
      setOrder((prev) => {
        if (!prev) return prev;
        const updated = {
          ...prev,
          status: 'paid' as const,
          actualFare: prev.actualFare ?? actualFare,
          fareExtras: prev.fareExtras ? { ...prev.fareExtras, paymentMethod: 'cash' } : { luggageCount: 0, taxiTypeName: prev.taxiType === 'green' ? '新界綠的' : '市區紅的', paymentMethod: 'cash' },
          receiptNo,
          paidAt,
        };
        try { scopedStorage.setItem('hktaxi_currentOrder', JSON.stringify(updated)); } catch {}
        window.dispatchEvent(new CustomEvent('hktaxi-order-updated', { detail: updated }));
        return updated;
      });
      // 同步寫入歷史（mock 兜底）
      refreshHistory();
    }
  }, [order, refreshHistory]);

  const submitDriverRating = useCallback(async (rating: number) => {
    if (!order) return;
    try {
      await apiRateDriver(order.id, rating);
      setOrder((prev) => prev ? { ...prev, driverRating: rating } : prev);
      refreshHistory();
    } catch (err) {
      logger.warn('submitDriverRating failed, falling back to local mock:', String(err));
      // 本地 mock 兜底
      setOrder((prev) => {
        if (!prev) return prev;
        const updated = { ...prev, driverRating: rating };
        try { scopedStorage.setItem('hktaxi_currentOrder', JSON.stringify(updated)); } catch {}
        return updated;
      });
    }
  }, [order, refreshHistory]);

  const submitPassengerRating = useCallback(async (rating: number, tags?: string[]) => {
    if (!order) return;
    try {
      await apiRatePassenger(order.id, rating);
      setOrder((prev) => prev ? { ...prev, passengerRating: rating } : prev);
      refreshHistory();
    } catch (err) {
      logger.warn('submitPassengerRating failed, falling back to local mock:', String(err));
      // 本地 mock 兜底
      setOrder((prev) => {
        if (!prev) return prev;
        const updated = { ...prev, passengerRating: rating, passengerRatingTags: tags || [] };
        try { scopedStorage.setItem('hktaxi_currentOrder', JSON.stringify(updated)); } catch {}
        return updated;
      });
    }
  }, [order, refreshHistory]);

  const submitComplaint = useCallback(async (data: { type: string; description: string }) => {
    if (!order) return;
    // 連 server 儲存投訴（管理員後台先睇到）
    try {
      await apiSubmitComplaint(order.id, data);
    } catch (e: any) {
      console.error('投訴上傳失敗', e?.message);
    }
    const complaint = {
      type: data.type,
      description: data.description,
      createdAt: Date.now(),
      status: 'pending' as const,
    };
    setOrder((prev) => {
      if (!prev) return prev;
      const updated = { ...prev, complaint };
      try { scopedStorage.setItem('hktaxi_currentOrder', JSON.stringify(updated)); } catch {}
      return updated;
    });
    // 同步到歷史記錄（乘客歷史）
    try {
      const raw = scopedStorage.getItem('hktaxi_passengerHistory');
      if (raw) {
        const list: IOrder[] = JSON.parse(raw);
        const idx = list.findIndex((o) => o.id === order.id);
        if (idx >= 0) {
          list[idx] = { ...list[idx], complaint };
          scopedStorage.setItem('hktaxi_passengerHistory', JSON.stringify(list));
        }
      }
    } catch { /* ignore */ }
    refreshHistory();
  }, [order, refreshHistory]);

  const resolveComplaint = useCallback(async (orderId: string, reply: string) => {
    // 管理員用：標記投訴已處理（連 server 更新）
    try {
      await apiResolveComplaint(orderId, reply);
    } catch (e: any) {
      console.error('投訴處理上傳失敗', e?.message);
    }
    // 本地同步
    try {
      const raw = scopedStorage.getItem('hktaxi_passengerHistory');
      if (raw) {
        const list: IOrder[] = JSON.parse(raw);
        const idx = list.findIndex((o) => o.id === orderId);
        if (idx >= 0 && list[idx].complaint) {
          list[idx].complaint = { ...list[idx].complaint!, status: 'resolved', reply };
          scopedStorage.setItem('hktaxi_passengerHistory', JSON.stringify(list));
        }
      }
    } catch { /* ignore */ }
    refreshHistory();
  }, [refreshHistory]);

  const getAllComplaints = useCallback(async (): Promise<IOrder[]> => {
    // 先攞 server 投訴（管理員後台跨裝置都睇到）
    try {
      const server = await apiGetComplaints();
      if (Array.isArray(server) && server.length > 0) {
        return (server as any[]).map((c: any) => ({
          id: c.id,
          status: c.status,
          passenger_id: c.passenger_id,
          driver_id: c.driver_id,
          pickup: { name: c.pickup_name },
          destination: { name: c.destination_name },
          estimatedFare: c.estimated_fare,
          actualFare: c.actual_fare,
          createdAt: c.created_at,
          complaint: c.complaint,
          complaintReply: c.reply,
        } as any));
      }
    } catch {
      // server 攞唔到先 fallback 本地（兼容）
    }
    try {
      const raw = scopedStorage.getItem('hktaxi_passengerHistory');
      if (!raw) return [];
      const list: IOrder[] = JSON.parse(raw);
      return list.filter((o) => o.complaint);
    } catch {
      return [];
    }
  }, []);

  const cancelOrder = useCallback(async () => {
    try {
      await apiCancelOrder();
      setOrder(null);
    } catch (err) {
      logger.warn('cancelOrder failed, falling back to local mock:', String(err));
      // 本地 mock 兜底：清空本地訂單 + 從大廳移除
      setOrder(null);
      try {
        scopedStorage.removeItem('hktaxi_currentOrder');
        const raw = scopedStorage.getItem(LOCAL_HALL_KEY);
        if (raw) {
          const list: IOrder[] = JSON.parse(raw);
          scopedStorage.setItem(
            LOCAL_HALL_KEY,
            JSON.stringify(list.filter((o) => o.status !== 'searching'))
          );
        }
      } catch {
        // ignore
      }
    }
  }, []);

  const driverCancelOrder = useCallback(async () => {
    if (!order) return;
    try {
      await driverCancelCurrentOrder();
      setOrder(null);
      refreshCurrentOrder();
    } catch (err) {
      logger.warn('driverCancelOrder failed, falling back to local mock:', String(err));
      // 本地 mock 兜底：將訂單改為 cancelled 狀態，放回大廳 search 狀態（俾其他司機接）
      const cancelled: IOrder = {
        ...order,
        status: 'searching',
        driver: undefined,
      };
      setOrder(null);
      try {
        // 從大廳移除舊嘅，再加返 search 狀態
        const raw = scopedStorage.getItem(LOCAL_HALL_KEY);
        const list: IOrder[] = raw ? JSON.parse(raw) : [];
        const filtered = list.filter((o) => o.id !== order.id);
        filtered.unshift(cancelled);
        scopedStorage.setItem(LOCAL_HALL_KEY, JSON.stringify(filtered));
        scopedStorage.removeItem('hktaxi_currentOrder');
        window.dispatchEvent(new CustomEvent('hktaxi-order-updated', { detail: cancelled }));
      } catch {
        // ignore
      }
    }
  }, [order]);

  const sendOrderMessage = useCallback(async (text: string, from: 'passenger' | 'driver') => {
    if (!order) return;
    const newMsg: IChatMessage = {
      id: 'local_' + Math.random().toString(36).slice(2, 8),
      text,
      from,
      timestamp: Date.now(),
    };
    try {
      if (from === 'passenger') {
        await sendPassengerMessage(order.id, text);
      } else {
        await sendDriverMessage(order.id, text);
      }
      // Optimistic update - SSE will also confirm
      setOrder((prev) => {
        if (!prev) return prev;
        return { ...prev, messages: [...(prev.messages ?? []), newMsg] };
      });
    } catch (err) {
      logger.warn('sendOrderMessage failed, using local fallback:', String(err));
      // 本地 mock 兜底：直接寫入 localStorage，雙端靠輪詢同步
      setOrder((prev) => {
        if (!prev) return prev;
        const updated = { ...prev, messages: [...(prev.messages ?? []), newMsg] };
        try {
          scopedStorage.setItem('hktaxi_currentOrder', JSON.stringify(updated));
        } catch {
          // ignore
        }
        return updated;
      });
    }
  }, [order]);

  const setDriverOnline = useCallback(async (online: boolean, lat?: number, lng?: number) => {
    try {
      await apiSetOnline(online, lat, lng);
      setDriverOnlineState(online);
      scopedStorage.setItem(DRIVER_ONLINE_KEY, String(online));
    } catch (err) {
      logger.warn('setDriverOnline failed, falling back to local mock:', String(err));
      // 本地 mock 兜底：直接更新狀態 + 寫 localStorage
      setDriverOnlineState(online);
      scopedStorage.setItem(DRIVER_ONLINE_KEY, String(online));
      window.dispatchEvent(new Event('hktaxi-driver-online-updated'));
    }
  }, []);

  const setCurrentRole = useCallback(async (role: 'passenger' | 'driver' | 'admin') => {
    setCurrentRoleState(role);
    writeRole(role);
    // 切換角色只係轉頁面，唔會自動登入示範帳號；要登入先用到
    window.dispatchEvent(new Event('hktaxi-order-updated'));
  }, []);

  const setDriverVerified = useCallback((verified: boolean) => {
    scopedStorage.setItem(DRIVER_VERIFIED_KEY, String(verified));
    setDriverVerifiedState(verified);
    window.dispatchEvent(new Event('hktaxi-driver-updated'));
  }, []);

  const submitDriverApplication = useCallback((data: { driverName: string; licenseNo: string; plate: string; carType: CarType }) => {
    const app: IDriverApplication = {
      id: genAppId(),
      driverName: data.driverName,
      licenseNo: data.licenseNo,
      plate: data.plate,
      carType: data.carType,
      status: 'pending',
      createdAt: Date.now(),
    };
    writeDriverApplication(app);
    const apps = readDriverApplications();
    const next = [app, ...apps];
    writeDriverApplications(next);
  }, []);

  const submitVvipApplication = useCallback(async () => {
    try {
      const { submitDriverVvipApplication } = await import('@/lib/api');
      const res = await submitDriverVvipApplication();
      if (res.user) {
        setDriverIsVvip(!!res.user.is_vvip);
        setDriverVvipExpiresAt(res.user.vvip_expires_at || null);
        setDriverLevel(res.user.is_vvip ? 'vvip' : res.user.is_vip ? 'vip' : 'normal');
        setVvipApplied(!!res.user.vvip_applied);
      }
      return;
    } catch (err: any) {
      logger.warn('vvip apply failed (expected in demo mode):', String(err));
      throw err;
    }
  }, []);

  const approveDriver = useCallback((applicationId: string) => {
    const apps = readDriverApplications();
    const idx = apps.findIndex((a) => a.id === applicationId);
    if (idx === -1) return;
    const updated: IDriverApplication = { ...apps[idx], status: 'approved', reviewedAt: Date.now() };
    apps[idx] = updated;
    writeDriverApplications(apps);
    const current = readDriverApplication();
    if (current && current.id === applicationId) {
      writeDriverApplication(updated);
      scopedStorage.setItem(DRIVER_VERIFIED_KEY, 'true');
      window.dispatchEvent(new Event('hktaxi-driver-updated'));
    }
  }, []);

  const rejectDriver = useCallback((applicationId: string, reason: string) => {
    const apps = readDriverApplications();
    const idx = apps.findIndex((a) => a.id === applicationId);
    if (idx === -1) return;
    const updated: IDriverApplication = { ...apps[idx], status: 'rejected', rejectReason: reason, reviewedAt: Date.now() };
    apps[idx] = updated;
    writeDriverApplications(apps);
    const current = readDriverApplication();
    if (current && current.id === applicationId) {
      writeDriverApplication(updated);
    }
  }, []);

  const refreshDriverApplications = useCallback(() => {
    setDriverApplicationsState(readDriverApplications());
  }, []);

  const resetToIdle = useCallback(() => {
    setOrder(null);
    // v2.0.85 修復「確認完成無限彈卡」：清埋 localStorage 殘留嘅已完成單，
    // 防止 SSE fallback / 重新登入又將佢復活，再彈返「確認完成」畫面
    try { scopedStorage.removeItem('hktaxi_currentOrder'); } catch { /* ignore */ }
  }, []);

  const resetDemoData = useCallback(() => {
    clearAuth();
    scopedStorage.removeItem(DRIVER_VERIFIED_KEY);
    scopedStorage.removeItem(DRIVER_APPLICATION_KEY);
    scopedStorage.removeItem(DRIVER_APPLICATIONS_KEY);
    setOrder(null);
    setDriverOnlineState(false);
    setDriverVerifiedState(false);
    setDriverApplicationState(null);
    setDriverApplicationsState([]);
    setHistoryOrders([]);
    setUser(null);
    setIsLoggedIn(false);
    window.dispatchEvent(new Event('hktaxi-order-updated'));
  }, []);

  const login = useCallback((role: 'passenger' | 'driver' | 'admin', userData: any, token: string) => {
    // Token 必須同步寫入 storage（setAuth 用頂部 sync import，唔再用 async import race），
    // 確保登入後緊接嘅 boot API call 一定攞到 token；否則 401 會清 token + 跳登入頁
    // →「登入後 reload 被踢／自動登出」。
    setAuth(token, userData, role);
    setUser(userData);
    setIsLoggedIn(true);
    setCurrentRoleState(role);
    writeRole(role);
    // For driver, set verified based on status
    if (role === 'driver') {
      const verified = userData.status === 'approved';
      scopedStorage.setItem(DRIVER_VERIFIED_KEY, String(verified));
      setDriverVerifiedState(verified);
      setDriverOnlineState(!!userData.online);
      setDriverIsVvip(!!userData.is_vvip);
      setDriverVvipExpiresAt(userData.vvip_expires_at || null);
      setDriverLevel(userData.is_vvip ? 'vvip' : userData.is_vip ? 'vip' : 'normal');
      setVvipApplied(!!userData.vvip_applied);
    }
  }, []);

  const demoLogin = useCallback(async (role: 'passenger' | 'driver', options?: { vvip?: boolean; level?: 'normal' | 'vip' | 'vvip' }) => {
    // 示範帳號已刪除：一律要真實登入
    throw new Error('示範登入已停用，請用真實帳號登入');
  }, []);

  const logout = useCallback(() => {
    clearAuth();
    setUser(null);
    setIsLoggedIn(false);
    setOrder(null);
    setHallOrders([]);
    setHistoryOrders([]);
    setDriverOnlineState(false);
    if (sseRef.current) { sseRef.current.close(); sseRef.current = null; }
    if (hallSseRef.current) { hallSseRef.current.close(); hallSseRef.current = null; }
  }, []);

  return (
    <OrderContext.Provider
      value={{
        order,
        driverOnline,
        currentRole,
        driverVerified,
        driverIsVvip,
        driverVvipExpiresAt,
        driverLevel,
        vvipApplied,
        driverApplication,
        driverApplications,
        historyOrders,
        hallOrders,
        hallStats,
        driverPostedOrders,
        floodAlerts,
        createPostedOrder,
        cancelPostedOrder,
        refreshPostedOrders,
        user,
        setUser,
        isLoggedIn,
        createOrder,
        acceptOrder,
        rejectOrder,
        updateDriverPosition,
        markPickedUp,
        markCompleted,
        markPaid,
        markDriverCashPaid,
        submitDriverRating,
        submitPassengerRating,
        submitComplaint,
        resolveComplaint,
        getAllComplaints,
        cancelOrder,
        driverCancelOrder,
        sendOrderMessage,
        setDriverOnline,
        setCurrentRole,
        setDriverVerified,
        submitDriverApplication,
        submitVvipApplication,
        approveDriver,
        rejectDriver,
        refreshDriverApplications,
        resetToIdle,
        resetDemoData,
        login,
        demoLogin,
        logout,
        refreshCurrentOrder,
        refreshHallOrders,
        refreshHistory,
      }}
    >
      {children}
    </OrderContext.Provider>
  );
}

export function useOrder() {
  const ctx = useContext(OrderContext);
  if (!ctx) throw new Error('useOrder must be used within OrderProvider');
  return ctx;
}
