// 共用音效模組
// 用單一 AudioContext + 首次用戶手勢解鎖，解決 iPhone Safari/WKWebView 自動播放限制
// （iOS 唔畀喺無用戶手勢下播聲，所以接貨有新單要 reuse 已解鎖嘅 ctx 先有聲）

let _ctx: AudioContext | null = null;

function getCtx(): AudioContext | null {
  if (_ctx) return _ctx;
  const C: any = window.AudioContext || (window as any).webkitAudioContext;
  if (!C) return null;
  try {
    _ctx = new C();
  } catch {
    return null;
  }
  return _ctx;
}

/** 解鎖 AudioContext（必須喺用戶手勢入面調用先有效；每次手勢都 resume，防止被 suspend 之後冇聲） */
export function unlockAudio() {
  const c = getCtx();
  if (!c) return;
  if (c.state === 'suspended') {
    c.resume().catch(() => { /* ignore */ });
  }
}

/** 新單水滴提示聲（1 下）—— 用已解鎖嘅 singleton ctx */
export function playWaterDrop() {
  const c = getCtx();
  if (!c) return;
  // 先嘗試解鎖／恢復（有啲瀏覽器會 suspend ctx，直接播會冇聲）
  if (c.state === 'suspended') {
    c.resume().catch(() => {});
  }
  if (c.state !== 'running') {
    // 等 resume 完成先播（微延遲兜底）
    setTimeout(() => {
      if (c.state === 'running') _playWaterDrop(c);
    }, 80);
    return;
  }
  _playWaterDrop(c);
}

function _playWaterDrop(c: AudioContext) {
  try {
    const now = c.currentTime;
    const osc = c.createOscillator();
    const gain = c.createGain();
    osc.type = 'sine';
    // 高頻滑落低頻＝水滴「叮」一聲
    osc.frequency.setValueAtTime(1900, now);
    osc.frequency.exponentialRampToValueAtTime(420, now + 0.16);
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(0.45, now + 0.02);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.28);
    osc.connect(gain);
    gain.connect(c.destination);
    osc.start(now);
    osc.stop(now + 0.32);
  } catch { /* ignore */ }
}

/**
 * 搶單成功音效（v2.0.78）——「叮咚」雙音：高→低兩個短音，清脆明確，
 * 用已解鎖嘅 singleton ctx，同水滴聲一致（iOS 亦播到）。
 */
export function playAcceptSuccess() {
  const c = getCtx();
  if (!c) return;
  if (c.state === 'suspended') {
    c.resume().catch(() => {});
  }
  if (c.state !== 'running') {
    setTimeout(() => {
      if (c.state === 'running') _playAcceptSuccess(c);
    }, 80);
    return;
  }
  _playAcceptSuccess(c);
}

function _playAcceptSuccess(c: AudioContext) {
  try {
    const now = c.currentTime;
    // 第一下：D5（587Hz）短促
    const o1 = c.createOscillator();
    const g1 = c.createGain();
    o1.type = 'sine';
    o1.frequency.setValueAtTime(587, now);
    g1.gain.setValueAtTime(0.0001, now);
    g1.gain.exponentialRampToValueAtTime(0.4, now + 0.02);
    g1.gain.exponentialRampToValueAtTime(0.0001, now + 0.16);
    o1.connect(g1);
    g1.connect(c.destination);
    o1.start(now);
    o1.stop(now + 0.18);
    // 第二下：G5（784Hz）稍高——「叮咚」完成感
    const o2 = c.createOscillator();
    const g2 = c.createGain();
    o2.type = 'sine';
    o2.frequency.setValueAtTime(784, now + 0.15);
    g2.gain.setValueAtTime(0.0001, now + 0.15);
    g2.gain.exponentialRampToValueAtTime(0.45, now + 0.17);
    g2.gain.exponentialRampToValueAtTime(0.0001, now + 0.42);
    o2.connect(g2);
    g2.connect(c.destination);
    o2.start(now + 0.15);
    o2.stop(now + 0.45);
  } catch { /* ignore */ }
}

// 首次用戶手勢（撳/點/打字）就解鎖；每次手勢都重新 resume，之後任何時刻播聲都得
if (typeof document !== 'undefined') {
  const unlock = () => unlockAudio();
  ['pointerdown', 'touchstart', 'click', 'keydown'].forEach((ev) => {
    document.addEventListener(ev, unlock, { passive: true });
  });
}

/**
 * 新單提示「海浪聲」（5 秒）
 * 用白噪聲 + 低通濾波 + 低頻起伏(LFO)合成海浪拍岸聲，
 * 純 Web Audio 生成，唔需要外部音效檔（免版權、PWA 一定播到）。
 */
export function playWave(durationSec = 5) {
  const c = getCtx();
  if (!c) return;
  // 先嘗試解鎖／恢復（防止 ctx 被 suspend 而冇聲）
  if (c.state === 'suspended') {
    c.resume().catch(() => {});
  }
  if (c.state !== 'running') {
    // 等 resume 完成先播（微延遲兜底）
    setTimeout(() => {
      if (c.state === 'running') _playWave(c, durationSec);
    }, 80);
    return;
  }
  _playWave(c, durationSec);
}

function _playWave(c: AudioContext, durationSec: number) {
  try {
    const now = c.currentTime;
    // 1. 白噪聲 buffer（5 秒）
    const len = Math.max(1, Math.floor(c.sampleRate * durationSec));
    const buffer = c.createBuffer(1, len, c.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    const src = c.createBufferSource();
    src.buffer = buffer;
    src.loop = true;

    // 2. 低通濾波 → 海浪「沙沙」基底
    const filter = c.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(430, now);
    filter.frequency.linearRampToValueAtTime(300, now + durationSec); // 波浪逐步變沉
    filter.Q.value = 0.55;

    // 3. 主音量（淡入 + 淡出）
    const gain = c.createGain();
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.linearRampToValueAtTime(0.26, now + 0.9);          // 淡入
    gain.gain.setValueAtTime(0.26, now + durationSec - 1);       // 保持
    gain.gain.linearRampToValueAtTime(0.0001, now + durationSec);// 淡出

    // 4. LFO 低頻起伏 → 海浪拍岸節奏（約 0.28Hz ≈ 每 3.5 秒一波）
    const lfo = c.createOscillator();
    const lfoGain = c.createGain();
    lfo.frequency.value = 0.28;
    lfoGain.gain.value = 0.22;
    lfo.connect(lfoGain);
    lfoGain.connect(gain.gain);

    src.connect(filter);
    filter.connect(gain);
    gain.connect(c.destination);
    src.start(now);
    lfo.start(now);
    src.stop(now + durationSec);
    lfo.stop(now + durationSec);
  } catch { /* ignore */ }
}
