import { useState, useRef, useEffect, useCallback, type FormEvent } from 'react';
import { X, Send, Phone, PhoneOff, MessageCircle } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { toast } from 'sonner';
import { useOrder } from '@/lib/order-context';
import { logger } from '@/lib/standalone-shim';
import VvipBadge from '@/components/VvipBadge';
import { useI18n } from '@/lib/i18n';

interface ChatSheetProps {
  open: boolean;
  onClose: () => void;
  role: 'passenger' | 'driver';
  otherName: string;
  otherAvatar?: string;
  otherIsVvip?: boolean;
}

export default function ChatSheet({ open, onClose, role, otherName, otherAvatar, otherIsVvip }: ChatSheetProps) {
  const { order, sendOrderMessage } = useOrder();
  const { t } = useI18n();
  const [inputValue, setInputValue] = useState('');
  const [showCallDialog, setShowCallDialog] = useState(false);
  const [callDuration, setCallDuration] = useState(0);
  const listRef = useRef<HTMLDivElement>(null);
  const callTimerRef = useRef<number | null>(null);

  const messages = order?.messages ?? [];
  const isDriver = role === 'driver';

  useEffect(() => {
    if (listRef.current) {
      listRef.current.scrollTop = listRef.current.scrollHeight;
    }
  }, [messages.length, open]);

  useEffect(() => {
    if (!open) {
      setInputValue('');
      setShowCallDialog(false);
      if (callTimerRef.current) {
        window.clearInterval(callTimerRef.current);
        callTimerRef.current = null;
      }
      setCallDuration(0);
    }
  }, [open]);

  const handleSend = useCallback(
    async (e: FormEvent) => {
      e.preventDefault();
      const text = inputValue.trim();
      if (!text || !order) return;
      try {
        await sendOrderMessage(text, role);
        setInputValue('');
      } catch (err) {
        logger.warn('sendOrderMessage failed:', String(err));
        toast.error(t.chat.sendFailed);
      }
    },
    [inputValue, order, role, sendOrderMessage, t]
  );

  const quickReplies = t.chat.quickReplies[role];

  const sendQuick = async (text: string) => {
    if (!order) return;
    try {
      await sendOrderMessage(text, role);
    } catch (err) {
      logger.warn('sendQuick failed:', String(err));
      toast.error(t.chat.sendFailed);
    }
  };

  const handleCall = () => {
    setShowCallDialog(true);
    setCallDuration(0);
    toast.info(t.chat.calling.replace('{name}', otherName));
    callTimerRef.current = window.setInterval(() => {
      setCallDuration((d) => d + 1);
    }, 1000);
  };

  const handleHangUp = () => {
    if (callTimerRef.current) {
      window.clearInterval(callTimerRef.current);
      callTimerRef.current = null;
    }
    setShowCallDialog(false);
    toast.success(t.chat.hangupToast);
  };

  const formatDuration = (s: number) => {
    const m = Math.floor(s / 60);
    const sec = s % 60;
    return `${m.toString().padStart(2, '0')}:${sec.toString().padStart(2, '0')}`;
  };

  const otherInitial = otherName?.slice(0, 1) ?? '?';

  // 司機端黑金大字風格 class 變體
  const driverBg = isDriver ? 'bg-zinc-900' : 'bg-white';
  const driverBorder = isDriver ? 'border-zinc-700' : 'border-slate-100';
  const driverText = isDriver ? 'text-white' : 'text-foreground';
  const driverMuted = isDriver ? 'text-zinc-400' : 'text-muted-foreground';
  const driverMsgBg = isDriver
    ? 'bg-yellow-500 text-black rounded-br-md'
    : 'bg-primary text-white rounded-br-md';
  const driverOtherBg = isDriver
    ? 'bg-zinc-800 border border-zinc-700 text-white rounded-bl-md'
    : 'bg-white border border-slate-200 text-foreground rounded-bl-md';
  const driverListBg = isDriver ? 'bg-black' : 'bg-slate-50/50';
  const driverInputBg = isDriver ? 'bg-zinc-800 text-white placeholder:text-zinc-500' : 'bg-slate-100 text-sm text-foreground placeholder:text-muted-foreground';
  const driverQuickBg = isDriver
    ? 'bg-zinc-800 border border-zinc-700 text-white hover:bg-zinc-700 hover:border-zinc-600'
    : 'bg-white border border-slate-200 text-foreground hover:bg-slate-50 hover:border-slate-300';

  return (
    <>
      <AnimatePresence>
        {open && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 bg-black/40 backdrop-blur-sm flex items-end"
            onClick={onClose}
          >
            <motion.div
              initial={{ y: '100%' }}
              animate={{ y: 0 }}
              exit={{ y: '100%' }}
              transition={{ type: 'spring', damping: 25, stiffness: 300 }}
              className={`w-full ${driverBg} rounded-t-3xl max-h-[80vh] flex flex-col`}
              onClick={(e) => e.stopPropagation()}
            >
              {/* Header */}
              <div className={`p-4 border-b ${driverBorder} flex items-center gap-3`}>
                <div className={`size-12 rounded-full ${isDriver ? 'bg-yellow-500/20 text-yellow-400' : 'bg-primary/10 text-primary'} flex items-center justify-center shrink-0 font-bold`}>
                  {otherInitial}
                </div>
                <div className="flex-1 min-w-0">
                  <div className={`font-bold flex items-center gap-1.5 flex-wrap ${isDriver ? 'text-white text-lg' : 'text-foreground text-sm'}`}>
                    {otherName}
                    {otherIsVvip && <VvipBadge size="sm" />}
                  </div>
                  <div className={`${isDriver ? 'text-sm text-zinc-400' : 'text-xs text-muted-foreground'} flex items-center gap-1`}>
                    <span className="size-2 rounded-full bg-green-500" />
                    {t.chat.online}
                  </div>
                </div>
                <button
                  onClick={handleCall}
                  className={`size-12 rounded-full ${isDriver ? 'bg-green-500/20 hover:bg-green-500/30' : 'bg-green-50 hover:bg-green-100'} flex items-center justify-center shrink-0 transition-colors`}
                  aria-label={t.chat.callAria}
                >
                  <Phone className={isDriver ? 'size-6 text-green-400' : 'size-4 text-green-600'} />
                </button>
                <button
                  onClick={onClose}
                  className={`size-12 rounded-full ${isDriver ? 'bg-zinc-800 hover:bg-zinc-700' : 'bg-slate-100 hover:bg-slate-200'} flex items-center justify-center shrink-0 transition-colors`}
                  aria-label={t.chat.closeAria}
                >
                  <X className={isDriver ? 'size-6 text-zinc-400' : 'size-4 text-slate-500'} />
                </button>
              </div>

              {/* Messages */}
              <div
                ref={listRef}
                className={`flex-1 overflow-y-auto p-4 space-y-3 ${driverListBg}`}
              >
                {messages.length === 0 && (
                  <div className="text-center py-8">
                    <div className={`size-16 rounded-full ${isDriver ? 'bg-zinc-800' : 'bg-slate-100'} flex items-center justify-center mx-auto mb-3`}>
                      <MessageCircle className={isDriver ? 'size-8 text-zinc-600' : 'size-6 text-slate-400'} />
                    </div>
                    <div className={isDriver ? 'text-base text-zinc-500' : 'text-xs text-muted-foreground'}>
                      {t.chat.empty}
                    </div>
                  </div>
                )}
                {messages.map((msg) => {
                  const isMine = msg.from === role;
                  return (
                    <div
                      key={msg.id}
                      className={`flex ${isMine ? 'justify-end' : 'justify-start'}`}
                    >
                      <div
                        className={`max-w-[75%] px-4 py-3 rounded-2xl ${isDriver ? driverMsgBg : driverOtherBg} ${isDriver ? 'text-base' : 'text-sm'}`}
                      >
                        <div className="leading-relaxed break-words">{msg.text}</div>
                        <div
                          className={`text-xs mt-1 ${
                            isMine
                              ? isDriver
                                ? 'text-black/60'
                                : 'text-white/70'
                              : driverMuted
                          }`}
                        >
                          {new Date(msg.timestamp).toLocaleTimeString('zh-HK', {
                            hour: '2-digit',
                            minute: '2-digit',
                          })}
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>

              {/* Quick replies */}
              <div className={`px-3 pt-2 flex gap-2 overflow-x-auto no-scrollbar ${isDriver ? 'bg-zinc-900' : 'bg-transparent'}`}>
                {quickReplies.map((q) => (
                  <button
                    key={q}
                    onClick={() => sendQuick(q)}
                    className={`shrink-0 px-4 py-2 rounded-full transition-colors ${driverQuickBg} ${isDriver ? 'text-sm font-bold' : 'text-xs'}`}
                  >
                    {q}
                  </button>
                ))}
              </div>

              {/* Input */}
              <form
                onSubmit={handleSend}
                className={`p-3 border-t ${driverBorder} flex items-center gap-2 ${isDriver ? 'bg-zinc-900' : 'bg-transparent'}`}
              >
                <input
                  type="text"
                  value={inputValue}
                  onChange={(e) => setInputValue(e.target.value)}
                  placeholder={t.chat.placeholder}
                  className={`flex-1 ${isDriver ? 'h-12 text-base pl-5' : 'h-10 text-sm pl-4'} rounded-full ${driverInputBg} focus:outline-none focus:ring-2 focus:ring-yellow-500/40 focus:bg-white transition-all`}
                />
                <button
                  type="submit"
                  disabled={!inputValue.trim()}
                  className={`${isDriver ? 'size-12' : 'size-10'} rounded-full ${isDriver ? 'bg-yellow-500 text-black hover:bg-yellow-400' : 'bg-primary text-white hover:bg-primary/90'} flex items-center justify-center shrink-0 disabled:opacity-50 disabled:cursor-not-allowed transition-colors`}
                  aria-label={t.chat.sendAria}
                >
                  <Send className={isDriver ? 'size-5' : 'size-4'} />
                </button>
              </form>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* 通話中 Dialog - 司機端大字 */}
      <AnimatePresence>
        {showCallDialog && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-[60] bg-black/80 backdrop-blur-md flex items-center justify-center"
          >
            <motion.div
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              className="text-center text-white"
            >
              <div className={`${isDriver ? 'size-32' : 'size-24'} rounded-full bg-green-500/20 flex items-center justify-center mx-auto mb-5 animate-pulse`}>
                <div className={`${isDriver ? 'size-24' : 'size-16'} rounded-full bg-green-500/30 flex items-center justify-center`}>
                  <Phone className={isDriver ? 'size-10 text-green-400' : 'size-7 text-green-400'} />
                </div>
              </div>
              <div className={`${isDriver ? 'text-2xl font-black' : 'text-lg font-semibold'} mb-1`}>{otherName}</div>
              <div className={`${isDriver ? 'text-lg' : 'text-sm'} text-white/60 mb-1`}>
                {callDuration === 0 ? t.chat.callingStatus : t.chat.onCall}
              </div>
              {callDuration > 0 && (
                <div className={`${isDriver ? 'text-base' : 'text-xs'} text-white/50 tabular-nums mb-6`}>
                  {formatDuration(callDuration)}
                </div>
              )}
              {callDuration === 0 && <div className={`${isDriver ? 'h-8' : 'h-6'} mb-6`} />}
              <button
                onClick={handleHangUp}
                className={`${isDriver ? 'size-16' : 'size-14'} rounded-full bg-red-500 flex items-center justify-center mx-auto hover:bg-red-600 transition-colors shadow-lg shadow-red-500/30`}
                aria-label={t.chat.hangupAria}
              >
                <PhoneOff className={isDriver ? 'size-7 text-white' : 'size-6 text-white'} />
              </button>
              <div className={`${isDriver ? 'text-sm mt-2' : 'text-xs mt-2'} text-white/40`}>{t.chat.hangupAria}</div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
}
