// Web Push 推播訂閱：司機允許通知後註冊，即使 app 喺後台／鎖屏都收到新單推送
import { getToken } from './api';

const SW_PATH = '/sw.js';

export function isPushSupported(): boolean {
  try {
    return (
      typeof window !== 'undefined' &&
      'serviceWorker' in navigator &&
      'PushManager' in window &&
      'Notification' in window
    );
  } catch {
    return false;
  }
}

export async function getExistingSubscription(): Promise<PushSubscription | null> {
  try {
    const reg = await navigator.serviceWorker.getRegistration();
    if (!reg || !reg.pushManager) return null;
    return await reg.pushManager.getSubscription();
  } catch {
    return null;
  }
}

// 訂閱（並上傳俾 server）
export async function subscribeToPush(): Promise<{ status: 'ok' | 'denied' | 'unsupported' | 'error'; detail?: string }> {
  try {
    if (!isPushSupported()) return { status: 'unsupported', detail: '此瀏覽器唔支援推播通知（要加到主畫面先得）' };

    // 註冊 Service Worker
    const reg = await navigator.serviceWorker.register(SW_PATH).catch(() => navigator.serviceWorker.getRegistration());
    if (!reg) return { status: 'error', detail: 'Service Worker 註冊失敗' };

    // 請求通知權限
    const permission = await Notification.requestPermission();
    if (permission !== 'granted') return { status: 'denied', detail: '用戶未允許通知' };

    // 訂閱
    let sub = await reg.pushManager.getSubscription();
    if (!sub) {
      const vapidKey = await fetchVapidKey();
      if (!vapidKey) return { status: 'error', detail: '攞唔到推送設定' };
      sub = await reg.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: urlBase64ToUint8Array(vapidKey),
      });
    }

    // 上傳俾 server
    const token = getToken();
    const payload = {
      subscription: {
        endpoint: sub.endpoint,
        keys: sub.toJSON().keys || {},
      },
    };
    const res = await fetch(`/api/push/subscribe`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}) },
      body: JSON.stringify(payload),
    });
    if (!res.ok) return { status: 'error', detail: '上傳訂閱失敗' };
    return { status: 'ok' };
  } catch (e: any) {
    return { status: 'error', detail: e?.message || String(e) };
  }
}

// 退訂（用戶關閉通知時）
export async function unsubscribeFromPush(): Promise<void> {
  try {
    const sub = await getExistingSubscription();
    if (sub) {
      const token = getToken();
      await fetch(`/api/push/unsubscribe`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}) },
        body: JSON.stringify({ endpoint: sub.endpoint }),
      }).catch(() => {});
      await sub.unsubscribe().catch(() => {});
    }
  } catch { /* 靜默 */ }
}

async function fetchVapidKey(): Promise<string | null> {
  try {
    const res = await fetch('/api/push/config', { headers: { 'Content-Type': 'application/json' } });
    const data = await res.json();
    return data?.vapidPublicKey || null;
  } catch {
    return null;
  }
}

function urlBase64ToUint8Array(base64String: string): Uint8Array {
  const padding = '='.repeat((4 - (base64String.length % 4)) % 4);
  const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
  const rawData = window.atob(base64);
  const outputArray = new Uint8Array(rawData.length);
  for (let i = 0; i < rawData.length; ++i) {
    outputArray[i] = rawData.charCodeAt(i);
  }
  return outputArray;
}
