// 去重：以 sc 為 key，後面嘅覆蓋前面（保留最後一個）
const SC_TO_TC_MAP: Record<string, string> = {};
for (const [sc, tc] of SC_TO_TC) {
  SC_TO_TC_MAP[sc] = tc;
}

// 建立反向映射（繁 → 簡），以 tc 為 key
const TC_TO_SC_MAP: Record<string, string> = {};
for (const [sc, tc] of SC_TO_TC) {
  // 避免同一 tc 對應多個 sc 嘅覆蓋問題，只保留第一次
  if (!TC_TO_SC_MAP[tc]) {
    TC_TO_SC_MAP[tc] = sc;
  }
}

/**
 * 簡體字轉繁體字（輕量版，針對香港地名搜尋）
 * 優先匹配長詞（2字以上），再匹配單字，避免「千色」被拆開轉錯
 */
export function scToTc(text: string): string {
  if (!text) return text;
  let result = text;

  // 先處理 2 字以上短語（按長度降序）
  const phrases = Object.keys(SC_TO_TC_MAP).filter((k) => k.length >= 2).sort((a, b) => b.length - a.length);
  for (const phrase of phrases) {
    if (result.includes(phrase)) {
      result = result.split(phrase).join(SC_TO_TC_MAP[phrase]);
    }
  }

  // 再處理單字
  let final = '';
  for (let i = 0; i < result.length; i++) {
    const char = result[i];
    final += SC_TO_TC_MAP[char] ?? char;
  }
  return final;
}

/**
 * 繁體字轉簡體字（輕量版）
 */
export function tcToSc(text: string): string {
  if (!text) return text;
  let result = text;

  const phrases = Object.keys(TC_TO_SC_MAP).filter((k) => k.length >= 2).sort((a, b) => b.length - a.length);
  for (const phrase of phrases) {
    if (result.includes(phrase)) {
      result = result.split(phrase).join(TC_TO_SC_MAP[phrase]);
    }
  }

  let final = '';
  for (let i = 0; i < result.length; i++) {
    const char = result[i];
    final += TC_TO_SC_MAP[char] ?? char;
  }
  return final;
}

/**
 * 粗略判斷輸入是否偏向簡體字
 * 用於顯示提示等非關鍵場景
 */
export function probablySimplified(text: string): boolean {
  if (!text) return false;
  let scWeight = 0;
  let tcWeight = 0;
  for (const char of text) {
    const tcOfSc = SC_TO_TC_MAP[char];
    if (tcOfSc && tcOfSc !== char) {
      scWeight += 1; // 係簡體字
    }
    const scOfTc = TC_TO_SC_MAP[char];
    if (scOfTc && scOfTc !== char) {
      tcWeight += 1; // 係繁體字
    }
  }
  return scWeight > 0 && scWeight >= tcWeight;
}
