// 出貨表單組件
function PostOrderSheet({ open, onClose, onSuccess }: { open: boolean; onClose: () => void; onSuccess: (orderId?: string) => void }) {
  const { createPostedOrder } = useOrder();
  const [submitting, setSubmitting] = useState(false);

  // 表單狀態
  const [pickupInput, setPickupInput] = useState('');
  const [destInput, setDestInput] = useState('');
  const [pickupLandmark, setPickupLandmark] = useState<ILandmark | null>(null);
  const [destLandmark, setDestLandmark] = useState<ILandmark | null>(null);
  const [showPickupResults, setShowPickupResults] = useState(false);
  const [showDestResults, setShowDestResults] = useState(false);
  const [pickupFocus, setPickupFocus] = useState(false);
  const [destFocus, setDestFocus] = useState(false);

  const [taxiType, setTaxiType] = useState<'red' | 'green'>('red');
  const [carType, setCarType] = useState<'4-seater' | '6-seater'>('4-seater');
  const [carModel, setCarModel] = useState<string>('');
  const [passengerPhone, setPassengerPhone] = useState('');
  const [notes, setNotes] = useState('');
  const [bookingMode, setBookingMode] = useState<'now' | 'later'>('now');
  const [bookingDate, setBookingDate] = useState('');
  const [bookingTimeVal, setBookingTimeVal] = useState('');
  const [selectedDiscount, setSelectedDiscount] = useState<'standard' | '90' | '85' | 'teishoku'>('standard');
  const [teishokuPrice, setTeishokuPrice] = useState<string>('');
  const [tipAmount, setTipAmount] = useState<number>(0);
  const [customTip, setCustomTip] = useState('');
  const [showCustomTip, setShowCustomTip] = useState(false);
  const [extras, setExtras] = useState({
    ePayment: false,
    receipt: false,
    doubleTunnel: false,
    pet: false,
  });

  // 語音落單：用咪講「上車點／目的地」，或者一個制講「X去Y」自動填起點+終點
  const [listeningFor, setListeningFor] = useState<'pickup' | 'dest' | 'route' | 'voice-order' | null>(null);
  const listeningCancelRef = useRef<(() => void) | null>(null);
  // 語音出單進行中鎖：防止一次辨識出多次結果（interim+final）或連撳 Mic 造成重複出單
  const voiceOrderBusyRef = useRef(false);
  // 語音出單成功標記：成功後 10 秒鎖（TTS 無聲用戶以為失敗再講多次 → 擋住）
  const voiceOrderSuccessRef = useRef(false);

  // 大 Mic 一鍵語音出單：講「地點去地點」（例如「元朗千色去粉嶺工地」）直接生成張單
  const startVoiceOrder = () => {
    // 撳 Mic 嗰一刻就係用戶手勢 → 預先喚醒語音引擎，之後 API 成功播報先出到聲
    unlockSpeech();
    // 上一張語音單仲處理緊 → 擋住，唔好重複出單
    if (voiceOrderBusyRef.current) {
      toast.info('上一張單處理緊，請等一等');
      return;
    }
    // 瀏覽器唔支援 → 提示，唔係靜默無反應
    if (!speechRecognitionSupported()) {
      toast.error('此瀏覽器唔支援語音出單（請用 Chrome 或手機瀏覽器）');
      return;
    }
    // 清返之前未結束嘅
    if (listeningCancelRef.current) {
      listeningCancelRef.current();
      listeningCancelRef.current = null;
    }
    setListeningFor('voice-order');
    const cancel = startListening({
      onResult: async (text) => {
        // 已經有一張語音單處理緊（同一次辨識可能出多次結果）→ 擋住，防止重複出單
        if (voiceOrderBusyRef.current) return;
        voiceOrderBusyRef.current = true;
        const rawT = text.trim();
        // v2.0.79：語音折扣偵測——講「85折/八五折/9折/九折」自動帶入張單
        let voiceDiscount: 'standard' | 'discount85' | 'discount90' = 'standard';
        if (/(85折|八五折|85\s*折)/.test(rawT)) voiceDiscount = 'discount85';
        else if (/(9折|九折|9\s*折)/.test(rawT)) voiceDiscount = 'discount90';
        // 剷走折扣字眼再 split 起點終點，避免「八五折」黐住地址
        const t = rawT.replace(/(85折|八五折|85\s*折|9折|九折|9\s*折)/g, ' ').trim();
        // 「元朗千色去粉嶺工地」→ split 起點終點
        const m = t.match(/^(.+?)(?:去|到|至|往|➡️|->|→)(.+)$/);
        if (!m || !m[1].trim() || !m[2].trim()) {
          voiceOrderBusyRef.current = false;
          toast.error('聽唔清楚，請講「地點去地點」，例如「元朗千色去粉嶺工地」');
          return;
        }
        const pkName = m[1].trim();
        const dtName = m[2].trim();
        // 折扣最終值：語音有講用語音；冇講就繼承表單揀咗嘅折扣（85折/9折）
        const finalDiscount: 'standard' | 'discount85' | 'discount90' =
          voiceDiscount !== 'standard'
            ? voiceDiscount
            : selectedDiscount === '85' ? 'discount85'
            : selectedDiscount === '90' ? 'discount90'
            : 'standard';
        // 車型偵測：講「綠的」用綠的、「6人車」用6人車，其餘默認紅的4人車
        const taxiGuess: 'red' | 'green' = /(綠的|新界綠的)/.test(t) ? 'green' : 'red';
        const carGuess: '4-seater' | '6-seater' = /(6人|六人|6座)/.test(t) ? '6-seater' : '4-seater';
        setSubmitting(true);
        try {
          // 兩個地點一齊查座標（並行），慳一半時間
          const [pkRaw, dtRaw] = await Promise.all([
            resolveWithGeo(pkName, null),
            resolveWithGeo(dtName, null),
          ]);
          // v2.0.79：保留語音原文地址名（例如「天水圍天悅」），
          // 唔好用解析後嘅簡化區域名（「天水圍」）覆蓋，顯示詳細啲
          const pk = pkRaw ? { ...pkRaw, name: pkName } : pkRaw;
          const dt = dtRaw ? { ...dtRaw, name: dtName } : dtRaw;
          let postFare = 0;
          let distKm = 0;
          if (pk?.lat && dt?.lat) {
            distKm = estimateRoadDistanceKm(pk as any, dt as any);
            const taxiTypeKey: 'urban' | 'nt' = taxiGuess === 'green' ? 'nt' : 'urban';
            postFare = calcFareByDistance(distKm, taxiTypeKey, {
              tip: 0,
              isDirectDiscount: finalDiscount,
            }).total;
          }
          const posted = await createPostedOrder({
            pickup: pk as any,
            destination: dt as any,
            estimatedFare: postFare,
            carType: carGuess,
            taxiType: taxiGuess,
            distanceKm: distKm > 0 ? distKm : undefined,
            passengerPhone: passengerPhone || undefined,
            isDirect: finalDiscount,
          });
          const carLabel = carGuess === '6-seater' ? '6人車' : '4人車';
          const discTxt = finalDiscount === 'discount85' ? '，85折' : finalDiscount === 'discount90' ? '，9折' : '';
          toast.success(`✅ 已出單！${pkName}去${dtName}${discTxt}（${taxiGuess === 'green' ? '新界綠的' : '市區紅的'}${carLabel}）`);
          // 出完單即時語音回饋「已出單」＋震動提示（手機 TTS 無聲都知成功咗）
          try {
            const speakDisc = finalDiscount === 'discount85' ? '，八五折' : finalDiscount === 'discount90' ? '，九折' : '';
            speak(`已出單，${pkName}去${dtName}${speakDisc}`);
          } catch { /* ignore */ }
          try { navigator.vibrate?.(250); } catch { /* ignore */ }
          // 成功後 10 秒內鎖住語音出單——防止「TTS 無聲以為冇出到再講多次」造成重複出單
          voiceOrderSuccessRef.current = true;
          setTimeout(() => {
            voiceOrderBusyRef.current = false;
            voiceOrderSuccessRef.current = false;
          }, 10000);
          // 出完單清表單，方便再出
          setPickupInput('');
          setDestInput('');
          setPickupLandmark(null);
          setDestLandmark(null);
        } catch (apiErr) {
          logger.warn('語音出單 API failed:', String(apiErr));
          toast.error('出單失敗：' + String(apiErr));
          voiceOrderBusyRef.current = false; // 失敗即刻解鎖，可以再試
        }
        setSubmitting(false);
      },
      onEnd: () => {
        setListeningFor(null);
        listeningCancelRef.current = null;
        // 如果已經成功出單（等緊 10 秒鎖），唔好即刻解鎖；否則解鎖
        if (!voiceOrderSuccessRef.current) voiceOrderBusyRef.current = false;
      },
      onError: (err) => {
        setListeningFor(null);
        // 失敗場景：即刻解鎖（除非啱啱成功出咗單）
        if (!voiceOrderSuccessRef.current) voiceOrderBusyRef.current = false;
        // 權限被拒／無 mic → 明確提示（唔係靜默無反應）
        if (err === 'not-allowed' || err === 'service-not-allowed') {
          toast.error('請允許咪高峰權限先可以用語音出單（瀏覽器／系統設定）');
        } else if (err === 'no-speech') {
          toast.info('冇聽到聲音，再試一次');
        } else if (err !== 'aborted') {
          toast.error('語音辨識失敗：' + err);
        }
      },
    });
    listeningCancelRef.current = cancel || null;
    // cancel 返 null = 即時失敗（例如無 mic 裝置）
    if (!cancel) {
      toast.error('無法啟動語音辨識（請檢查咪高峰權限）');
    }
  };

  // 開始語音辨識（target 係 'pickup' / 'dest' / 'route'）
  const startVoiceInput = (target: 'pickup' | 'dest' | 'route') => {
    // 瀏覽器唔支援 → 提示，唔係靜默無反應
    if (!speechRecognitionSupported()) {
      toast.error('此瀏覽器唔支援語音輸入（請用 Chrome 或手機瀏覽器）');
      return;
    }
    // 清返之前未結束嘅
    if (listeningCancelRef.current) {
      listeningCancelRef.current();
      listeningCancelRef.current = null;
    }
    setListeningFor(target);
    const cancel = startListening({
      onResult: (text) => {
        if (target === 'route') {
          // 一個制講「X去Y」→ split 起點終點
          const t = text.trim();
          // 常見分隔詞：去／到／->／至／往
          const m = t.match(/^(.+?)(?:去|到|至|往|➡️|->|→)(.+)$/);
          if (m && m[1].trim() && m[2].trim()) {
            setPickupInput(m[1].trim());
            setPickupLandmark(null);
            setShowPickupResults(false);
            setDestInput(m[2].trim());
            setDestLandmark(null);
            setShowDestResults(false);
            toast.success(`已聽取：${m[1].trim()} 去 ${m[2].trim()}`);
          } else {
            // 冇分隔詞 → 當淨係講咗上車點
            setPickupInput(t);
            setPickupLandmark(null);
            setShowPickupResults(false);
            toast.info('只聽到上車點，講「地點去地點」可以一次填晒');
          }
        } else if (target === 'pickup') {
          setPickupInput(text);
          setPickupLandmark(null);
          setShowPickupResults(false);
        } else {
          setDestInput(text);
          setDestLandmark(null);
          setShowDestResults(false);
        }
      },
      onEnd: () => {
        setListeningFor(null);
        listeningCancelRef.current = null;
      },
      onError: (err) => {
        setListeningFor(null);
        // 權限被拒／無 mic → 明確提示（唔係靜默無反應）
        if (err === 'not-allowed' || err === 'service-not-allowed') {
          toast.error('請允許咪高峰權限先可以用語音落單（瀏覽器／系統設定）');
        } else if (err === 'no-speech') {
          toast.info('冇聽到聲音，再試一次');
        } else if (err !== 'aborted') {
          toast.error('語音辨識失敗：' + err);
        }
      },
    });
    listeningCancelRef.current = cancel || null;
    // cancel 返 null = 即時失敗（例如無 mic 裝置）
    if (!cancel) {
      toast.error('無法啟動語音辨識（請檢查咪高峰權限）');
    }
  };

  // 搜尋地標（支援簡體／繁體／英文名匹配）
  const pickupResults = useMemo(() => {
    const kw = pickupInput.trim();
    if (!kw) return [];
    const tcKw = scToTc(kw);
    const scKw = tcToSc(kw);
    const lowerKw = kw.toLowerCase();
    const lowerTc = tcKw.toLowerCase();
    const lowerSc = scKw.toLowerCase();
    const matched = MOCK_LANDMARKS.filter((l) => {
      const name = l.name;
      const lowerName = name.toLowerCase();
      const lowerEn = l.enName?.toLowerCase() ?? '';
      return (
        name.includes(tcKw) ||
        name.includes(scKw) ||
        name.includes(kw) ||
        lowerName.includes(lowerTc) ||
        lowerName.includes(lowerSc) ||
        lowerName.includes(lowerKw) ||
        (lowerEn && (lowerEn.includes(lowerKw) || lowerEn.includes(lowerTc) || lowerEn.includes(lowerSc))) ||
        l.district.includes(tcKw) ||
        l.district.includes(scKw)
      );
    });
    // 優先排序：前綴匹配 > 中文名包含 > 英文名匹配 > 地區匹配
    const sorted = [...matched].sort((a, b) => {
      const score = (l: typeof matched[number]) => {
        let s = 0;
        const lowerName = l.name.toLowerCase();
        const lowerEn = l.enName?.toLowerCase() ?? '';
        if (l.name.startsWith(tcKw) || l.name.startsWith(scKw) || l.name.startsWith(kw)) s += 100;
        if (lowerName.includes(lowerTc) || lowerName.includes(lowerSc)) s += 50;
        if (lowerEn.includes(lowerKw)) s += 30;
        if (l.district.includes(tcKw)) s += 10;
        return s;
      };
      return score(b) - score(a);
    });
    return sorted.slice(0, 12);
  }, [pickupInput]);

  const destResults = useMemo(() => {
    const kw = destInput.trim();
    if (!kw) return [];
    const tcKw = scToTc(kw);
    const scKw = tcToSc(kw);
    const lowerKw = kw.toLowerCase();
    const lowerTc = tcKw.toLowerCase();
    const lowerSc = scKw.toLowerCase();
    const matched = MOCK_LANDMARKS.filter((l) => {
      const name = l.name;
      const lowerName = name.toLowerCase();
      const lowerEn = l.enName?.toLowerCase() ?? '';
      return (
        name.includes(tcKw) ||
        name.includes(scKw) ||
        name.includes(kw) ||
        lowerName.includes(lowerTc) ||
        lowerName.includes(lowerSc) ||
        lowerName.includes(lowerKw) ||
        (lowerEn && (lowerEn.includes(lowerKw) || lowerEn.includes(lowerTc) || lowerEn.includes(lowerSc))) ||
        l.district.includes(tcKw) ||
        l.district.includes(scKw)
      );
    });
    const sorted = [...matched].sort((a, b) => {
      const score = (l: typeof matched[number]) => {
        let s = 0;
        const lowerName = l.name.toLowerCase();
        const lowerEn = l.enName?.toLowerCase() ?? '';
        if (l.name.startsWith(tcKw) || l.name.startsWith(scKw) || l.name.startsWith(kw)) s += 100;
        if (lowerName.includes(lowerTc) || lowerName.includes(lowerSc)) s += 50;
        if (lowerEn.includes(lowerKw)) s += 30;
        if (l.district.includes(tcKw)) s += 10;
        return s;
      };
      return score(b) - score(a);
    });
    return sorted.slice(0, 12);
  }, [destInput]);

  // 估算車費（原價）
  // 道路距離（公里）：初始用估算，AMap Driving 成功後替換成真實值
  const [roadDistanceKm, setRoadDistanceKm] = useState<number>(0);

  // 將輸入 resolve 成真實地標座標（用同一份搜尋邏輯，確保車費計算同 UI 列表一致）
  const resolveLandmarkFromInput = (input: string): { name: string; lat: number; lng: number; matched: true } | null => {
    const trimmed = input.trim();
    if (!trimmed) return null;
    const tcKw = scToTc(trimmed);
    const scKw = tcToSc(trimmed);
    const lowerKw = trimmed.toLowerCase();
    const lowerTc = tcKw.toLowerCase();
    const lowerSc = scKw.toLowerCase();
    // 先試精確頭部匹配
    let best = MOCK_LANDMARKS.find((l) => l.name === tcKw || l.name === scKw || l.name === trimmed);
    if (best) return { name: best.name, lat: best.lat, lng: best.lng, matched: true };
    // 再試前綴匹配
    best = MOCK_LANDMARKS.find(
      (l) => l.name.startsWith(tcKw) || l.name.startsWith(scKw) || l.name.startsWith(trimmed),
    );
    if (best) return { name: best.name, lat: best.lat, lng: best.lng, matched: true };
    // 最後試包含匹配
    best = MOCK_LANDMARKS.find((l) => {
      const lowerName = l.name.toLowerCase();
      const lowerEn = l.enName?.toLowerCase() ?? '';
      return (
        l.name.includes(tcKw) ||
        l.name.includes(scKw) ||
        lowerName.includes(lowerTc) ||
        lowerName.includes(lowerSc) ||
        lowerName.includes(lowerKw) ||
        lowerEn.includes(lowerKw) ||
        lowerEn.includes(lowerTc)
      );
    });
    if (best) return { name: best.name, lat: best.lat, lng: best.lng, matched: true };
    return null;
  };

  const resolvedPickup = useMemo(() => {
    if (pickupLandmark) return { name: pickupLandmark.name, lat: pickupLandmark.lat, lng: pickupLandmark.lng, matched: true };
    return resolveLandmarkFromInput(pickupInput);
  }, [pickupLandmark, pickupInput]);

  const resolvedDest = useMemo(() => {
    if (destLandmark) return { name: destLandmark.name, lat: destLandmark.lat, lng: destLandmark.lng, matched: true };
    return resolveLandmarkFromInput(destInput);
  }, [destLandmark, destInput]);

  const baseFare = useMemo(() => {
    const pk = resolvedPickup;
    const dt = resolvedDest;
    if (!pk || !dt) return 0;
    // 出貨單：用穩定估算距離計費（避免揀完地點後真實道路距離返嚟令價錢跳動）
    const distKm = estimateRoadDistanceKm(pk, dt);
    const taxiTypeKey: 'urban' | 'nt' | 'lantau' = taxiType === 'green' ? 'nt' : 'urban';
    const { total } = calcFareByDistance(distKm, taxiTypeKey, {
      // baseFare 係原價，唔計折扣同貼士（discount 同 tip 後面再加）
    });
    return total;
  }, [resolvedPickup, resolvedDest, taxiType, carType]);

  // 起訖點變時重新拉取道路距離
  useEffect(() => {
    const pk = resolvedPickup;
    const dt = resolvedDest;
    if (!pk || !dt) {
      setRoadDistanceKm(0);
      return;
    }

    let cancelled = false;

    // 即刻用估算值
    const estimated = estimateRoadDistanceKm(pk, dt);
    setRoadDistanceKm(estimated);

    // 嘗試用高德 Driving 拿真實道路距離
    getDrivingDistanceKm(pk, dt)
      .then((realKm) => {
        if (!cancelled) {
          setRoadDistanceKm(realKm);
        }
      })
      .catch(() => {
        // 失敗就保持估算值
      });

    return () => {
      cancelled = true;
    };
  }, [resolvedPickup, resolvedDest]);

  const teishokuFare = useMemo(() => {
    if (selectedDiscount !== 'teishoku') return 0;
    const n = parseInt(teishokuPrice, 10);
    return Number.isFinite(n) && n > 0 ? n : 0;
  }, [selectedDiscount, teishokuPrice]);

  const canSubmit = useMemo(() => {
    if (!pickupInput.trim() || !destInput.trim()) return false;
    if (bookingMode === 'later') {
      if (!bookingDate || !bookingTimeVal) return false;
    }
    if (selectedDiscount === 'teishoku' && teishokuFare <= 0) return false;
    return true;
  }, [pickupInput, destInput, bookingMode, bookingDate, bookingTimeVal, selectedDiscount, teishokuFare]);

  const discountRate = useMemo(() => {
    if (selectedDiscount === 'teishoku') return 1; // 定食唔打折，車費直接用輸入金額
    if (selectedDiscount === '90') return 0.9;
    if (selectedDiscount === '85') return 0.85;
    return 1;
  }, [selectedDiscount]);

  const estimatedFare = useMemo(() => {
    if (selectedDiscount === 'teishoku') return teishokuFare + tipAmount;
    return Math.round(baseFare * discountRate) + tipAmount;
  }, [baseFare, discountRate, tipAmount, selectedDiscount, teishokuFare]);

  const resolveLandmark = (input: string, landmark: ILandmark | null): { name: string; lat?: number; lng?: number } => {
    if (landmark) return { name: landmark.name, lat: landmark.lat, lng: landmark.lng };
    const trimmed = input.trim();
    if (!trimmed) return { name: '自訂地址' };
    // 嘗試模糊匹配第一個地標
    const match = MOCK_LANDMARKS.find((l) => l.name.includes(trimmed) || trimmed.includes(l.name));
    if (match) return { name: match.name, lat: match.lat, lng: match.lng };
    // 兜底：冇座標（跳錶）——唔用假座標，caller 會試高德 Geocoder
    return { name: trimmed };
  };

  // 解析地點：本地地標 → 高德 Geocoder 真座標 → 冇座標（跳錶）
  const resolveWithGeo = async (input: string, landmark: ILandmark | null) => {
    const lm = resolveLandmark(input, landmark);
    if (lm?.lat && lm?.lng) return lm;
    const geo = await amapGeocode(input);
    if (geo) return { name: lm.name, lat: geo.lat, lng: geo.lng };
    return lm; // 冇座標 → 跳錶
  };

  const handleSubmit = async () => {
    const missing: string[] = [];
    if (!pickupInput.trim()) missing.push('上車地點');
    if (!destInput.trim()) missing.push('目的地');
    if (bookingMode === 'later') {
      if (!bookingDate) missing.push('預約日期');
      if (!bookingTimeVal) missing.push('預約時間');
    }
    if (selectedDiscount === 'teishoku' && teishokuFare <= 0) {
      missing.push('定食價');
    }
    if (missing.length > 0) {
      toast.error(`仲未填：${missing.join('、')}`);
      return;
    }
    setSubmitting(true);
    // v2.0.83：posted 用外層 let——server 失敗 fallback 之後 onSuccess 都可以攞到單 id
    // （之前 const 喺內層 try scope，onSuccess 讀會 ReferenceError → 出單「無反應」）
    let posted: { id?: string } | null = null;
    // v2.0.87：成功語音回饋用嘅地點名（pk/dt 喺內層 scope，外層要自記）
    let finalPkName = '';
    let finalDtName = '';
    try {
      const bookingTs = bookingMode === 'later' && bookingDate && bookingTimeVal
        ? new Date(`${bookingDate}T${bookingTimeVal}`).getTime()
        : undefined;
      try {
        const pk = await resolveWithGeo(pickupInput, pickupLandmark);
        const dt = await resolveWithGeo(destInput, destLandmark);
        finalPkName = pk?.name || '';
        finalDtName = dt?.name || '';
          let postFare = estimatedFare;
          // 高德補咗座標（原本冇地標）→ 用真座標重計車費，唔再係 0
          if ((!pickupLandmark || !destLandmark) && pk?.lat && dt?.lat) {
            const distKm = estimateRoadDistanceKm(pk as any, dt as any);
            const taxiTypeKey = taxiType === 'green' ? 'nt' : 'urban';
            postFare = calcFareByDistance(distKm, taxiTypeKey, {
              tip: tipAmount,
              isDirectDiscount: selectedDiscount === 'standard' ? 'standard' : selectedDiscount === 'teishoku' ? 'teishoku' : selectedDiscount === '85' ? 'discount85' : 'discount90',
              teishokuPrice: selectedDiscount === 'teishoku' ? teishokuFare : undefined,
            }).total;
          }
          const postedNew = await createPostedOrder({
          pickup: pk,
          destination: dt,
          estimatedFare: postFare,
          carType,
          taxiType,
          carModel: (carModel as any) || undefined,
          distanceKm: roadDistanceKm > 0 ? roadDistanceKm : undefined,
          passengerNotes: {
            ...extras,
            customNote: notes || undefined,
          } as any,
          passengerPhone: passengerPhone || undefined,
          bookingTime: bookingTs,
          isDirect: selectedDiscount === 'standard' ? 'standard' : selectedDiscount === 'teishoku' ? 'teishoku' : selectedDiscount === '85' ? 'discount85' : selectedDiscount,
          tip: tipAmount,
          dispatchPhase: selectedDiscount === '85' ? 2 : selectedDiscount === '90' ? 1 : selectedDiscount === 'teishoku' ? 4 : 3,
          teishokuPrice: selectedDiscount === 'teishoku' ? teishokuFare : undefined,
        });
        posted = postedNew || null;
      } catch (apiErr) {
        // 本地兜底：API 唔得都要寫入 localStorage 派單池，保證示範可行
        logger.warn('createPostedOrder API failed, fallback to local:', String(apiErr));
        const pk = await resolveWithGeo(pickupInput, pickupLandmark);
        const dt = await resolveWithGeo(destInput, destLandmark);
        finalPkName = pk?.name || '';
        finalDtName = dt?.name || '';
        let distKm = 0;
        let fareCalc: { total: number } | undefined;
        if (pk?.lat && dt?.lat) {
          distKm = roadDistanceKm > 0 ? roadDistanceKm : estimateRoadDistanceKm(pk as any, dt as any);
          const taxiTypeKey: 'urban' | 'nt' | 'lantau' = taxiType === 'green' ? 'nt' : 'urban';
          fareCalc = calcFareByDistance(distKm, taxiTypeKey, {
            tip: tipAmount,
            isDirectDiscount: selectedDiscount === 'standard' ? 'standard' : selectedDiscount === 'teishoku' ? 'teishoku' : selectedDiscount === '85' ? 'discount85' : 'discount90',
            teishokuPrice: selectedDiscount === 'teishoku' ? teishokuFare : undefined,
          });
        }
        const newOrder = {
          id: 'POST' + Math.random().toString(36).slice(2, 8).toUpperCase(),
          status: 'searching',
          pickup: pk,
          destination: dt,
          carType,
          carModel: carModel || undefined,
          tip: tipAmount,
          estimatedFare: fareCalc?.total ?? 0,
          discount85: selectedDiscount === '85',
          teishoku: selectedDiscount === 'teishoku',
          teishokuPrice: selectedDiscount === 'teishoku' ? teishokuFare : undefined,
          passengerNotes: { ...extras, customNote: notes || undefined } as any,
          taxiType,
          createdAt: Date.now(),
          distanceKm: Math.max(1, distKm),
          etaMinutes: Math.max(3, Math.round(distKm * 3)),
          createdByDriver: true,
          driverPostedFrom: 'demo_driver',
          passengerPhone: passengerPhone || undefined,
          bookingTime: bookingTs,
          isDirect: selectedDiscount === 'standard' ? 'standard' : selectedDiscount === 'teishoku' ? 'teishoku' : selectedDiscount === '85' ? 'discount85' : selectedDiscount,
          dispatchPhase: selectedDiscount === '85' ? 2 : selectedDiscount === '90' ? 1 : selectedDiscount === 'teishoku' ? 4 : 3,
          dispatchPhaseStartedAt: Date.now(),
        };
        try {
          const rawPosted = scopedStorage.getItem('hktaxi_localPostedOrders');
          const postedList = rawPosted ? JSON.parse(rawPosted) : [];
          postedList.unshift(newOrder);
          scopedStorage.setItem('hktaxi_localPostedOrders', JSON.stringify(postedList));
        } catch (storageErr) {
          logger.error('save posted fallback failed:', String(storageErr));
        }
        try {
          const rawHall = scopedStorage.getItem('hktaxi_localHallOrders');
          const hallList = rawHall ? JSON.parse(rawHall) : [];
          hallList.push(newOrder);
          scopedStorage.setItem('hktaxi_localHallOrders', JSON.stringify(hallList));
          window.dispatchEvent(new CustomEvent('hktaxi-new-hall-order', { detail: newOrder }));
        } catch (storageErr) {
          logger.error('save hall fallback failed:', String(storageErr));
        }
        // v2.0.83：離線 fallback 單都要俾返 id 出去，onSuccess 先正常跳去「出貨」tab
        posted = { id: newOrder.id };
      }
      // v2.0.87：打字出貨成功都要有語音回饋「已出單」（之前得語音出貨有）
      try {
        const speakDisc = selectedDiscount === '85' ? '，八五折' : selectedDiscount === '90' ? '，九折' : selectedDiscount === 'teishoku' ? '，定食' : '';
        speak(`已出單，${finalPkName || '上車點'}去${finalDtName || '目的地'}${speakDisc}`);
      } catch { /* ignore */ }
      try { navigator.vibrate?.(200); } catch { /* ignore */ }
      onSuccess(posted?.id);
    } catch (err) {
      logger.error('出單失敗:', String(err));
      toast.error('出單失敗，請重試');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={(o) => !o && onClose()}>
      <DialogContent className="bg-zinc-900 border border-zinc-700 text-white max-w-md p-0 rounded-3xl overflow-hidden" showCloseButton={false}>
        <div className="flex flex-col max-h-[85vh]">
          {/* 表頭 */}
          <div className="px-5 pt-5 pb-3 bg-gradient-to-b from-yellow-600/20 to-transparent border-b border-zinc-800 shrink-0">
            <div className="flex items-center justify-between">
              <div>
                <div className="text-xl font-black">出貨</div>
                <div className="text-xs text-zinc-500 mt-0.5">自己出單，俾其他司機接</div>
              </div>
              <button
                onClick={onClose}
                className="size-8 rounded-full bg-zinc-800 hover:bg-zinc-700 flex items-center justify-center transition-colors"
              >
                <X className="size-4" />
              </button>
            </div>
            {pickupLandmark && destLandmark && (
              <div className="mt-3">
                <div className="flex items-baseline gap-2 flex-wrap">
                  <span className="text-3xl font-black text-yellow-400">${estimatedFare}</span>
                  {selectedDiscount !== 'standard' && selectedDiscount !== 'teishoku' && (
                    <span className="text-xs text-zinc-500 line-through">車費原價 ${baseFare}</span>
                  )}
                  {tipAmount > 0 && (
                    <span className="text-xs text-cyan-300 font-bold">+ 貼士 ${tipAmount}</span>
                  )}
                </div>
                <div className="text-xs text-zinc-500 mt-0.5">
                  預計總金額 · {selectedDiscount === 'standard' ? '千足金（原價）' : selectedDiscount === 'teishoku' ? '定食一口價' : `${selectedDiscount} 折`}
                </div>
              </div>
            )}
          </div>

          <div className="p-5 space-y-5 overflow-y-auto min-h-0 flex-1">
            {/* 路線 */}
            <div className="space-y-2">
              <div className="text-sm font-bold text-zinc-300">路線</div>
              {/* 大 Mic 一鍵語音出單：講「地點去地點」直接生成張單 */}
              {speechRecognitionSupported() && (
                <>
                  <button
                    type="button"
                    aria-label="語音出單"
                    onClick={startVoiceOrder}
                    className={`w-full flex flex-col items-center justify-center gap-1.5 py-4 rounded-2xl border-2 transition-all ${
                      listeningFor === 'voice-order'
                        ? 'bg-red-500/20 border-red-500 animate-pulse'
                        : 'bg-yellow-500/10 border-yellow-500/50 hover:bg-yellow-500/20 active:scale-[0.98]'
                    }`}
                  >
                    <span className={`size-14 rounded-full flex items-center justify-center shadow-lg transition-colors ${
                      listeningFor === 'voice-order'
                        ? 'bg-red-500 text-white animate-pulse'
                        : 'bg-gradient-to-br from-yellow-400 to-yellow-500 text-black'
                    }`}>
                      <Mic className="size-7" />
                    </span>
                    <span className={`text-base font-black ${
                      listeningFor === 'voice-order' ? 'text-red-400 animate-pulse' : 'text-yellow-400'
                    }`}>
                      {listeningFor === 'voice-order' ? '聆聽中… 請講地點' : '語音出單'}
                    </span>
                    <span className="text-xs text-zinc-400 leading-snug text-center px-3">
                      講「地點 去 地點」，例如「元朗千色去粉嶺工地」，即自動生成張單
                    </span>
                  </button>
                  <div className="text-center text-xs font-bold text-red-400">必需講「去」字</div>
                </>
              )}
              {/* 上車 */}
              <div className="relative">
                <div className="flex items-center gap-3 bg-zinc-800/60 rounded-xl px-3 py-2.5 border border-zinc-700">
                  <div className="size-3 rounded-full bg-green-400 shrink-0" />
                  <input
                    type="text"
                    value={pickupInput}
                    onChange={(e) => { setPickupInput(e.target.value); setPickupLandmark(null); }}
                    onFocus={() => setPickupFocus(true)}
                    onBlur={() => setTimeout(() => setShowPickupResults(false), 150)}
                    placeholder="上車地點（輸入地標名）"
                    className="flex-1 bg-transparent text-white placeholder-zinc-600 outline-none text-sm font-bold"
                  />
                  {speechRecognitionSupported() && (
                    <button
                      type="button"
                      aria-label="用語音輸入上車點"
                      onClick={() => startVoiceInput('pickup')}
                      className={`shrink-0 size-8 rounded-full flex items-center justify-center transition-colors ${
                        listeningFor === 'pickup'
                          ? 'bg-red-500 text-white animate-pulse'
                          : 'bg-zinc-700 text-zinc-300 hover:bg-zinc-600 active:scale-95'
                      }`}
                    >
                      <Mic className="size-4" />
                    </button>
                  )}
                </div>
                {showPickupResults && pickupResults.length > 0 && (
                  <div className="absolute top-full left-0 right-0 mt-1 bg-zinc-800 border border-zinc-700 rounded-xl z-20 overflow-hidden max-h-48 overflow-y-auto">
                    {pickupResults.map((l) => (
                      <button
                        key={l.id}
                        onMouseDown={() => {
                          setPickupLandmark(l);
                          setPickupInput(l.name);
                          setShowPickupResults(false);
                        }}
                        className="w-full text-left px-3 py-2 hover:bg-zinc-700 text-sm text-white truncate"
                      >
                        {l.name}
                      </button>
                    ))}
                  </div>
                )}
                {/* 快捷鍵 */}
                <div className="flex flex-wrap gap-1.5 mt-2">
                  {QUICK_LANDMARKS.map((q) => (
                    <button
                      key={q.id}
                      type="button"
                      onClick={() => {
                        setPickupLandmark(q);
                        setPickupInput(q.name);
                        setShowPickupResults(false);
                      }}
                      className="px-2.5 py-1 rounded-full bg-zinc-800/80 border border-zinc-700 text-xs text-zinc-300 hover:bg-zinc-700 hover:text-white transition-colors whitespace-nowrap"
                    >
                      {q.shortName}
                    </button>
                  ))}
                </div>
              </div>
              {/* 落車 */}
              <div className="relative">
                <div className="flex items-center gap-3 bg-zinc-800/60 rounded-xl px-3 py-2.5 border border-zinc-700">
                  <div className="size-3 rounded-full bg-red-500 shrink-0" />
                  <input
                    type="text"
                    value={destInput}
                    onChange={(e) => { setDestInput(e.target.value); setDestLandmark(null); }}
                    onFocus={() => setDestFocus(true)}
                    onBlur={() => setTimeout(() => setShowDestResults(false), 150)}
                    placeholder="目的地（輸入地標名）"
                    className="flex-1 bg-transparent text-white placeholder-zinc-600 outline-none text-sm font-bold"
                  />
                  {speechRecognitionSupported() && (
                    <button
                      type="button"
                      aria-label="用語音輸入目的地"
                      onClick={() => startVoiceInput('dest')}
                      className={`shrink-0 size-8 rounded-full flex items-center justify-center transition-colors ${
                        listeningFor === 'dest'
                          ? 'bg-red-500 text-white animate-pulse'
                          : 'bg-zinc-700 text-zinc-300 hover:bg-zinc-600 active:scale-95'
                      }`}
                    >
                      <Mic className="size-4" />
                    </button>
                  )}
                </div>
                {showDestResults && destResults.length > 0 && (
                  <div className="absolute top-full left-0 right-0 mt-1 bg-zinc-800 border border-zinc-700 rounded-xl z-20 overflow-hidden max-h-48 overflow-y-auto">
                    {destResults.map((l) => (
                      <button
                        key={l.id}
                        onMouseDown={() => {
                          setDestLandmark(l);
                          setDestInput(l.name);
                          setShowDestResults(false);
                        }}
                        className="w-full text-left px-3 py-2 hover:bg-zinc-700 text-sm text-white truncate"
                      >
                        {l.name}
                      </button>
                    ))}
                  </div>
                )}
                {/* 快捷鍵 */}
                <div className="flex flex-wrap gap-1.5 mt-2">
                  {QUICK_LANDMARKS.map((q) => (
                    <button
                      key={q.id}
                      type="button"
                      onClick={() => {
                        setDestLandmark(q);
                        setDestInput(q.name);
                        setShowDestResults(false);
                      }}
                      className="px-2.5 py-1 rounded-full bg-zinc-800/80 border border-zinc-700 text-xs text-zinc-300 hover:bg-zinc-700 hover:text-white transition-colors whitespace-nowrap"
                    >
                      {q.shortName}
                    </button>
                  ))}
                </div>
              </div>
            </div>

            {/* 聯絡資訊 */}
            <div className="space-y-2">
              <div className="text-sm font-bold text-zinc-300">客人電話（若不留客人電話系統會留你電話）</div>
              <input
                type="tel"
                value={passengerPhone}
                onChange={(e) => setPassengerPhone(e.target.value)}
                placeholder="例如：98765432"
                className="w-full bg-zinc-800 text-white rounded-xl px-3 py-2.5 text-sm font-bold outline-none border border-zinc-700 focus:border-yellow-500 placeholder-zinc-600"
              />
            </div>

            {/* 車型 */}
            <div className="space-y-2">
              <div className="text-sm font-bold text-zinc-300">車型</div>
              {/* 的種 */}
              <div className="grid grid-cols-2 gap-2">
                <button
                  onClick={() => setTaxiType('red')}
                  className={`py-2.5 rounded-xl text-sm font-bold transition-colors ${
                    taxiType === 'red'
                      ? 'bg-red-600 text-white'
                      : 'bg-zinc-800 text-zinc-400 hover:bg-zinc-700'
                  }`}
                >
                  市區紅的
                </button>
                <button
                  onClick={() => setTaxiType('green')}
                  className={`py-2.5 rounded-xl text-sm font-bold transition-colors ${
                    taxiType === 'green'
                      ? 'bg-green-600 text-white'
                      : 'bg-zinc-800 text-zinc-400 hover:bg-zinc-700'
                  }`}
                >
                  新界綠的
                </button>
              </div>
              {/* 座位 */}
              <div className="grid grid-cols-2 gap-2">
                <button
                  onClick={() => setCarType('4-seater')}
                  className={`py-2.5 rounded-xl text-sm font-bold transition-colors ${
                    carType === '4-seater'
                      ? 'bg-yellow-500 text-black'
                      : 'bg-zinc-800 text-zinc-400 hover:bg-zinc-700'
                  }`}
                >
                  4 人車
                </button>
                <button
                  onClick={() => setCarType('6-seater')}
                  className={`py-2.5 rounded-xl text-sm font-bold transition-colors ${
                    carType === '6-seater'
                      ? 'bg-yellow-500 text-black'
                      : 'bg-zinc-800 text-zinc-400 hover:bg-zinc-700'
                  }`}
                >
                  6 人車
                </button>
              </div>
              {/* 車款 */}
              <div>
                <select
                  value={carModel}
                  onChange={(e) => setCarModel(e.target.value)}
                  className="w-full bg-zinc-800 text-white rounded-xl px-3 py-2.5 text-sm font-bold outline-none border border-zinc-700 focus:border-yellow-500"
                >
                  <option value="">普通車款</option>
                  <option value="old-comfort">舊金豐</option>
                  <option value="hybrid">混能</option>
                  <option value="electric">電車</option>
                  <option value="mifa7">MIFA 7</option>
                  <option value="vw-van">大黃鋒 Van</option>
                </select>
              </div>
            </div>

            {/* 預約時間 */}
            <div className="space-y-2">
              <div className="text-sm font-bold text-zinc-300">時間</div>
              <div className="grid grid-cols-2 gap-2">
                <button
                  onClick={() => setBookingMode('now')}
                  className={`py-2.5 rounded-xl text-sm font-bold transition-colors ${
                    bookingMode === 'now'
                      ? 'bg-yellow-500 text-black'
                      : 'bg-zinc-800 text-zinc-400 hover:bg-zinc-700'
                  }`}
                >
                  即刻
                </button>
                <button
                  onClick={() => setBookingMode('later')}
                  className={`py-2.5 rounded-xl text-sm font-bold transition-colors ${
                    bookingMode === 'later'
                      ? 'bg-yellow-500 text-black'
                      : 'bg-zinc-800 text-zinc-400 hover:bg-zinc-700'
                  }`}
                >
                  預約
                </button>
              </div>
              {bookingMode === 'later' && (
                <div className="grid grid-cols-2 gap-2">
                  <input
                    type="date"
                    value={bookingDate}
                    onChange={(e) => setBookingDate(e.target.value)}
                    className="bg-zinc-800 text-white rounded-xl px-3 py-2.5 text-sm font-bold outline-none border border-zinc-700"
                  />
                  <input
                    type="time"
                    value={bookingTimeVal}
                    onChange={(e) => setBookingTimeVal(e.target.value)}
                    className="bg-zinc-800 text-white rounded-xl px-3 py-2.5 text-sm font-bold outline-none border border-zinc-700"
                  />
                </div>
              )}
            </div>

            {/* 附加選項 */}
            <div className="space-y-2">
              <div className="text-sm font-bold text-zinc-300">附加選項</div>
              <div className="grid grid-cols-2 gap-2">
                {[
                  { key: 'ePayment', label: '電子支付' },
                  { key: 'receipt', label: '要收據' },
                  { key: 'doubleTunnel', label: '雙程隧道' },
                  { key: 'pet', label: '有寵物' },
                ].map((item) => (
                  <button
                    key={item.key}
                    onClick={() => setExtras((prev) => ({ ...prev, [item.key]: !prev[item.key as keyof typeof prev] }))}
                    className={`py-2.5 rounded-xl text-sm font-bold transition-colors ${
                      extras[item.key as keyof typeof extras]
                        ? 'bg-yellow-500/20 text-yellow-400 border border-yellow-500/50'
                        : 'bg-zinc-800 text-zinc-400 border border-zinc-700 hover:bg-zinc-700'
                    }`}
                  >
                    {item.label}
                  </button>
                ))}
              </div>
            </div>

            {/* 備注 */}
            <div className="space-y-2">
              <div className="text-sm font-bold text-zinc-300">備注/額外要求</div>
              <textarea
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                placeholder="例如：幫手搬行李、有 BB 車..."
                rows={2}
                className="w-full bg-zinc-800 text-white rounded-xl px-3 py-2.5 text-sm font-bold outline-none border border-zinc-700 focus:border-yellow-500 placeholder-zinc-600 resize-none"
              />
            </div>

            {/* 貼士 */}
            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <div className="text-sm font-bold text-zinc-300">貼士</div>
                <button
                  onClick={() => { setShowCustomTip(!showCustomTip); if (!showCustomTip) { setTipAmount(0); setCustomTip(''); } }}
                  className="text-xs text-yellow-400 font-bold hover:text-yellow-300"
                >
                  {showCustomTip ? '用快捷金額' : '自訂金額'}
                </button>
              </div>
              {!showCustomTip ? (
                <div className="grid grid-cols-4 gap-1.5">
                  {[10, 20, 30, 50, 70, 80, 100, 0].map((val) => (
                    <button
                      key={val}
                      onClick={() => setTipAmount(val)}
                      className={`py-2 rounded-xl text-sm font-black transition-all border ${
                        tipAmount === val
                          ? 'bg-yellow-500 text-black border-yellow-400'
                          : 'bg-zinc-800 text-zinc-300 border-transparent hover:bg-zinc-700'
                      }`}
                    >
                      {val === 0 ? '唔加' : `+$${val}`}
                    </button>
                  ))}
                </div>
              ) : (
                <div className="relative">
                  <span className="absolute left-3 top-1/2 -translate-y-1/2 text-lg font-black text-yellow-400">$</span>
                  <input
                    type="number"
                    min={0}
                    max={100}
                    value={customTip}
                    onChange={(e) => {
                      const v = e.target.value;
                      setCustomTip(v);
                      const num = parseInt(v, 10);
                      if (!isNaN(num) && num >= 0 && num <= 100) {
                        setTipAmount(num);
                      } else if (v === '') {
                        setTipAmount(0);
                      }
                    }}
                    placeholder="輸入貼士金額（0-100）"
                    className="w-full bg-zinc-800 text-white rounded-xl pl-8 pr-3 py-2.5 text-base font-black outline-none border border-zinc-700 focus:border-yellow-500 placeholder-zinc-600"
                  />
                </div>
              )}
              {tipAmount > 0 && (
                <div className="text-xs text-cyan-300 font-bold">
                  已加貼士 ${tipAmount}，會一併計入出單車費
                </div>
              )}
            </div>
          </div>

          {/* 直出折扣選擇 */}
          <div className="px-5 space-y-2 pt-3">
            <div className="text-sm font-bold text-zinc-300">政府跳表</div>
            <div className="grid grid-cols-4 gap-1.5">
              {[
                { key: 'standard' as const, label: '千足金', sub: '原價', color: 'bg-yellow-900/40 text-yellow-300 hover:bg-yellow-900/60', activeColor: 'bg-yellow-500 text-white border-yellow-300' },
                { key: '90' as const, label: '90', sub: '9折', color: 'bg-zinc-800/60 text-zinc-400 hover:bg-zinc-700/60', activeColor: 'bg-zinc-600 text-white border-zinc-300' },
                { key: '85' as const, label: '85', sub: '85折', color: 'bg-zinc-200/20 text-zinc-300 hover:bg-zinc-200/30', activeColor: 'bg-white text-zinc-900 border-zinc-300' },
                { key: 'teishoku' as const, label: '定食', sub: '一口價', color: 'bg-purple-900/40 text-purple-300 hover:bg-purple-900/60', activeColor: 'bg-purple-500 text-white border-purple-300' },
              ].map((opt) => (
                <button
                  key={opt.key}
                  onClick={() => setSelectedDiscount(opt.key)}
                  className={`py-2.5 rounded-xl font-black transition-all flex flex-col items-center gap-0.5 border ${
                    selectedDiscount === opt.key ? opt.activeColor : opt.color + ' border-transparent'
                  }`}
                >
                  <span className="text-sm leading-none">{opt.label}</span>
                  <span className="text-[9px] font-bold opacity-70">{opt.sub}</span>
                </button>
              ))}
            </div>
            {selectedDiscount === 'teishoku' && (
              <div className="relative mt-1">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-yellow-400 font-bold text-base">$</span>
                <input
                  type="number"
                  value={teishokuPrice}
                  onChange={(e) => setTeishokuPrice(e.target.value)}
                  placeholder="輸入定食價，例如 160"
                  className="w-full bg-zinc-800/60 border border-purple-500/50 rounded-xl pl-8 pr-3 py-2.5 text-white placeholder-zinc-600 outline-none text-sm font-bold focus:border-purple-400 transition-colors"
                />
              </div>
            )}
          </div>

          {/* 底部按鈕 */}
          <div className="p-5 pt-3 border-t border-zinc-800 bg-zinc-900 shrink-0">
            <button
              disabled={submitting || !canSubmit}
              onClick={handleSubmit}
              className="w-full py-3.5 rounded-xl bg-gradient-to-r from-yellow-500 to-yellow-600 hover:from-yellow-400 hover:to-yellow-500 text-black font-black text-lg transition-all disabled:opacity-40 disabled:cursor-not-allowed shadow-lg shadow-yellow-900/30 active:scale-[0.99]"
            >
              {submitting ? '出單中...' : '立即出單'}
            </button>
            {pickupLandmark && destLandmark ? (
              <div className="text-center text-xs text-zinc-500 mt-2">
                出單後會自動進入接貨列表，其他司機可見
              </div>
            ) : (
              <div className="text-center text-xs text-yellow-500/80 mt-2">
                記得揀選上車點同目的地先可以出單
              </div>
            )}
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}
