// 語音共用模組：TTS 播報 + 語音辨識（SpeechRecognition）
// TTS 播報：網頁用瀏覽器 speechSynthesis（粵語優先、默認女聲）；APK（Capacitor native）用 @capacitor-community/text-to-speech
// （Android WebView 嘅 speechSynthesis 有「間歇性失聲」bug：引擎未 ready／長開後睡死／連續播報會靜默失敗，原生 TTS 先穩定）
// 語音落單：網頁用 Web Speech API（webkitSpeechRecognition）；APK（Capacitor native）用 @capacitor-community/speech-recognition
import { Capacitor } from '@capacitor/core';

// Capacitor 原生語音插件（APK 用；延遲載入，瀏覽器環境唔會失敗）
let capSpeechModule: any = null;
let capSpeechLoaded = false;
async function loadCapSpeech(): Promise<any> {
  if (capSpeechLoaded) return capSpeechModule;
  capSpeechLoaded = true;
  try {
    const mod = await import('@capacitor-community/speech-recognition');
    capSpeechModule = mod.SpeechRecognition || mod.default || null;
  } catch {
    capSpeechModule = null;
  }
  return capSpeechModule;
}

// Capacitor 原生 TTS 插件（APK 播報用；延遲載入）
let capTtsModule: any = null;
let capTtsLoaded = false;
async function loadCapTts(): Promise<any> {
  if (capTtsLoaded) return capTtsModule;
  capTtsLoaded = true;
  try {
    const mod = await import('@capacitor-community/text-to-speech');
    capTtsModule = mod.TextToSpeech || mod.default || null;
  } catch {
    capTtsModule = null;
  }
  return capTtsModule;
}

export function ttsSupported(): boolean {
  if (typeof window === 'undefined') return false;
  // APK：原生 TTS 插件可用 → 支援播報
  try {
    if (Capacitor.isNativePlatform()) return true;
  } catch { /* ignore */ }
  return 'speechSynthesis' in window;
}

// 女聲名稱特徵（iOS Ting-Ting／Windows Tracy／Samantha／Android 粵語女聲等）
const FEMALE_PATTERN = /ting-?ting|tracy|samantha|female|woman|女声|女聲|女性|mei-?jia|ya-?ya|sin-?ji|google 粵語|google 國語|karen|victoria|zira|hazel|susan/i;

// 確保 voices 已載入（部分瀏覽器首次 getVoices 係空，要等 onvoiceschanged）
let voicesWarmed = false;
// v2.0.79 iOS PWA 修復：網頁 speechSynthesis 播報鎖——上一次播報未完，新播報延後再試（唔疊播、唔跳過）
let webSpeakBusy = false;
// v2.0.81：voices 未載入時最多等幾耐（每次 200ms，最多 15 次 = 3 秒），避免部分 Android/iOS 首次 voices 空導致靜默失敗
let voiceWaitTries = 0;
// v2.0.88：voices 一直空（部分 Android WebView 長期 getVoices=0）時唔好等足 3 秒——
// 等太耐用戶會以為冇聲，而且 voices=0 都照樣可以出聲（用 lang 兜底）；所以上限改 5 次 = 1 秒
const MAX_VOICE_WAIT = 5;
// v2.0.88：上一段播報未完（webSpeakBusy）時，最多延後 3 次（0.9 秒），之後直接放棄——
// 避免多張新單同時到時無限積壓，令成段時間都冇聲
let webBusyRetries = 0;
// v2.0.81：網頁播報失敗自動重試次數上限
const MAX_WEB_RETRIES = 3;
// v2.0.79 iOS PWA 修復：首次網頁播報前要先播一段無聲空白解鎖 iOS 語音引擎
// （iOS 異步播報——例如「人地出單」新單到達——唔係用戶手勢觸發，首次唔解鎖就會無聲；
//   自己出單因為撳掣觸發，有手勢授權所以有聲，呢個正正解釋咗「人地出單聽唔到」）
let everSpokeWeb = false;

// v2.0.81：Android 省電保活心跳——每 45 秒空播一次（volume 0，無聲），
// 防止 speechSynthesis 引擎被系統凍結之後「間歇冇聲」（長開/鎖屏後常見）
if (typeof window !== 'undefined' && 'speechSynthesis' in window) {
  try {
    setInterval(() => {
      if (webSpeakBusy) return;
      try {
        const synth = window.speechSynthesis;
        synth.cancel();
        const u = new SpeechSynthesisUtterance(' ');
        u.volume = 0;
        u.rate = 2;
        synth.speak(u);
      } catch { /* ignore */ }
    }, 45000);
  } catch { /* ignore */ }
}
function warmVoices() {
  if (!ttsSupported() || voicesWarmed) return;
  voicesWarmed = true;
  try {
    const synth = window.speechSynthesis;
    // 觸發 voices 載入
    synth.getVoices();
    const onChange = () => {
      synth.removeEventListener?.('voiceschanged', onChange);
    };
    synth.addEventListener?.('voiceschanged', onChange);
  } catch { /* ignore */ }
}

// 讀取司機設定：voiceFemale（默認開女聲）
function wantFemaleVoice(): boolean {
  try {
    const raw = window.localStorage.getItem('hktaxi_driverSettings');
    if (raw) {
      const s = JSON.parse(raw);
      return (s as any).voiceFemale !== false;
    }
  } catch { /* ignore */ }
  return true;
}

function pickVoice(): SpeechSynthesisVoice | null {
  const voices = window.speechSynthesis.getVoices();
  const female = wantFemaleVoice();
  const zhLang = (v: SpeechSynthesisVoice) => /(yue|zh)/i.test((v.lang || '').replace('-', '_'));
  const isFemale = (v: SpeechSynthesisVoice) => FEMALE_PATTERN.test(v.name || '');

  // 次序：女聲粵語 → 女聲中文 → 粵語 → 繁體中文 → 任何中文
  const prefs = ['yue-HK', 'yue_HK', 'zh-HK', 'zh-TW', 'zh_HK', 'zh_TW', 'zh-CN', 'zh'];
  if (female) {
    for (const p of prefs) {
      const v = voices.find((v) => (v.lang || '').toLowerCase().replace('-', '_').startsWith(p.toLowerCase()) && isFemale(v));
      if (v) return v;
    }
  }
  for (const p of prefs) {
    const v = voices.find((v) => (v.lang || '').toLowerCase().replace('-', '_').startsWith(p.toLowerCase()));
    if (v) return v;
  }
  // 兜底：任何含「Yue/粵/Cantonese」或中文
  const cantonese = voices.find((v) => /yue|粵|cantonese/i.test(v.lang + ' ' + v.name));
  if (cantonese) return cantonese;
  return voices.find((v) => zhLang(v)) || null;
}

// 朗讀一段文字（粵語優先、默認女聲）；遇到問題就靜默失敗
// APK 環境用系統原生 TTS（穩定），網頁環境照舊用 speechSynthesis
// 【修復 v2.0.76】speechSynthesis 有「間歇性失聲」知名 bug（引擎卡死喺 speaking/pending，
// 之後所有 speak 靜默失敗）——每次播報前強制 cancel ＋ pause/resume 喚醒 ＋ onend/onerror 監聽 ＋ 超時重置
export function speak(text: string, opts: { rate?: number; volume?: number; onDone?: () => void } = {}) {
  const done = opts.onDone;
  const finish = () => { try { done?.(); } catch { /* ignore */ } };
  try {
    // APK（Capacitor native）：用系統原生 TTS，避免 WebView speechSynthesis 間歇失聲
    if (Capacitor.isNativePlatform()) {
      (async () => {
        try {
          const tts = await loadCapTts();
          if (!tts) { finish(); return; }
          await tts.stop();
          // v2.0.88：stop 之後俾引擎 100ms 清場先再 speak（Android TTS stop 係異步，即刻 speak 會被吞）
          await new Promise((r) => setTimeout(r, 100));
          let spoken = false;
          for (let i = 0; i < 3 && !spoken; i++) {
            try {
              await tts.speak({
                text,
                lang: 'zh-HK',
                rate: opts.rate ?? 0.95,
                pitch: 1.0,
                category: 'ambient',
              });
              spoken = true;
            } catch {
              // v2.0.88：原生 TTS 失敗自動重試（最多 3 次，每次隔 250ms）
              if (i < 2) await new Promise((r) => setTimeout(r, 250));
            }
          }
          finish();
        } catch { finish(); }
      })();
      return;
    }
    if (!ttsSupported()) { finish(); return; }
    warmVoices();
    // v2.0.81：voices 未載入（首次 getVoices 空）就延後 200ms 再試，最多等 3 秒——
    // 部分 Android/iOS 首次播報嗰陣 voices 仲未 ready，直接 speak 會靜默失敗
    if (typeof window !== 'undefined' && 'speechSynthesis' in window) {
      try {
        if (window.speechSynthesis.getVoices().length === 0 && voiceWaitTries < MAX_VOICE_WAIT) {
          voiceWaitTries++;
          setTimeout(() => { try { speak(text, opts); } catch { finish(); } }, 200);
          return;
        }
      } catch { /* ignore */ }
      voiceWaitTries = 0;
    }
    const synth = window.speechSynthesis;
    // v2.0.79 iOS PWA 修復①：上一次網頁播報未完，新播報延後 300ms 再試（避免 iOS 語音佇列疊播壞死）
    // v2.0.88：最多延後 3 次就放棄，避免多張新單同時到時無限積壓
    if (webSpeakBusy) {
      if (webBusyRetries >= 3) {
        webBusyRetries = 0;
        finish();
        return;
      }
      webBusyRetries++;
      setTimeout(() => { try { speak(text, opts); } catch { finish(); } }, 300);
      return;
    }
    webBusyRetries = 0;
    webSpeakBusy = true;
    // 1) 強制清走之前未播完嘅（避免疊聲）
    try { synth.cancel(); } catch { /* ignore */ }
    // 2) Chrome/WebView 卡死喚醒：引擎 stuck 喺 speaking 就 pause+resume 重啟
    try {
      if (synth.speaking) { synth.pause(); synth.resume(); }
    } catch { /* ignore */ }
    // v2.0.79 iOS PWA 修復③：首次網頁播報前先播一段無聲空白，解鎖 iOS 語音引擎
    // （異步新單播報唔係用戶手勢觸發，iOS 首次唔解鎖就會無聲——解決「人地出單聽唔到」）
    if (!everSpokeWeb) {
      everSpokeWeb = true;
      try {
        const w = new SpeechSynthesisUtterance('。');
        w.volume = 0;
        w.rate = 2;
        synth.speak(w);
      } catch { /* ignore */ }
    }
    // v2.0.79 iOS PWA 修復②：cancel 之後俾引擎 200ms 重置先再 speak
    // （iOS 連續 cancel→speak 會令引擎交替失聲：第一張冇聲、第二張有聲、再冇聲……）
    setTimeout(() => {
      const u = new SpeechSynthesisUtterance(text);
      const voice = pickVoice();
      if (voice) u.voice = voice;
      u.lang = (voice && voice.lang) || 'zh-HK';
      u.rate = opts.rate ?? 0.95;
      u.volume = opts.volume ?? 1;
      // 3) 監聽完成/錯誤，卡住就超時兜底，下次播報先會正常
      let settled = false;
      let retries = 0;
      const settle = () => {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        webSpeakBusy = false;
        voiceWaitTries = 0;
        finish();
      };
      // v2.0.81：播報失敗（onerror，例如引擎暫時佔用）自動重試最多 3 次，每次隔 350ms
      const retrySpeak = () => {
        if (settled) return;
        if (retries < MAX_WEB_RETRIES) {
          retries++;
          settled = true;
          clearTimeout(timer);
          webSpeakBusy = false;
          setTimeout(() => { try { speak(text, opts); } catch { finish(); } }, 350);
        } else {
          settle();
        }
      };
      u.onend = settle;
      u.onerror = retrySpeak;
      const timer = setTimeout(settle, 6000); // v2.0.88：6 秒超時（短句夠晒；縮短「引擎靜默失敗」嘅無聲窗口）
      try {
        synth.speak(u);
      } catch { retrySpeak(); }
    }, 200);
  } catch {
    webSpeakBusy = false;
    finish();
  }
}

// 喺用戶手勢（撳掣嗰一刻）預先喚醒語音引擎 + 播一段超短空白，解鎖瀏覽器 autoplay 限制，
// 之後異步回調（API 成功先 speak）先會正常出聲——解決「10次得1次有聲」
export function unlockSpeech() {
  try {
    if (Capacitor.isNativePlatform()) return; // 原生 TTS 冇 autoplay 限制
    if (!ttsSupported()) return;
    warmVoices();
    const synth = window.speechSynthesis;
    try { synth.cancel(); } catch { /* ignore */ }
    try {
      if (synth.speaking) { synth.pause(); synth.resume(); }
    } catch { /* ignore */ }
    // 播一句極短空白（「。 」）觸發引擎 + 攞到 autoplay 授權；speak 出唔到聲都唔影響
    const u = new SpeechSynthesisUtterance('。');
    u.volume = 0;
    u.rate = 2;
    try { synth.speak(u); } catch { /* ignore */ }
  } catch { /* ignore */ }
}

// v2.0.88：App 由背景/鎖屏回到前景時自動再解鎖一次語音引擎（iOS/Android WebView 長開後
// 引擎可能失去授權狀態；返到前景重新喚醒，減少「間歇冇聲」）
if (typeof window !== 'undefined' && typeof document !== 'undefined') {
  try {
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'visible') {
        try { unlockSpeech(); } catch { /* ignore */ }
      }
    });
  } catch { /* ignore */ }
}

// 停止朗讀
export function stopSpeaking() {
  try {
    // APK：停止原生 TTS
    if (Capacitor.isNativePlatform()) {
      (async () => {
        try {
          const tts = await loadCapTts();
          if (tts) await tts.stop();
        } catch { /* ignore */ }
      })();
      return;
    }
  } catch { /* ignore */ }
  if (ttsSupported()) {
    try { window.speechSynthesis.cancel(); } catch { /* ignore */ }
  }
}

export interface SpeechListenCallbacks {
  onResult: (text: string) => void;
  onEnd: () => void;
  onError?: (err: string) => void;
}

export function speechRecognitionSupported(): boolean {
  // 網頁版 Web Speech API
  if (typeof window !== 'undefined' &&
    !!((window as any).SpeechRecognition || (window as any).webkitSpeechRecognition)) return true;
  // APK（Capacitor native）：有裝 speech-recognition 插件 → 都支援語音
  try {
    if (Capacitor.isNativePlatform()) return true;
  } catch { /* ignore */ }
  return false;
}

// 開始語音辨識（粵語優先；認到文字就 onResult，最後 onEnd）
// 返回一個 cancel 函數；唔支援就返 null
export function startListening(cbs: SpeechListenCallbacks): (() => void) | null {
  const C = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;

  // APK 環境：網頁 Web Speech API 唔存在 → 用 Capacitor 原生語音
  if (!C) {
    let isNative = false;
    try { isNative = Capacitor.isNativePlatform(); } catch { /* ignore */ }
    if (!isNative) return null;
    let cancelled = false;
    let listeners: any[] = [];
    (async () => {
      try {
        const cap = await loadCapSpeech();
        if (!cap) { cbs.onEnd?.(); return; }
        // 權限（RECORD_AUDIO）
        const perm = await cap.requestPermissions();
        if (cancelled) return;
        const onPartial = await cap.addListener('partialResults', (data: any) => {
          if (cancelled) return;
          const arr = data?.matches || [];
          const text = arr[arr.length - 1] || arr[0] || '';
          if (text) cbs.onResult(text);
        });
        const onEnd = await cap.addListener('end', () => { if (!cancelled) cbs.onEnd(); });
        const onErr = await cap.addListener('error', (e: any) => {
          if (!cancelled) { cbs.onError?.(String(e?.message || 'unknown')); cbs.onEnd(); }
        });
        listeners = [onPartial, onEnd, onErr];
        await cap.start({ language: 'yue-HK' });
      } catch (e: any) {
        if (!cancelled) { cbs.onError?.('not-allowed'); cbs.onEnd(); }
      }
    })();
    return () => {
      cancelled = true;
      (async () => {
        try {
          const cap = await loadCapSpeech();
          if (cap) {
            await cap.stop();
            for (const l of listeners) l?.remove?.();
          }
        } catch { /* ignore */ }
      })();
    };
  }

  try {
    const rec = new C();
    rec.lang = 'yue-HK'; // 粵語；唔支援會自動 fallback 到瀏覽器默認
    rec.continuous = false;
    rec.interimResults = false;
    rec.maxAlternatives = 1;

    rec.onresult = (ev: any) => {
      let transcript = '';
      for (let i = 0; i < ev.results.length; i++) {
        if (ev.results[i].isFinal) {
          transcript += ev.results[i][0].transcript || '';
        }
      }
      if (transcript.trim()) cbs.onResult(transcript.trim());
    };
    rec.onerror = (ev: any) => {
      if (cbs.onError) cbs.onError(ev?.error || 'unknown');
      cbs.onEnd();
    };
    rec.onend = () => cbs.onEnd();

    rec.start();
    return () => {
      try { rec.abort(); } catch { /* ignore */ }
    };
  } catch {
    return null;
  }
}
