import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  ArrowLeft,
  User,
  Phone,
  Car,
  Bell,
  Globe,
  LogOut,
  Check,
} from 'lucide-react';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from '@/components/ui/alert-dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Switch } from '@/components/ui/switch';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { toast } from 'sonner';
import { useI18n, type Lang } from '@/lib/i18n';
import { useOrder } from '@/lib/order-context';
import { scopedStorage } from '@/lib/standalone-shim';
import { changeDriverPassword, deleteDriverAccount, updateDriverProfile, persistUser } from '@/lib/api';

const SETTINGS_KEY = 'hktaxi_driverSettings';

interface DriverSettings {
  name: string;
  phone: string;
  plate: string;
  carType: 'urban' | 'nt' | 'lantau';
  newOrderNotif: boolean;
  messageNotif: boolean;
  systemNotif: boolean;
  // 新單語音播報（TTS 讀出「新貨單」+ 位置）
  voiceNotif: boolean;
  // 播報用女聲（預設開）
  voiceFemale: boolean;
}

export default function DriverSettingsPage() {
  const navigate = useNavigate();
  const { t, lang, setLang } = useI18n();
  const { user, setDriverOnline, logout, setUser } = useOrder();

  const [settings, setSettings] = useState<DriverSettings>({
    name: user?.name || '',
    phone: user?.phone || '',
    plate: user?.plate || '',
    carType: 'urban',
    newOrderNotif: true,
    messageNotif: true,
    systemNotif: true,
    voiceNotif: true,
    voiceFemale: true,
  });
  const [saving, setSaving] = useState(false);
  const [logoutConfirm, setLogoutConfirm] = useState(false);
  const [deleteConfirm, setDeleteConfirm] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [pw, setPw] = useState({ old: '', next: '', confirm: '' });
  const [pwSaving, setPwSaving] = useState(false);

  // 讀本地設定
  useEffect(() => {
    try {
      const raw = scopedStorage.getItem(SETTINGS_KEY);
      if (raw) {
        const saved = JSON.parse(raw) as Partial<DriverSettings>;
        setSettings((prev) => ({ ...prev, ...saved }));
      }
    } catch {
      // ignore
    }
  }, []);

  const handleSave = async () => {
    setSaving(true);
    try {
      // 更新 server 個人資料（姓名／電話），先會喺個人中心即時反映
      const dirtyName = settings.name.trim() !== (user?.name || '');
      const dirtyPhone = settings.phone.trim() !== (user?.phone || '');
      if (dirtyName || dirtyPhone) {
        const res = await updateDriverProfile({
          name: dirtyName ? settings.name : undefined,
          phone: dirtyPhone ? settings.phone : undefined,
        });
        if (res?.user) {
          setUser(res.user);
          persistUser(res.user);
        } else {
          const merged: any = { ...user, name: settings.name, phone: settings.phone };
          setUser(merged);
          persistUser(merged);
        }
      }
      scopedStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
      toast.success(t.driverSettings.saved);
    } catch (e: any) {
      toast.error(e?.message || t.common.errors.submitFailed);
    } finally {
      setSaving(false);
    }
  };

  const handleLogout = () => {
    setDriverOnline(false);
    logout();
    navigate('/driver/login', { replace: true });
  };

  const handleDeleteAccount = async () => {
    setDeleting(true);
    try {
      await deleteDriverAccount();
      setDriverOnline(false);
      logout();
      toast.success('帳戶已刪除');
      navigate('/driver/login', { replace: true });
    } catch {
      toast.error('刪除失敗，請稍後再試');
    } finally {
      setDeleting(false);
      setDeleteConfirm(false);
    }
  };

  const handleChangeLang = (l: Lang) => {
    setLang(l);
  };

  const handleChangePassword = async () => {
    if (!pw.old || !pw.next || !pw.confirm) {
      toast.error(t.driverSettings.passwordTooShort);
      return;
    }
    if (pw.next !== pw.confirm) {
      toast.error(t.driverSettings.passwordMismatch);
      return;
    }
    if (pw.next.length < 6) {
      toast.error(t.driverSettings.passwordTooShort);
      return;
    }
    setPwSaving(true);
    try {
      await changeDriverPassword(pw.old, pw.next);
      toast.success(t.driverSettings.passwordChanged);
      setPw({ old: '', next: '', confirm: '' });
    } catch (e: any) {
      const msg = e?.response?.data?.error;
      if (msg === '舊密碼錯誤' || String(msg).includes('old')) {
        toast.error(t.driverSettings.oldPasswordWrong);
      } else if (msg === '新密碼至少 6 位') {
        toast.error(t.driverSettings.passwordTooShort);
      } else {
        toast.error(msg || t.common.errors.submitFailed);
      }
    } finally {
      setPwSaving(false);
    }
  };

  return (
    <div className="min-h-screen bg-black text-white flex flex-col">
      {/* 頂部導航 */}
      <div className="sticky top-0 z-40 bg-black/80 backdrop-blur-md border-b border-zinc-800">
        <div className="flex items-center h-14 px-4">
          <button
            onClick={() => navigate(-1)}
            className="size-10 rounded-full flex items-center justify-center hover:bg-zinc-800 transition-colors -ml-2"
            aria-label={t.common.back}
          >
            <ArrowLeft className="size-5 text-white" />
          </button>
          <h1 className="flex-1 text-center text-lg font-black -ml-10">
            {t.driverSettings.title}
          </h1>
          <div className="w-10" />
        </div>
      </div>

      <div className="px-4 py-5 space-y-5 flex-1">
        {/* 個人資料 */}
        <div className="rounded-2xl bg-zinc-900 border border-zinc-800 overflow-hidden">
          <div className="px-4 py-3 border-b border-zinc-800 flex items-center gap-2">
            <User className="size-4 text-yellow-400" />
            <span className="text-sm font-bold text-white">
              {t.driverSettings.profileSection}
            </span>
          </div>

          <div className="px-4 py-3 space-y-4">
            <div>
              <label className="text-xs text-zinc-400 font-medium mb-1.5 block">
                {t.driverSettings.driverName} <span className="text-zinc-500">（不能更改）</span>
              </label>
              <Input
                value={settings.name}
                readOnly
                className="bg-zinc-800 border-zinc-700 text-white h-11 font-bold"
              />
            </div>

            <div>
              <label className="text-xs text-zinc-400 font-medium mb-1.5 block">
                {t.driverSettings.phone}
              </label>
              <Input
                value={settings.phone}
                onChange={(e) => setSettings({ ...settings, phone: e.target.value })}
                className="bg-zinc-800 border-zinc-700 text-white h-11 font-bold"
              />
            </div>

            <div>
              <label className="text-xs text-zinc-400 font-medium mb-1.5 block">
                {t.driverSettings.plateNo}
              </label>
              <Input
                value={settings.plate}
                onChange={(e) => setSettings({ ...settings, plate: e.target.value })}
                className="bg-zinc-800 border-zinc-700 text-white h-11 font-bold font-mono uppercase"
              />
            </div>

            <div>
              <label className="text-xs text-zinc-400 font-medium mb-1.5 block">
                {t.driverSettings.carType}
              </label>
              <Select
                value={settings.carType}
                onValueChange={(v: 'urban' | 'nt' | 'lantau') =>
                  setSettings({ ...settings, carType: v })
                }
              >
                <SelectTrigger className="bg-zinc-800 border-zinc-700 text-white h-11 font-bold">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent className="bg-zinc-900 border-zinc-700 text-white">
                  <SelectItem value="urban">{t.driverSettings.carTypeUrban}</SelectItem>
                  <SelectItem value="nt">{t.driverSettings.carTypeNT}</SelectItem>
                  <SelectItem value="lantau">{t.driverSettings.carTypeLantau}</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </div>

        {/* 通知設定 */}
        <div className="rounded-2xl bg-zinc-900 border border-zinc-800 overflow-hidden">
          <div className="px-4 py-3 border-b border-zinc-800 flex items-center gap-2">
            <Bell className="size-4 text-yellow-400" />
            <span className="text-sm font-bold text-white">
              {t.driverSettings.notificationSection}
            </span>
          </div>

          <div className="divide-y divide-zinc-800">
            {[
              {
                key: 'newOrderNotif' as const,
                label: t.driverSettings.newOrderNotif,
              },
              {
                key: 'messageNotif' as const,
                label: t.driverSettings.messageNotif,
              },
              {
                key: 'systemNotif' as const,
                label: t.driverSettings.systemNotif,
              },
              {
                key: 'voiceNotif' as const,
                label: t.driverSettings.voiceNotif,
              },
              {
                key: 'voiceFemale' as const,
                label: t.driverSettings.voiceFemale,
              },
            ].map((item) => (
              <div
                key={item.key}
                className="flex items-center justify-between px-4 py-3"
              >
                <span className="text-sm font-bold text-white">{item.label}</span>
                <Switch
                  checked={settings[item.key]}
                  onCheckedChange={(v) =>
                    setSettings({ ...settings, [item.key]: v })
                  }
                />
              </div>
            ))}
          </div>
        </div>

        {/* 語言設定 */}
        <div className="rounded-2xl bg-zinc-900 border border-zinc-800 overflow-hidden">
          <div className="px-4 py-3 border-b border-zinc-800 flex items-center gap-2">
            <Globe className="size-4 text-yellow-400" />
            <span className="text-sm font-bold text-white">
              {t.driverSettings.languageSection}
            </span>
          </div>

          <div className="divide-y divide-zinc-800">
            {(
              [
                { code: 'zh-Hant', label: t.driverSettings.zhHant },
                { code: 'en', label: t.driverSettings.en },
                { code: 'ja', label: t.driverSettings.ja },
              ] as const
            ).map((l) => {
              const active = lang === l.code;
              return (
                <button
                  key={l.code}
                  onClick={() => handleChangeLang(l.code)}
                  className="w-full flex items-center justify-between px-4 py-3 hover:bg-zinc-800/60 transition-colors text-left"
                >
                  <span className="text-sm font-bold text-white">{l.label}</span>
                  {active && <Check className="size-5 text-yellow-400" />}
                </button>
              );
            })}
          </div>
        </div>

        {/* 更改密碼 */}
        <div className="rounded-2xl bg-zinc-900 border border-zinc-800 overflow-hidden">
          <div className="px-4 py-3 border-b border-zinc-800 flex items-center gap-2">
            <Check className="size-4 text-yellow-400" />
            <span className="text-sm font-bold text-white">
              {t.driverSettings.changePasswordSection}
            </span>
          </div>
          <div className="px-4 py-3 space-y-4">
            <div>
              <label className="text-xs text-zinc-400 font-medium mb-1.5 block">
                {t.driverSettings.oldPassword}
              </label>
              <Input
                type="password"
                value={pw.old}
                onChange={(e) => setPw({ ...pw, old: e.target.value })}
                className="bg-zinc-800 border-zinc-700 text-white h-11 font-bold"
                autoComplete="current-password"
              />
            </div>
            <div>
              <label className="text-xs text-zinc-400 font-medium mb-1.5 block">
                {t.driverSettings.newPassword}
              </label>
              <Input
                type="password"
                value={pw.next}
                onChange={(e) => setPw({ ...pw, next: e.target.value })}
                className="bg-zinc-800 border-zinc-700 text-white h-11 font-bold"
                autoComplete="new-password"
              />
            </div>
            <div>
              <label className="text-xs text-zinc-400 font-medium mb-1.5 block">
                {t.driverSettings.confirmPassword}
              </label>
              <Input
                type="password"
                value={pw.confirm}
                onChange={(e) => setPw({ ...pw, confirm: e.target.value })}
                className="bg-zinc-800 border-zinc-700 text-white h-11 font-bold"
                autoComplete="new-password"
              />
            </div>
            <Button
              onClick={handleChangePassword}
              disabled={pwSaving}
              className="w-full h-11 rounded-xl bg-zinc-700 hover:bg-zinc-600 text-white font-bold text-sm"
            >
              {pwSaving ? '...' : t.driverSettings.changePasswordBtn}
            </Button>
          </div>
        </div>

        {/* 儲存 */}
        <Button
          onClick={handleSave}
          disabled={saving}
          className="w-full h-12 rounded-2xl bg-yellow-500 hover:bg-yellow-400 text-black font-black text-base"
        >
          {saving ? '...' : t.driverSettings.saveBtn}
        </Button>

        {/* 登出 */}
        <AlertDialog open={logoutConfirm} onOpenChange={setLogoutConfirm}>
          <AlertDialogTrigger asChild>
            <button className="w-full flex items-center justify-center gap-2 py-4 rounded-2xl bg-red-500/10 text-red-400 hover:bg-red-500/20 transition-colors border border-red-500/20">
              <LogOut className="size-5" />
              <span className="text-lg font-bold">{t.driverSettings.logoutBtn}</span>
            </button>
          </AlertDialogTrigger>
          <AlertDialogContent className="bg-zinc-900 border-zinc-700 text-white max-w-sm">
            <AlertDialogHeader>
              <AlertDialogTitle className="text-white text-xl font-bold">
                {t.driverSettings.logoutConfirm}
              </AlertDialogTitle>
              <AlertDialogDescription className="text-zinc-400 text-base">
                {t.driverSettings.logoutDesc}
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter className="gap-2 sm:gap-2">
              <AlertDialogCancel className="bg-zinc-800 text-white border-zinc-700 hover:bg-zinc-700 mt-2 sm:mt-0">
                {t.common.cancel}
              </AlertDialogCancel>
              <AlertDialogAction
                onClick={handleLogout}
                className="bg-red-500 hover:bg-red-600 text-white"
              >
                {t.driverSettings.logoutBtn}
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>

        {/* 刪除帳戶 */}
        <AlertDialog open={deleteConfirm} onOpenChange={setDeleteConfirm}>
          <AlertDialogTrigger asChild>
            <button className="w-full flex items-center justify-center gap-2 py-3 rounded-2xl bg-red-500/5 text-red-400/80 hover:bg-red-500/15 transition-colors border border-red-500/20 text-sm">
              <span className="font-semibold">刪除帳戶</span>
            </button>
          </AlertDialogTrigger>
          <AlertDialogContent className="bg-zinc-900 border-zinc-700 text-white max-w-sm">
            <AlertDialogHeader>
              <AlertDialogTitle className="text-white text-xl font-bold text-red-400">
                刪除帳戶
              </AlertDialogTitle>
              <AlertDialogDescription className="text-zinc-400 text-base leading-relaxed">
                確定要刪除帳戶？呢個動作<strong className="text-white">不可逆</strong>——會刪除你嘅帳戶同所有相關訂單資料。日後需要重新申請註冊。
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter className="gap-2 sm:gap-2">
              <AlertDialogCancel className="bg-zinc-800 text-white border-zinc-700 hover:bg-zinc-700 mt-2 sm:mt-0">
                取消
              </AlertDialogCancel>
              <AlertDialogAction
                onClick={handleDeleteAccount}
                disabled={deleting}
                className="bg-red-500 hover:bg-red-600 text-white"
              >
                {deleting ? '刪除中…' : '確認刪除'}
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>

        {/* 私隱政策 */}
        <button
          onClick={() => navigate('/privacy')}
          className="w-full flex items-center justify-center gap-2 py-3 rounded-2xl bg-zinc-800/40 hover:bg-zinc-800 text-zinc-300 transition-colors text-sm"
        >
          <span className="font-semibold">私隱政策</span>
        </button>
      </div>
    </div>
  );
}
