import { useMemo } from 'react';
import { motion } from 'framer-motion';
import { useI18n } from '@/lib/i18n';

export interface ChartDataPoint {
  label: string;
  value: number;
}

interface BarChartProps {
  data: ChartDataPoint[];
  height?: number;
  color?: string;
  yUnit?: string;
  animate?: boolean;
}

export default function BarChart({
  data,
  height = 180,
  color = '#eab308',
  yUnit = '$',
  animate = true,
}: BarChartProps) {
  const { t } = useI18n();

  const { maxValue, bars } = useMemo(() => {
    const max = Math.max(...data.map((d) => d.value), 1);
    const ceilMax = Math.ceil(max / 50) * 50; // round up to nearest 50
    return {
      maxValue: ceilMax,
      bars: data.map((d) => ({
        ...d,
        heightPct: (d.value / ceilMax) * 100,
      })),
    };
  }, [data]);

  const yTicks = useMemo(() => {
    const ticks = [];
    const step = maxValue / 4;
    for (let i = 4; i >= 0; i--) {
      ticks.push(Math.round(step * i));
    }
    return ticks;
  }, [maxValue]);

  return (
    <div className="w-full" style={{ height }}>
      <div className="flex h-full gap-2">
        {/* Y-axis labels */}
        <div className="flex flex-col justify-between py-1 text-[9px] text-zinc-500 font-mono w-10 text-right">
          {yTicks.map((tick, i) => (
            <span key={i}>{yUnit}{tick}</span>
          ))}
        </div>

        {/* Bars area */}
        <div className="flex-1 flex items-end gap-1.5 relative">
          {/* Grid lines */}
          <div className="absolute inset-0 flex flex-col justify-between pointer-events-none">
            {yTicks.map((_, i) => (
              <div key={i} className="border-t border-zinc-800/40" />
            ))}
          </div>

          {bars.map((bar, i) => (
            <div key={bar.label} className="flex-1 flex flex-col items-center justify-end h-full relative z-10">
              <motion.div
                initial={animate ? { height: 0 } : false}
                animate={{ height: `${bar.heightPct}%` }}
                transition={{ duration: 0.6, delay: i * 0.05, ease: 'easeOut' }}
                className="w-full rounded-t-md relative group"
                style={{
                  background: `linear-gradient(to top, ${color}, ${color}dd)`,
                  minHeight: bar.value > 0 ? '4px' : '0',
                }}
              >
                {/* Value tooltip */}
                <div className="absolute -top-5 left-1/2 -translate-x-1/2 text-[9px] font-bold text-white bg-zinc-800 px-1.5 py-0.5 rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap">
                  {yUnit}{bar.value}
                </div>
              </motion.div>
            </div>
          ))}
        </div>
      </div>

      {/* X-axis labels */}
      <div className="flex gap-2 mt-1.5">
        <div className="w-10" />
        <div className="flex-1 flex gap-1.5">
          {bars.map((bar) => (
            <div
              key={bar.label}
              className="flex-1 text-center text-[9px] text-zinc-500 truncate"
              title={bar.label}
            >
              {bar.label}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
