// ============= 出 Post 表單 =============
interface RentalPostFormProps {
  t: ReturnType<typeof useI18n>['t'];
  onSubmit: () => void;
  onCancel: () => void;
  initial?: IRentalCar;     // 編輯模式預填
  initialPwd?: string;      // 編輯模式已驗證嘅管理密碼
}

function RentalPostForm({ t, onSubmit, onCancel, initial, initialPwd }: RentalPostFormProps) {
  const [district, setDistrict] = useState<DistrictKey | ''>(initial?.district || '');
  const [taxiColor, setTaxiColor] = useState<TaxiColor | ''>(initial?.taxiColor || '');
  const [carModel, setCarModel] = useState<CarModelKey | ''>(initial?.carModel || '');
  const [shift, setShift] = useState<ShiftType | ''>(initial?.shift || '');
  const [price, setPrice] = useState(initial ? String(initial.price || '') : '');
  const [plate, setPlate] = useState(initial?.plate || '');
  const [ownerName, setOwnerName] = useState(initial?.ownerName || '');
  const [phone, setPhone] = useState(initial?.ownerPhone || '');
  const [note, setNote] = useState(initial?.note || '');
  const [duration, setDuration] = useState<number | ''>(initial?.duration || '');
  const [managePwd, setManagePwd] = useState('');
  const [managePwdError, setManagePwdError] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});

  function validate(): boolean {
    const e: Record<string, string> = {};
    if (!district) e.district = t.rental.errors.districtRequired;
    if (!taxiColor) e.taxiColor = t.rental.errors.taxiColorRequired;
    if (!carModel) e.carModel = t.rental.errors.carModelRequired;
    if (!shift) e.shift = t.rental.errors.shiftRequired;
    if (!price.trim()) {
      e.price = t.rental.errors.priceRequired;
    } else if (isNaN(Number(price)) || Number(price) <= 0) {
      e.price = t.rental.errors.priceInvalid;
    }
    if (!phone.trim()) {
      e.phone = t.rental.errors.phoneRequired;
    } else if (!/^[0-9]{8}$/.test(phone.trim())) {
      e.phone = t.rental.errors.phoneInvalid;
    }
    setErrors(e);
    return Object.keys(e).length === 0;
  }

  function handleSubmit(ev: FormEvent) {
    ev.preventDefault();
    if (!validate()) return;
    if (!initial && !managePwd.trim()) { setManagePwdError('請設定管理密碼，日後用嚟修改／刪除'); return; }
    setManagePwdError('');
    setSubmitting(true);
    (async () => {
      try {
        const payload = {
          district: district as DistrictKey,
          taxiColor: taxiColor as TaxiColor,
          carModel: carModel as CarModelKey,
          shift: shift as ShiftType,
          price: Number(price),
          priceUnit: 'day',
          plate: plate.trim() || '—',
          ownerName: ownerName.trim() || (t.rental.defaultOwner || '車主'),
          ownerPhone: phone.trim(),
          year: new Date().getFullYear(),
          seats: getSeatsByModel(carModel as CarModelKey),
          note: note.trim() || undefined,
          duration: duration || undefined,
          rating: 5.0,
          rentalCount: 0,
        };
        if (initial) {
          await updateRentalPost(initial.id, payload, initialPwd || '');
          toast.success('已更新');
        } else {
          await addRentalPost(payload, managePwd);
          toast.success(t.rental.postSuccess);
        }
        onSubmit();
      } catch (e: any) {
        toast.error(e?.message || t.common?.toast?.failed || '發佈失敗');
      } finally {
        setSubmitting(false);
      }
    })();
  }

  function appendTag(tagText: string) {
      const sep = t.rental.noteSeparator || '、';
      setNote((prev) => {
        if (!prev) return tagText;
        if (prev.includes(tagText)) return prev;
        return prev.endsWith(sep) || prev.endsWith(',') ? prev + tagText : prev + sep + tagText;
      });
  }

  function renderChipRow<T extends string>(
    items: { key: T; label?: string }[],
    value: T | '',
    setValue: (v: T) => void,
  ) {
    return (
      <div className="flex flex-wrap gap-2">
        {items.map((item) => {
          const label = item.label ?? item.key;
          const active = value === item.key;
          return (
            <button
              key={item.key}
              type="button"
              onClick={() => setValue(item.key)}
              className={`px-4 py-2.5 rounded-full text-base font-medium transition-all ${
                active
                  ? 'bg-primary text-primary-foreground shadow-md'
                  : 'bg-muted text-muted-foreground hover:bg-accent hover:text-foreground'
              }`}
            >
              {label}
            </button>
          );
        })}
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-5">
      {/* 地區 */}
      <div className="space-y-2">
        <label className="text-base font-bold text-foreground">{t.rental.fieldDistrict}</label>
        {renderChipRow(
          RENTAL_DISTRICTS.map((d) => ({
            key: d.key,
            label: t.rental.districts[d.key as keyof typeof t.rental.districts] || d.labelZh,
          })),
          district,
          (v) => setDistrict(v as DistrictKey),
        )}
        {errors.district && (
          <p className="text-sm text-destructive font-medium">⚠️ {errors.district}</p>
        )}
      </div>

      {/* 的士顏色 */}
      <div className="space-y-2">
        <label className="text-base font-bold text-foreground">{t.rental.fieldTaxiColor}</label>
        <div className="flex flex-wrap gap-2">
          {RENTAL_TAXI_COLORS.map((c) => {
            const active = taxiColor === c.key;
            return (
              <button
                key={c.key}
                type="button"
                onClick={() => setTaxiColor(c.key)}
                className={`px-4 py-2.5 rounded-full text-base font-medium transition-all flex items-center gap-2 ${
                  active
                    ? 'bg-primary text-primary-foreground shadow-md'
                    : 'bg-muted text-muted-foreground hover:bg-accent hover:text-foreground'
                }`}
              >
                <span
                  className="size-4 rounded-full border border-white/30"
                  style={{ backgroundColor: c.color }}
                />
                {t.rental.taxiColors[c.key]}
              </button>
            );
          })}
        </div>
        {errors.taxiColor && (
          <p className="text-sm text-destructive font-medium">⚠️ {errors.taxiColor}</p>
        )}
      </div>

      {/* 車型 */}
      <div className="space-y-2">
        <label className="text-base font-bold text-foreground">{t.rental.fieldCarModel}</label>
        {renderChipRow(
          RENTAL_CAR_MODELS.map((m) => ({
            key: m.key,
            label: t.rental.carModels[m.key],
          })),
          carModel,
          (v) => setCarModel(v as CarModelKey),
        )}
        {errors.carModel && (
          <p className="text-sm text-destructive font-medium">⚠️ {errors.carModel}</p>
        )}
      </div>

      {/* 更期 */}
      <div className="space-y-2">
        <label className="text-base font-bold text-foreground">{t.rental.fieldShift}</label>
        {renderChipRow(
          RENTAL_SHIFT_TYPES.map((s) => ({
            key: s.key,
            label: t.rental.shifts[s.key],
          })),
          shift,
          (v) => setShift(v as ShiftType),
        )}
        {errors.shift && (
          <p className="text-sm text-destructive font-medium">⚠️ {errors.shift}</p>
        )}
      </div>

      {/* 發佈時間 */}
      <div className="space-y-2">
        <label className="text-base font-bold text-foreground">{t.rental.fieldDuration}</label>
        <div className="flex flex-wrap gap-2">
          {[
            { v: 7, l: t.rental.duration7 },
            { v: 14, l: t.rental.duration14 },
            { v: 30, l: t.rental.duration1M },
            { v: 90, l: t.rental.duration3M },
          ].map((opt) => {
            const active = duration === opt.v;
            return (
              <button
                key={opt.v}
                type="button"
                onClick={() => setDuration(active ? '' : opt.v)}
                className={`px-4 py-2.5 rounded-full text-base font-medium transition-all ${
                  active
                    ? 'bg-primary text-primary-foreground shadow-md'
                    : 'bg-muted text-muted-foreground hover:bg-accent hover:text-foreground'
                }`}
              >
                {opt.l}
              </button>
            );
          })}
        </div>
        <p className="text-sm text-muted-foreground">唔揀就永久有效</p>
      </div>

      {/* 租金 */}
      <div className="space-y-2">
        <label className="text-base font-bold text-foreground">{t.rental.fieldPrice}</label>
        <div className="relative">
          <span className="absolute left-4 top-1/2 -translate-y-1/2 text-foreground font-bold text-lg">
            {t.common.hkd}
          </span>
          <input
            type="number"
            inputMode="numeric"
            value={price}
            onChange={(e) => setPrice(e.target.value)}
            placeholder="650"
            className={`w-full h-14 pl-16 pr-4 rounded-xl border-2 text-lg font-bold tabular-nums bg-background text-foreground focus:outline-none focus:border-primary transition-colors ${
              errors.price ? 'border-destructive' : 'border-border'
            }`}
          />
        </div>
        {errors.price && (
          <p className="text-sm text-destructive font-medium">⚠️ {errors.price}</p>
        )}
      </div>

      {/* 車牌 */}
      <div className="space-y-2">
        <label className="text-base font-bold text-foreground">{t.rental.fieldPlate}</label>
        <input
          type="text"
          value={plate}
          onChange={(e) => setPlate(e.target.value)}
          placeholder={t.rental.placeholderPlate}
          className="w-full h-14 px-4 rounded-xl border-2 border-border bg-background text-foreground text-base focus:outline-none focus:border-primary transition-colors"
        />
      </div>

      {/* 車主名 */}
      <div className="space-y-2">
        <label className="text-base font-bold text-foreground">{t.rental.fieldOwnerName}</label>
        <input
          type="text"
          value={ownerName}
          onChange={(e) => setOwnerName(e.target.value)}
          placeholder={t.rental.placeholderOwnerName}
          className="w-full h-14 px-4 rounded-xl border-2 border-border bg-background text-foreground text-base focus:outline-none focus:border-primary transition-colors"
        />
      </div>

      {/* 聯絡電話 */}
      <div className="space-y-2">
        <label className="text-base font-bold text-foreground">{t.rental.fieldPhone}</label>
        <input
          type="tel"
          inputMode="numeric"
          value={phone}
          onChange={(e) => setPhone(e.target.value)}
          placeholder={t.rental.placeholderPhone}
          maxLength={8}
          className={`w-full h-14 px-4 rounded-xl border-2 bg-background text-foreground text-lg font-medium tabular-nums focus:outline-none focus:border-primary transition-colors ${
            errors.phone ? 'border-destructive' : 'border-border'
          }`}
        />
        {errors.phone && (
          <p className="text-sm text-destructive font-medium">⚠️ {errors.phone}</p>
        )}
      </div>

      {/* 備註 + 快捷標籤 */}
      <div className="space-y-2">
        <label className="text-base font-bold text-foreground">{t.rental.fieldNote}</label>
        {/* 快捷標籤 */}
        <div className="space-y-2">
          <div className="flex items-center gap-1.5 text-sm text-muted-foreground font-medium">
            <Tag className="size-3.5" />
            {t.rental.quickTags}
          </div>
          <div className="flex flex-wrap gap-1.5">
            {QUICK_NOTE_TAGS.map((tag) => (
              <button
                key={tag.key}
                type="button"
                onClick={() => appendTag(t.rental.quickTag[tag.key as keyof typeof t.rental.quickTag])}
                className="px-3 py-1.5 rounded-full text-xs font-medium bg-primary/10 text-primary border border-primary/20 hover:bg-primary/20 transition-colors"
              >
                + {t.rental.quickTag[tag.key as keyof typeof t.rental.quickTag]}
              </button>
            ))}
          </div>
        </div>
        <textarea
          value={note}
          onChange={(e) => setNote(e.target.value)}
          placeholder={t.rental.placeholderNote}
          rows={3}
          className="w-full px-4 py-3 rounded-xl border-2 border-border bg-background text-foreground text-base focus:outline-none focus:border-primary transition-colors resize-none"
        />
      </div>

      {!initial && (
        <div className="space-y-2" id="rentManagePwdField">
          <label className="text-base font-bold text-foreground">管理密碼 *</label>
          <div className="relative">
            <Lock className="absolute left-3 top-1/2 -translate-y-1/2 size-5 text-muted-foreground" />
            <input
              type="password"
              value={managePwd}
              onChange={(e) => { setManagePwd(e.target.value); if (managePwdError) setManagePwdError(''); }}
              placeholder="設定一個密碼，日後修改／刪除要用"
              className={`w-full h-12 pl-10 pr-4 rounded-xl border-2 text-base bg-background text-foreground focus:outline-none transition-colors ${managePwdError ? 'border-red-500' : 'border-border focus:border-primary'}`}
            />
          </div>
          {managePwdError ? (
            <p className="text-sm text-red-500 font-medium">{managePwdError}</p>
          ) : (
            <p className="text-sm text-muted-foreground">記住呢個密碼，日後任何機都可以用嚟修改／刪除呢張單</p>
          )}
        </div>
      )}

      {/* 按鈕 */}
      <div className="pt-2 flex gap-3">
        <button
          type="button"
          onClick={onCancel}
          className="h-14 px-6 rounded-xl bg-muted text-foreground font-bold text-base hover:bg-accent transition-colors"
        >
          {t.common.cancel}
        </button>
        <button
          type="submit"
          disabled={submitting}
          className="flex-1 h-14 rounded-xl bg-primary text-primary-foreground font-bold text-lg shadow-lg hover:scale-[1.02] active:scale-[0.98] transition-transform disabled:opacity-60 disabled:hover:scale-100"
        >
          {submitting ? t.rental.submitting : t.rental.submitPost}
        </button>
      </div>
    </form>
  );
}

// ============= 主頁面 =============
// ============= 人搵車：乘客發佈搭車需求，車主/司機睇到可以聯絡 =============
const RIDE_TAXI_COLORS = [
  { key: 'all', label: '全部顏色' },
  { key: 'red', label: '紅的' },
  { key: 'green', label: '綠的' },
  { key: 'blue', label: '藍的' },
];
const RIDE_TAXI_TYPES = [
  { key: 'all', label: '全部車款' },
  { key: 'comf', label: '金豐' },
  { key: 'hybrid', label: '混能' },
  { key: 'ev', label: '電車' },
  { key: 'mifa', label: 'MIFA 7' },
  { key: 'van', label: '大黃蜂 Van' },
];
const RIDE_TIMES = ['00:00', '06:00', '08:00', '10:00', '12:00', '14:00', '16:00', '18:00', '20:00', '22:00', '23:59'];

// 手動輸入時間：normalize 做 HH:MM，格式唔啱就返 null
function normalizeTime(v: string): string | null {
  v = (v || '').trim();
  if (!/^\d{1,2}:\d{1,2}$/.test(v)) return null;
  const [h, m] = v.split(':').map(Number);
  if (h < 0 || h > 23 || m < 0 || m > 59) return null;
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
}

function FindRideView({ onBack }: { onBack: () => void }) {
  const [requests, setRequests] = useState<IRideRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);

  // 表單狀態
  const [pickupArea, setPickupArea] = useState('');
  const [timeFrom, setTimeFrom] = useState('08:00');
  const [timeTo, setTimeTo] = useState('18:00');
  const [dates, setDates] = useState('');
  const [taxiColor, setTaxiColor] = useState('all');
  const [taxiType, setTaxiType] = useState('all');
  const [duration, setDuration] = useState(10);
  const [contact, setContact] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [contactError, setContactError] = useState('');
  const [areaError, setAreaError] = useState('');
  const [managePwd, setManagePwd] = useState('');
  const [managePwdError, setManagePwdError] = useState('');
  // 管理彈窗（修改/刪除）
  const [manageId, setManageId] = useState<string | null>(null);
  const [manageInput, setManageInput] = useState('');
  const [manageErr, setManageErr] = useState('');
  // 編輯模式
  const [editId, setEditId] = useState<string | null>(null);
  const [editPwd, setEditPwd] = useState('');

  useEffect(() => {
    let alive = true;
    fetchRideRequests().then((r) => { if (alive) { setRequests(r); setLoading(false); } });
    return () => { alive = false; };
  }, []);

  function refresh() {
    setLoading(true);
    fetchRideRequests().then((r) => { setRequests(r); setLoading(false); });
  }

  async function handleSubmit(e: FormEvent) {
    e.preventDefault();
    if (!pickupArea.trim()) { setAreaError('請填寫交收範圍'); setContactError(''); document.getElementById('pickupAreaField')?.scrollIntoView({ behavior: 'smooth', block: 'center' }); return; }
    // 手動輸入時間：驗證 HH:MM 格式
    const nf = normalizeTime(timeFrom);
    const nt = normalizeTime(timeTo);
    if (!nf || !nt) { toast.error('時間要用手動格式 HH:MM，例如 08:00 至 18:00'); return; }
    if (nf >= nt) { toast.error('結束時間要喺開始時間之後'); return; }
    if (!contact.trim()) { setContactError('請填寫聯絡資料（電話或電郵）'); setAreaError(''); document.getElementById('contactField')?.scrollIntoView({ behavior: 'smooth', block: 'center' }); return; }
    const pwd = editId ? editPwd : managePwd;
    if (!pwd.trim()) { setManagePwdError('請設定管理密碼，日後用嚟修改／刪除'); setContactError(''); setAreaError(''); document.getElementById('managePwdField')?.scrollIntoView({ behavior: 'smooth', block: 'center' }); return; }
    setContactError(''); setAreaError(''); setManagePwdError('');
    setSubmitting(true);
    try {
      if (editId) {
        await updateRideRequest(editId, {
          pickupArea: pickupArea.trim(),
          timeFrom: nf, timeTo: nt,
          dates: dates.trim(),
          taxiColor, taxiType,
          duration,
          contact: contact.trim(),
        }, pwd);
        toast.success('已更新');
        setEditId(null); setEditPwd('');
      } else {
        await addRideRequest({
          pickupArea: pickupArea.trim(),
          timeFrom: nf, timeTo: nt,
          dates: dates.trim(),
          taxiColor, taxiType,
          duration,
          contact: contact.trim(),
        }, pwd);
        toast.success('已發佈，車主睇到就會聯絡你');
      }
      setShowForm(false);
      setPickupArea(''); setDates(''); setContact(''); setManagePwd('');
      refresh();
    } catch (err: any) {
      toast.error(err?.message || '發佈失敗');
    } finally {
      setSubmitting(false);
    }
  }

  async function handleDelete(id: string) {
    if (!manageInput.trim()) { setManageErr('請輸入管理密碼'); return; }
    try {
      await removeRideRequest(id, manageInput);
      toast.success('已刪除');
      setManageId(null); setManageInput(''); setManageErr('');
      refresh();
    } catch (err: any) {
      setManageErr(err?.message || '刪除失敗，請檢查密碼');
    }
  }

  function openEdit(r: IRideRequest) {
    setPickupArea(r.pickupArea);
    setTimeFrom(r.timeFrom || '08:00');
    setTimeTo(r.timeTo || '18:00');
    setDates(r.dates || '');
    setTaxiColor(r.taxiColor || 'all');
    setTaxiType(r.taxiType || 'all');
    setContact(r.contact || '');
    setEditId(r.id);
    setEditPwd(manageInput);
    setManageId(null); setManageInput(''); setManageErr('');
    setShowForm(true);
  }

  function colorHex(c: string) {
    if (c === 'red') return '#e11d48';
    if (c === 'green') return '#16a34a';
    if (c === 'blue') return '#2563eb';
    return '#94a3b8';
  }
  function colorLabel(c: string) {
    const f = RIDE_TAXI_COLORS.find((x) => x.key === c);
    return f ? f.label : '全部';
  }
  function typeLabel(c: string) {
    const f = RIDE_TAXI_TYPES.find((x) => x.key === c);
    return f ? f.label : '全部';
  }

  function chip(label: string, active: boolean, onClick: () => void) {
    return (
      <button
        key={label}
        type="button"
        onClick={onClick}
        className={`px-3.5 py-2 rounded-full text-sm font-medium transition-all ${
          active ? 'bg-primary text-primary-foreground shadow-md' : 'bg-muted text-muted-foreground hover:bg-accent'
        }`}
      >
        {label}
      </button>
    );
  }

  if (showForm) {
    return (
      <div className="min-h-screen bg-gradient-to-b from-slate-50 via-white to-background text-foreground">
        <div className="fixed inset-0 overflow-hidden pointer-events-none">
          <div className="absolute top-0 right-0 size-72 rounded-full blur-3xl opacity-10" style={{ backgroundColor: '#0ea5e9' }} />
        </div>
        <div className="relative z-10 sticky top-0 bg-background/80 backdrop-blur-md border-b border-border/40">
          <div className="max-w-lg mx-auto px-4 h-14 flex items-center gap-3">
            <button onClick={() => setShowForm(false)} className="size-10 rounded-full bg-card border border-border flex items-center justify-center hover:bg-muted transition-colors shrink-0">
              <X className="size-5 text-foreground" />
            </button>
            <h1 className="text-lg font-bold flex-1 text-center pr-10">人搵車</h1>
          </div>
        </div>
        <div className="relative z-10 max-w-lg mx-auto px-4 pt-5 pb-10">
          <p className="text-muted-foreground text-base mb-5">填好需求，車主／司機睇到就會聯絡你</p>

          <form onSubmit={handleSubmit} className="space-y-5">
            {/* 交收範圍 */}
            <div className="space-y-2" id="pickupAreaField">
              <label className="text-base font-bold text-foreground">交收範圍 *</label>
              <p className="text-xs text-muted-foreground -mt-1">範圍愈大愈容易配對（例如屯門區錶位）</p>
              <div className="relative">
                <MapPin className="absolute left-3 top-1/2 -translate-y-1/2 size-5 text-muted-foreground" />
                <input
                  value={pickupArea}
                  onChange={(e) => { setPickupArea(e.target.value); if (areaError) setAreaError(''); }}
                  placeholder="例如：元朗"
                  className={`w-full h-12 pl-10 pr-4 rounded-xl border-2 text-base bg-background text-foreground focus:outline-none transition-colors ${areaError ? 'border-red-500' : 'border-border focus:border-primary'}`}
                />
              </div>
              {areaError && <p className="text-sm text-red-500 font-medium">{areaError}</p>}
            </div>

            {/* 交收時間 */}
            <div className="space-y-2">
              <label className="text-base font-bold text-foreground">交收時間 *</label>
              <div className="flex items-center gap-2">
                <input
                  value={timeFrom}
                  onChange={(e) => setTimeFrom(e.target.value)}
                  placeholder="08:00"
                  inputMode="numeric"
                  className="flex-1 h-12 rounded-xl border-2 border-border text-base bg-background text-foreground px-3 focus:outline-none focus:border-primary"
                />
                <span className="text-muted-foreground shrink-0">至</span>
                <input
                  value={timeTo}
                  onChange={(e) => setTimeTo(e.target.value)}
                  placeholder="18:00"
                  inputMode="numeric"
                  className="flex-1 h-12 rounded-xl border-2 border-border text-base bg-background text-foreground px-3 focus:outline-none focus:border-primary"
                />
              </div>
              <p className="text-xs text-muted-foreground">手動輸入，例如 08:00 至 18:00</p>
            </div>

            {/* 交收日期 */}
            <div className="space-y-2">
              <label className="text-base font-bold text-foreground">交收日期</label>
              <div className="relative">
                <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 size-5 text-muted-foreground" />
                <input
                  value={dates}
                  onChange={(e) => setDates(e.target.value)}
                  placeholder="例如：1~5 / 逢星期日 / 10月20日"
                  className="w-full h-12 pl-10 pr-4 rounded-xl border-2 border-border text-base bg-background text-foreground focus:outline-none focus:border-primary transition-colors"
                />
              </div>
            </div>

            {/* 的士顏色 */}
            <div className="space-y-2">
              <label className="text-base font-bold text-foreground">的士顏色</label>
              <div className="flex flex-wrap gap-2">
                {RIDE_TAXI_COLORS.map((c) => chip(c.label, taxiColor === c.key, () => setTaxiColor(c.key)))}
              </div>
            </div>

            {/* 的士類型 */}
            <div className="space-y-2">
              <label className="text-base font-bold text-foreground">的士類型</label>
              <div className="flex flex-wrap gap-2">
                {RIDE_TAXI_TYPES.map((c) => chip(c.label, taxiType === c.key, () => setTaxiType(c.key)))}
              </div>
            </div>

            {/* 發佈時間 */}
            <div className="space-y-2">
              <label className="text-base font-bold text-foreground">發佈時間</label>
              <div className="flex flex-wrap gap-2">
                {[10, 20, 30].map((d) => chip(`${d} 日`, duration === d, () => setDuration(d)))}
              </div>
              <p className="text-sm text-muted-foreground">最多 30 日，到期自動下架</p>
            </div>

            {/* 聯絡資料 */}
            <div className="space-y-2" id="contactField">
              <label className="text-base font-bold text-foreground">聯絡資料 *</label>
              <div className="relative">
                <Phone className="absolute left-3 top-1/2 -translate-y-1/2 size-5 text-muted-foreground" />
                <input
                  value={contact}
                  onChange={(e) => { setContact(e.target.value); if (contactError) setContactError(''); }}
                  placeholder="電話號碼或電郵，例如 91234567 / abc@gmail.com"
                  className={`w-full h-12 pl-10 pr-4 rounded-xl border-2 text-base bg-background text-foreground focus:outline-none transition-colors ${contactError ? 'border-red-500' : 'border-border focus:border-primary'}`}
                />
              </div>
              {contactError ? (
                <p className="text-sm text-red-500 font-medium">{contactError}</p>
              ) : (
                <p className="text-sm text-muted-foreground">車主／司機睇到呢張需求就會用呢個方法聯絡你</p>
              )}
            </div>

            {!editId && (
              <div className="space-y-2" id="managePwdField">
                <label className="text-base font-bold text-foreground">管理密碼 *</label>
                <div className="relative">
                  <Lock className="absolute left-3 top-1/2 -translate-y-1/2 size-5 text-muted-foreground" />
                  <input
                    type="password"
                    value={managePwd}
                    onChange={(e) => { setManagePwd(e.target.value); if (managePwdError) setManagePwdError(''); }}
                    placeholder="設定一個密碼，日後修改／刪除要用"
                    className={`w-full h-12 pl-10 pr-4 rounded-xl border-2 text-base bg-background text-foreground focus:outline-none transition-colors ${managePwdError ? 'border-red-500' : 'border-border focus:border-primary'}`}
                  />
                </div>
                {managePwdError ? (
                  <p className="text-sm text-red-500 font-medium">{managePwdError}</p>
                ) : (
                  <p className="text-sm text-muted-foreground">記住呢個密碼，日後任何機都可以用嚟修改／刪除呢張需求</p>
                )}
              </div>
            )}

            <button
              type="submit"
              disabled={submitting}
              className="w-full h-14 rounded-xl bg-primary text-primary-foreground font-bold text-lg shadow-md hover:scale-[1.01] active:scale-95 transition-transform disabled:opacity-60"
            >
              {submitting ? '發佈中...' : '發佈人搵車'}
            </button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-b from-slate-50 via-white to-background text-foreground">
      <div className="fixed inset-0 overflow-hidden pointer-events-none">
        <div className="absolute top-0 left-0 size-72 rounded-full blur-3xl opacity-10" style={{ backgroundColor: '#0ea5e9' }} />
        <div className="absolute bottom-1/3 right-0 size-80 rounded-full bg-sky-200/20 blur-3xl" />
      </div>

      <div className="relative z-10 sticky top-0 bg-background/80 backdrop-blur-md border-b border-border/40">
        <div className="max-w-lg mx-auto px-4 h-14 flex items-center gap-3">
          <button onClick={onBack} className="size-10 rounded-full bg-card border border-border flex items-center justify-center hover:bg-muted transition-colors shrink-0">
            <ArrowLeft className="size-5 text-foreground" />
          </button>
          <h1 className="text-lg font-bold flex-1 text-center">人搵車</h1>
          <button onClick={() => setShowForm(true)} className="h-9 px-3 rounded-full bg-primary text-primary-foreground text-xs font-bold flex items-center gap-1 shadow-md hover:scale-105 transition-transform shrink-0">
            <Plus className="size-4" />發佈
          </button>
        </div>
      </div>

      <div className="relative z-10 max-w-lg mx-auto px-4 pt-4 pb-8">
        <p className="text-muted-foreground text-base mb-4">車主／司機睇到呢啲需求，可以直接聯絡</p>

        {loading ? (
          <p className="text-center text-muted-foreground py-16">載入緊...</p>
        ) : requests.length === 0 ? (
          <div className="text-center py-16">
            <p className="text-muted-foreground mb-2">暫時冇人搵車</p>
            <button onClick={() => setShowForm(true)} className="text-primary font-bold underline">發佈第一個需求</button>
          </div>
        ) : (
          <div className="space-y-3">
            {requests.map((r) => (
              <div key={r.id} className="bg-card/90 backdrop-blur rounded-2xl border border-border p-4 shadow-sm">
                <div className="flex items-start justify-between gap-2">
                  <div className="flex-1">
                    <div className="flex items-center gap-1.5 mb-1.5">
                      <MapPin className="size-4 text-primary shrink-0" />
                      <span className="text-lg font-bold text-foreground">{r.pickupArea}</span>
                    </div>
                    <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-sm text-muted-foreground">
                      <span className="flex items-center gap-1"><Clock className="size-3.5" />{r.timeFrom} - {r.timeTo}</span>
                      {r.dates && <span className="flex items-center gap-1"><Calendar className="size-3.5" />{r.dates}</span>}
                    </div>
                    <div className="flex flex-wrap gap-1.5 mt-2">
                      <span className="px-2.5 py-0.5 rounded-full text-xs font-semibold text-white" style={{ backgroundColor: colorHex(r.taxiColor) }}>{colorLabel(r.taxiColor)}</span>
                      <span className="px-2.5 py-0.5 rounded-full text-xs font-semibold bg-slate-200 text-slate-700"><CarIcon className="inline size-3 mr-0.5" />{typeLabel(r.taxiType)}</span>
                    </div>
                    {r.contact && (
                      <a
                        href={r.contact.includes('@') ? `mailto:${r.contact}` : `tel:${r.contact.replace(/\s/g, '')}`}
                        className="mt-2 inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-sm font-bold bg-primary/10 text-primary border border-primary/20 hover:bg-primary/20 transition-colors"
                      >
                        <Phone className="size-3.5" />
                        聯絡 {r.contact}
                      </a>
                    )}
                  </div>
                  <button
                    onClick={() => { setManageId(r.id); setManageInput(''); setManageErr(''); }}
                    className="size-9 rounded-full bg-slate-100 text-slate-600 flex items-center justify-center hover:bg-slate-200 transition-colors shrink-0"
                    aria-label="管理"
                  >
                    <Pencil className="size-4" />
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* 管理彈窗：修改／刪除人搵車 */}
      {manageId && (
        <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/50 p-4" onClick={() => setManageId(null)}>
          <div className="bg-background rounded-2xl w-full max-w-md p-5 shadow-xl" onClick={(e) => e.stopPropagation()}>
            <h3 className="text-lg font-bold">管理呢張人搵車</h3>
            <p className="text-sm text-muted-foreground mt-1">輸入發佈時設定嘅管理密碼先可以修改／刪除</p>
            <input
              type="password"
              value={manageInput}
              onChange={(e) => { setManageInput(e.target.value); if (manageErr) setManageErr(''); }}
              placeholder="管理密碼"
              autoFocus
              className="w-full h-12 mt-3 rounded-xl border-2 border-border text-base bg-background px-3 focus:outline-none focus:border-primary"
            />
            {manageErr && <p className="text-sm text-red-500 font-medium mt-1">{manageErr}</p>}
            <div className="flex gap-2 mt-4">
              <button
                onClick={() => { const r = requests.find((x) => x.id === manageId); if (r) openEdit(r); }}
                className="flex-1 h-12 rounded-xl bg-primary text-primary-foreground font-bold"
              >修改</button>
              <button
                onClick={() => handleDelete(manageId)}
                className="flex-1 h-12 rounded-xl bg-destructive text-white font-bold"
              >刪除</button>
            </div>
            <button onClick={() => setManageId(null)} className="w-full mt-2 h-10 rounded-xl text-muted-foreground">取消</button>
          </div>
        </div>
      )}
    </div>
  );
}

export default function RentalPage() {
  const navigate = useNavigate();
  const { t } = useI18n();
  const { primaryColor } = useTheme();

  const [showPostForm, setShowPostForm] = useState(false);
  const [showFindRide, setShowFindRide] = useState(false);
  const [tab, setTab] = useState<'all' | 'mine' | 'favorites'>('all');
  const [cars, setCars] = useState<IRentalCar[]>([]);
  const [favIds, setFavIds] = useState<string[]>([]);
  // 出租管理（修改／刪除，靠管理密碼）
  const [rentManageId, setRentManageId] = useState<string | null>(null);
  const [rentManageInput, setRentManageInput] = useState('');
  const [rentManageErr, setRentManageErr] = useState('');
  // 出租編輯模式
  const [editCar, setEditCar] = useState<IRentalCar | null>(null);
  const [editCarPwd, setEditCarPwd] = useState('');

  const [district, setDistrict] = useState<DistrictKey | 'all'>('all');
  const [taxiColor, setTaxiColor] = useState<TaxiColor | 'all'>('all');
  const [carModel, setCarModel] = useState<CarModelKey | 'all'>('all');
  const [shift, setShift] = useState<ShiftType | 'all'>('all');
  const [priceRange, setPriceRange] = useState<PriceRangeKey>('all');

  // 初次加載
  useEffect(() => {
    let alive = true;
    (async () => {
      const cars = await loadRentalCars();
      if (alive) setCars(cars);
    })();
    setFavIds(getFavoriteIds());
    return () => { alive = false; };
  }, []);

  function refreshCars() {
    loadRentalCars().then(setCars).catch(() => {});
  }

  function handlePostSubmit() {
    setShowPostForm(false);
    setEditCar(null); setEditCarPwd('');
    refreshCars();
    setTab('mine');
  }

  function handleManage(id: string) {
    setRentManageId(id); setRentManageInput(''); setRentManageErr('');
  }

  async function handleRentDelete() {
    if (!rentManageId) return;
    if (!rentManageInput.trim()) { setRentManageErr('請輸入管理密碼'); return; }
    try {
      await removeRentalPost(rentManageId, rentManageInput);
      toast.success('已刪除');
      setRentManageId(null); setRentManageInput(''); setRentManageErr('');
      refreshCars();
    } catch (e: any) {
      setRentManageErr(e?.message || '刪除失敗，請檢查密碼');
    }
  }

  function openRentEdit() {
    const c = cars.find((x) => x.id === rentManageId);
    if (!c) return;
    setEditCar(c);
    setEditCarPwd(rentManageInput);
    setRentManageId(null); setRentManageInput(''); setRentManageErr('');
    setShowPostForm(true);
  }

  function handleToggleFav(id: string) {
    const nowFav = toggleFavorite(id);
    setFavIds(getFavoriteIds());
    toast.success(nowFav ? `♥ ${t.rental.favAdded || '已收藏'}` : `♡ ${t.rental.favRemoved || '已取消收藏'}`);
  }

  const filtered = useMemo(() => {
    let list = cars;
    if (tab === 'mine') {
      list = list.filter((c) => c.isMine);
    } else if (tab === 'favorites') {
      list = list.filter((c) => favIds.includes(c.id));
    }
    const range = RENTAL_PRICE_RANGES.find((r) => r.key === priceRange);
    return list.filter((car) => {
      if (district !== 'all' && car.district !== district) return false;
      if (taxiColor !== 'all' && car.taxiColor !== taxiColor) return false;
      if (carModel !== 'all' && car.carModel !== carModel) return false;
      if (shift !== 'all' && car.shift !== shift) return false;
      if (range && range.key !== 'all') {
        const price = car.price;
        // under_500: price < 500; 500_800: 500 <= price < 800; over_800: price >= 800
        if (range.key === 'under_500' && price >= 500) return false;
        if (range.key === '500_800' && (price < 500 || price >= 800)) return false;
        if (range.key === 'over_800' && price < 800) return false;
      }
      return true;
    });
  }, [cars, tab, district, taxiColor, carModel, shift, priceRange, favIds]);

  type FilterKey = 'district' | 'taxiColor' | 'carModel' | 'shift' | 'priceRange';
  type FilterValue = string | 'all';

  function renderFilterRow(
    key: FilterKey,
    value: FilterValue,
    setValue: (v: FilterValue) => void,
    label: string,
    allLabel: string,
    items: { key: string; label?: string }[],
  ) {
    const getItemLabel = (item: { key: string; label?: string }) => {
      if (item.label) return item.label;
      switch (key) {
        case 'district':
          return t.rental.districts[item.key as DistrictKey];
        case 'taxiColor':
          return t.rental.taxiColors[item.key as TaxiColor];
        case 'carModel':
          return t.rental.carModels[item.key as CarModelKey];
        case 'shift':
          return t.rental.shifts[item.key as ShiftType];
        case 'priceRange':
          return t.rental.priceRange[item.key as keyof typeof t.rental.priceRange];
      }
    };

    return (
      <div className="space-y-2">
        <div className="text-sm font-semibold text-foreground">{label}</div>
        <div className="flex flex-wrap gap-2">
          <button
            onClick={() => setValue('all')}
            className={`px-3.5 py-2 rounded-full text-sm font-medium transition-all ${
              value === 'all'
                ? 'bg-primary text-primary-foreground shadow-md'
                : 'bg-muted text-muted-foreground hover:bg-accent hover:text-foreground'
            }`}
          >
            {allLabel}
          </button>
          {items.map((item) => (
            <button
              key={item.key}
              onClick={() => setValue(item.key)}
              className={`px-3.5 py-2 rounded-full text-sm font-medium transition-all ${
                value === item.key
                  ? 'bg-primary text-primary-foreground shadow-md'
                  : 'bg-muted text-muted-foreground hover:bg-accent hover:text-foreground'
              }`}
            >
              {getItemLabel(item)}
            </button>
          ))}
        </div>
      </div>
    );
  }

  // 出 Post 表單頁
  // 人搵車 view
  if (showFindRide) {
    return <FindRideView onBack={() => setShowFindRide(false)} />;
  }

  if (showPostForm) {
    return (
      <div className="min-h-screen bg-gradient-to-b from-slate-50 via-white to-background text-foreground">
        {/* 背景裝飾 */}
        <div className="fixed inset-0 overflow-hidden pointer-events-none">
          <div
            className="absolute top-0 left-0 size-72 rounded-full blur-3xl opacity-10"
            style={{ backgroundColor: primaryColor }}
          />
        </div>

        {/* 頂部導航 */}
        <div className="relative z-10 sticky top-0 bg-background/80 backdrop-blur-md border-b border-border/40">
          <div className="max-w-lg mx-auto px-4 h-14 flex items-center gap-3">
            <button
              onClick={() => setShowPostForm(false)}
              className="size-10 rounded-full bg-card border border-border flex items-center justify-center hover:bg-muted transition-colors shrink-0"
              aria-label={t.common.cancel}
            >
              <X className="size-5 text-foreground" />
            </button>
            <h1 className="text-lg font-bold flex-1 text-center pr-10">{t.rental.postTitle}</h1>
          </div>
        </div>

        {/* 表單內容 */}
        <div className="relative z-10 max-w-lg mx-auto px-4 pt-5 pb-10">
          <p className="text-muted-foreground text-base mb-5">{t.rental.postSubtitle}</p>
          <RentalPostForm
            t={t}
            initial={editCar || undefined}
            initialPwd={editCarPwd}
            onSubmit={handlePostSubmit}
            onCancel={() => setShowPostForm(false)}
          />
        </div>
      </div>
    );
  }

  // 列表頁
  return (
    <div className="min-h-screen bg-gradient-to-b from-slate-50 via-white to-background text-foreground">
      {/* 背景裝飾 */}
      <div className="fixed inset-0 overflow-hidden pointer-events-none">
        <div
          className="absolute top-0 left-0 size-72 rounded-full blur-3xl opacity-10"
          style={{ backgroundColor: primaryColor }}
        />
        <div className="absolute bottom-1/3 right-0 size-80 rounded-full bg-amber-200/20 blur-3xl" />
      </div>

      {/* 頂部導航 */}
      <div className="relative z-10 sticky top-0 bg-background/80 backdrop-blur-md border-b border-border/40">
        <div className="max-w-lg mx-auto px-4 h-14 flex items-center gap-3">
          <button
            onClick={() => navigate(-1)}
            className="size-10 rounded-full bg-card border border-border flex items-center justify-center hover:bg-muted transition-colors shrink-0"
            aria-label={t.rental.back}
          >
            <ArrowLeft className="size-5 text-foreground" />
          </button>
          <h1 className="text-lg font-bold flex-1 text-center">{t.rental.title}</h1>
          <button
            onClick={() => setShowPostForm(true)}
            className="size-10 rounded-full bg-primary text-primary-foreground flex items-center justify-center shadow-md hover:scale-110 active:scale-95 transition-transform shrink-0"
            aria-label={t.rental.postBtn}
          >
            <Plus className="size-5" />
          </button>
        </div>

        {/* Tab 切換 */}
        <div className="max-w-lg mx-auto px-4 pb-3 flex gap-2">
          <button
            onClick={() => setTab('all')}
            className={`flex-1 h-10 rounded-full text-sm font-bold transition-all flex items-center justify-center gap-1.5 ${
              tab === 'all'
                ? 'bg-primary text-primary-foreground shadow-md'
                : 'bg-muted text-muted-foreground hover:text-foreground'
            }`}
          >
            <Grid3X3 className="size-4" />
            {t.rental.allCarsTab}
          </button>
          <button
            onClick={() => setTab('favorites')}
            className={`flex-1 h-10 rounded-full text-sm font-bold transition-all flex items-center justify-center gap-1.5 ${
              tab === 'favorites'
                ? 'bg-primary text-primary-foreground shadow-md'
                : 'bg-muted text-muted-foreground hover:text-foreground'
            }`}
          >
            <Heart className="size-4" />
            {t.rental.favoritesTab}
          </button>
          <button
            onClick={() => setTab('mine')}
            className={`flex-1 h-10 rounded-full text-sm font-bold transition-all flex items-center justify-center gap-1.5 ${
              tab === 'mine'
                ? 'bg-primary text-primary-foreground shadow-md'
                : 'bg-muted text-muted-foreground hover:text-foreground'
            }`}
          >
            <List className="size-4" />
            {t.rental.myPostsTab}
          </button>
        </div>
      </div>

      {/* 內容 */}
      <div className="relative z-10 max-w-lg mx-auto px-4 pt-4 pb-8">
        {/* 副標題 / 出租按鈕 */}
        <div className="flex items-center gap-3 mb-5">
          <p className="text-muted-foreground text-base flex-1">{t.rental.subtitle}</p>
          <button
            onClick={() => setShowFindRide(true)}
            className="h-10 px-4 rounded-full bg-cyan-500 text-white font-bold text-sm shadow-md hover:scale-105 active:scale-95 transition-transform flex items-center gap-1.5 shrink-0"
          >
            <CarIcon className="size-4" />
            人搵車
          </button>
          <button
            onClick={() => setShowPostForm(true)}
            className="h-10 px-4 rounded-full bg-primary text-primary-foreground font-bold text-sm shadow-md hover:scale-105 active:scale-95 transition-transform flex items-center gap-1.5 shrink-0"
          >
            <Plus className="size-4" />
            {t.rental.postBtn}
          </button>
        </div>

        {/* 篩選區 */}
        <div className="bg-card/80 backdrop-blur rounded-2xl border border-border p-4 mb-5 space-y-4 shadow-sm">
          <p className="text-xs text-muted-foreground font-medium">{t.rental.filterHint}</p>

          {renderFilterRow(
            'district',
            district,
            (v) => setDistrict(v as DistrictKey | 'all'),
            t.rental.district,
            t.rental.allDistricts,
            RENTAL_DISTRICTS.map((d) => ({ key: d.key })),
          )}

          {renderFilterRow(
            'taxiColor',
            taxiColor,
            (v) => setTaxiColor(v as TaxiColor | 'all'),
            t.rental.taxiColor,
            t.rental.allColors,
            RENTAL_TAXI_COLORS.map((c) => ({ key: c.key })),
          )}

          {renderFilterRow(
            'carModel',
            carModel,
            (v) => setCarModel(v as CarModelKey | 'all'),
            t.rental.carModel,
            t.rental.allModels,
            RENTAL_CAR_MODELS.map((m) => ({ key: m.key })),
          )}

          {renderFilterRow(
            'shift',
            shift,
            (v) => setShift(v as ShiftType | 'all'),
            t.rental.shift,
            t.rental.allShifts,
            RENTAL_SHIFT_TYPES.map((s) => ({ key: s.key })),
          )}

          {renderFilterRow(
            'priceRange',
            priceRange,
            (v) => setPriceRange(v as PriceRangeKey),
            t.rental.priceFilter,
            t.rental.priceRange.all,
            RENTAL_PRICE_RANGES.filter((r) => r.key !== 'all').map((r) => ({ key: r.key })),
          )}
        </div>

        {/* 結果數量 */}
        <div className="text-sm text-muted-foreground mb-3 font-medium">
          {t.rental.resultCount.replace('{count}', String(filtered.length))}
        </div>

        {/* 車輛列表 */}
        {filtered.length === 0 ? (
          <div className="bg-card rounded-2xl border border-border p-10 text-center">
            <CarIcon className="size-12 mx-auto text-muted-foreground/40 mb-3" />
            <p className="text-muted-foreground mb-4">
              {tab === 'mine'
                ? t.rental.noMyPosts
                : tab === 'favorites'
                ? t.rental.noFavorites
                : t.rental.empty}
            </p>
            {(tab === 'mine' || tab === 'favorites') && (
              <button
                onClick={() => (tab === 'mine' ? setShowPostForm(true) : setTab('all'))}
                className="h-12 px-6 rounded-full bg-primary text-primary-foreground font-bold text-sm shadow-md hover:scale-105 active:scale-95 transition-transform inline-flex items-center gap-1.5"
              >
                <Plus className="size-4" />
                {tab === 'mine' ? t.rental.goPost : t.rental.allCarsTab}
              </button>
            )}
          </div>
        ) : (
          <div className="space-y-4">
            {filtered.map((car) => (
              <RentalCarCard
                key={car.id}
                car={car}
                t={t}
                isFav={favIds.includes(car.id)}
                onToggleFav={handleToggleFav}
                onManage={handleManage}
              />
            ))}
          </div>
        )}
      </div>

      {/* 出租管理彈窗：修改／刪除 */}
      {rentManageId && (
        <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/50 p-4" onClick={() => setRentManageId(null)}>
          <div className="bg-background rounded-2xl w-full max-w-md p-5 shadow-xl" onClick={(e) => e.stopPropagation()}>
            <h3 className="text-lg font-bold">管理呢張出租</h3>
            <p className="text-sm text-muted-foreground mt-1">輸入發佈時設定嘅管理密碼先可以修改／刪除</p>
            <input
              type="password"
              value={rentManageInput}
              onChange={(e) => { setRentManageInput(e.target.value); if (rentManageErr) setRentManageErr(''); }}
              placeholder="管理密碼"
              autoFocus
              className="w-full h-12 mt-3 rounded-xl border-2 border-border text-base bg-background px-3 focus:outline-none focus:border-primary"
            />
            {rentManageErr && <p className="text-sm text-red-500 font-medium mt-1">{rentManageErr}</p>}
            <div className="flex gap-2 mt-4">
              <button onClick={openRentEdit} className="flex-1 h-12 rounded-xl bg-primary text-primary-foreground font-bold">修改</button>
              <button onClick={handleRentDelete} className="flex-1 h-12 rounded-xl bg-destructive text-white font-bold">刪除</button>
            </div>
            <button onClick={() => setRentManageId(null)} className="w-full mt-2 h-10 rounded-xl text-muted-foreground">取消</button>
          </div>
        </div>
      )}
    </div>
  );
}
