import { createContext, useContext, useState, useEffect, useCallback, type ReactNode } from 'react';
import { scopedStorage, logger } from '@/lib/standalone-shim';
import type { ILatLng } from '@/lib/order-context';

export type FavoritePlaceType = 'home' | 'work' | 'custom';

export interface IFavoritePlace {
  id: string;
  name: string;
  type: FavoritePlaceType;
  location: ILatLng;
}

interface IFavoritePlacesContext {
  places: IFavoritePlace[];
  addPlace: (place: Omit<IFavoritePlace, 'id'>) => void;
  removePlace: (id: string) => void;
  updatePlace: (id: string, data: Partial<Omit<IFavoritePlace, 'id'>>) => void;
}

const FavoritePlacesContext = createContext<IFavoritePlacesContext | null>(null);

const STORAGE_KEY = 'hktaxi_favoritePlaces';

function loadPlaces(): IFavoritePlace[] {
  try {
    const raw = scopedStorage.getItem(STORAGE_KEY);
    if (raw) return JSON.parse(raw);
  } catch (e) {
    logger.error('Failed to load favorite places:', String(e));
  }
  // mock 初始化：屋企 + 公司
  return [
    {
      id: 'fp_home',
      name: '屋企',
      type: 'home',
      location: { name: '旺角', lat: 22.3193, lng: 114.1694 },
    },
    {
      id: 'fp_work',
      name: '公司',
      type: 'work',
      location: { name: '中環', lat: 22.2819, lng: 114.1585 },
    },
  ];
}

function savePlaces(list: IFavoritePlace[]) {
  try {
    scopedStorage.setItem(STORAGE_KEY, JSON.stringify(list));
  } catch (e) {
    logger.error('Failed to save favorite places:', String(e));
  }
}

export function FavoritePlacesProvider({ children }: { children: ReactNode }) {
  const [places, setPlaces] = useState<IFavoritePlace[]>(() => loadPlaces());

  useEffect(() => {
    savePlaces(places);
  }, [places]);

  const addPlace = useCallback((place: Omit<IFavoritePlace, 'id'>) => {
    const newPlace: IFavoritePlace = {
      ...place,
      id: `fp_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
    };
    setPlaces((prev) => [...prev, newPlace]);
  }, []);

  const removePlace = useCallback((id: string) => {
    setPlaces((prev) => prev.filter((p) => p.id !== id));
  }, []);

  const updatePlace = useCallback((id: string, data: Partial<Omit<IFavoritePlace, 'id'>>) => {
    setPlaces((prev) => prev.map((p) => (p.id === id ? { ...p, ...data } : p)));
  }, []);

  return (
    <FavoritePlacesContext.Provider value={{ places, addPlace, removePlace, updatePlace }}>
      {children}
    </FavoritePlacesContext.Provider>
  );
}

export function useFavoritePlaces() {
  const ctx = useContext(FavoritePlacesContext);
  if (!ctx) throw new Error('useFavoritePlaces must be used within FavoritePlacesProvider');
  return ctx;
}
