import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { ArrowLeft, Lock, User, Eye, EyeOff, ShieldCheck, ClipboardCheck } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { toast } from 'sonner';
import { Image } from '@/components/ui/image';
import { useI18n } from '@/lib/i18n';
import { setAdminAuth } from '@/lib/admin-auth';
import { adminLogin, setAuth } from '@/lib/api';

const ADMIN_USERNAME = 'admin';
const ADMIN_PASSWORD = 'lovevivi815';

const LOGO_URL = 'https://aka.doubaocdn.com/s/pKMrCCXYov';

export default function AdminLoginPage() {
  const navigate = useNavigate();
  const { t } = useI18n();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  // 登入身份：管理員 / 營運主任
  const [loginMode, setLoginMode] = useState<'admin' | 'operator'>('admin');
  const isOp = loginMode === 'operator';

  const switchMode = (mode: 'admin' | 'operator') => {
    setLoginMode(mode);
    setUsername('');
    setPassword('');
    setError('');
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!username.trim() || !password.trim()) {
       setError(t.admin.loginRequired);
      return;
    }

    setLoading(true);
    // 先試真後端登入（雲端模式：真審批、真數據）
    try {
      const data = await adminLogin({ username: username.trim(), password });
      // 營運主任登入後，淨係俾佢入批核頁
      const role = data.user?.role === 'operator' ? 'operator' : 'admin';
      setAuth(data.token, { ...data.user, role }, 'admin');
      setAdminAuth(data.token, { ...data.user, role });
      toast.success(role === 'operator' ? '營運主任登入成功' : t.admin.loginSuccess);
      navigate('/admin');
      setLoading(false);
      return;
    } catch (err: any) {
      // 401 = 密碼錯（server 喺度）；網絡錯誤先 fallback 本地單機模式
      if (err?.response?.status === 401 || err?.response?.status === 400) {
        setError(t.admin.loginError);
        setLoading(false);
        return;
      }
      // 離線單機模式：前端本地驗證（原型用）
      if (username.trim() === ADMIN_USERNAME && password === ADMIN_PASSWORD) {
        setAdminAuth('local-admin-token', { username: ADMIN_USERNAME, role: 'admin' });
        setAuth('local-admin-token', { username: ADMIN_USERNAME, role: 'admin' }, 'admin');
        toast.success(t.admin.loginSuccess);
        navigate('/admin');
      } else {
        setError(t.admin.loginError);
      }
    }
    setLoading(false);
  };

  return (
    <div className="min-h-screen bg-background text-foreground flex flex-col">
      {/* Header */}
      <div className="px-4 pt-6 pb-2">
        <div className="flex items-center gap-3">
          <button
            onClick={() => navigate('/')}
            className="size-10 rounded-full bg-card flex items-center justify-center hover:bg-accent transition-colors"
          >
            <ArrowLeft className="size-5" />
          </button>
          <div>
            <h1 className="text-xl font-bold">{t.admin.login}</h1>
             <p className="text-sm text-slate-400">{t.admin.title}</p>
          </div>
        </div>
      </div>

      {/* Logo + brand */}
      <motion.div
        initial={{ opacity: 0, y: -10 }}
        animate={{ opacity: 1, y: 0 }}
        className="flex flex-col items-center justify-center py-12"
      >
        <div className="relative">
          <Image
            src={LOGO_URL}
            alt="的道"
            className="size-20 rounded-full object-cover ring-4 ring-primary/30 shadow-xl shadow-primary/20"
          />
          <div className="absolute -bottom-1 -right-1 size-7 rounded-full bg-emerald-500 flex items-center justify-center ring-4 ring-slate-900">
            <ShieldCheck className="size-4 text-primary-foreground" />
          </div>
        </div>
        <h2 className="text-lg font-bold mb-1">{t.admin.title}</h2>
        <p className="text-sm text-slate-400 mt-1">{t.admin.subtitle}</p>
      </motion.div>

      {/* Login form */}
      <div className="px-6 flex-1">
        <motion.form
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          onSubmit={handleSubmit}
          className="max-w-sm mx-auto space-y-4"
        >
          <Card className="bg-card bg-card border-border backdrop-blur">
            <CardContent className="p-5 space-y-4">
              {/* 登入身份切換 */}
              <div className="grid grid-cols-2 gap-2">
                <button
                  type="button"
                  onClick={() => switchMode('admin')}
                  className={`flex items-center justify-center gap-1.5 rounded-lg py-2 text-sm font-semibold transition-colors ${
                    !isOp ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:bg-muted/70'
                  }`}
                >
                  <ShieldCheck className="size-4" />
                  管理員
                </button>
                <button
                  type="button"
                  onClick={() => switchMode('operator')}
                  className={`flex items-center justify-center gap-1.5 rounded-lg py-2 text-sm font-semibold transition-colors ${
                    isOp ? 'bg-info text-info-foreground' : 'bg-muted text-muted-foreground hover:bg-muted/70'
                  }`}
                >
                  <ClipboardCheck className="size-4" />
                  營運主任
                </button>
              </div>

              {isOp && (
                <div className="p-3 rounded-lg bg-blue-500/10 border border-blue-500/30 text-xs text-blue-300/90 space-y-1">
                  <div className="font-semibold text-blue-300">營運主任登入</div>
                  <div>帳號＝你嘅<strong>手機號碼</strong>，密碼＝你<strong>司機嘅登入密碼</strong>。</div>
                  <div className="text-blue-400/70">需管理員已喺「會員列表」開通你做營運主任先可以用。登入後淨係睇到待審批批核。</div>
                </div>
              )}

              {/* Username */}
              <div className="space-y-1.5">
                <Label htmlFor="username" className="text-xs text-slate-400">
                  {isOp ? '手機號碼' : t.admin.username}
                </Label>
                <div className="relative">
                  <User className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-slate-500" />
                  <Input
                    id="username"
                    type="text"
                    value={username}
                    onChange={(e) => {
                      setUsername(e.target.value);
                      setError('');
                    }}
                    placeholder={isOp ? '請輸入手機號碼' : t.admin.usernamePlaceholder}
                    className="bg-muted border-border pl-9 text-foreground placeholder:text-muted-foreground focus:border-primary h-11"
                    autoComplete="username"
                  />
                </div>
              </div>

              {/* Password */}
              <div className="space-y-1.5">
                <Label htmlFor="password" className="text-xs text-slate-400">
                  {t.admin.password}
                </Label>
                <div className="relative">
                  <Lock className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-slate-500" />
                  <Input
                    id="password"
                    type={showPassword ? 'text' : 'password'}
                    value={password}
                    onChange={(e) => {
                      setPassword(e.target.value);
                      setError('');
                    }}
                    placeholder={t.admin.passwordPlaceholder}
                    className="bg-muted border-border pl-9 pr-10 text-foreground placeholder:text-muted-foreground focus:border-primary h-11"
                    autoComplete="current-password"
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword((s) => !s)}
                    className="absolute right-2 top-1/2 -translate-y-1/2 size-8 rounded-md flex items-center justify-center text-slate-500 hover:text-muted-foreground transition-colors"
                    aria-label={showPassword ? t.admin.hidePassword : t.admin.showPassword}
                  >
                    {showPassword ? <EyeOff className="size-4" /> : <Eye className="size-4" />}
                  </button>
                </div>
              </div>

              {/* Error message */}
              {error && (
                <motion.div
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: 'auto' }}
                  className="p-3 rounded-lg bg-red-500/10 border border-red-500/30 text-sm text-red-400 flex items-center gap-2"
                >
                  <span className="size-1.5 rounded-full bg-red-500 shrink-0" />
                  {error}
                </motion.div>
              )}

              {/* Submit */}
              <Button
                type="submit"
                size="lg"
                className="w-full h-12 rounded-xl font-semibold shadow-lg shadow-primary/25"
                disabled={loading}
              >
                {loading ? (
                  <>
                    <span className="size-4 border-2 border-white/30 border-t-white rounded-full animate-spin mr-2" />
                     {t.admin.signingIn}
                  </>
                 ) : (
                   t.admin.signIn
                 )}
              </Button>
            </CardContent>
          </Card>

           <p className="text-xs text-slate-500 text-center px-4">
             {t.admin.loginSubtitle}
           </p>
        </motion.form>
      </div>

      <div className="pb-8 pt-4 text-center text-xs text-slate-600">
        © 2026 的道 · 香港
      </div>
    </div>
  );
}
