import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Phone, MessageCircle, Star, Navigation, MapPin, Clock, PhoneOff, MessageSquare, Share2, Copy, ExternalLink } from 'lucide-react';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Avatar, AvatarImage, AvatarFallback } from '@/components/ui/avatar';
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetDescription } from '@/components/ui/sheet';
import AMapView from '@/components/AMapView';
import VvipBadge from '@/components/VvipBadge';
import ChatSheet from '@/components/ChatSheet';
import StarRating from '@/components/StarRating';
import { useOrder, CAR_MODEL_OPTIONS, NOTE_TAG_OPTIONS, type CarType } from '@/lib/order-context';
import { useI18n } from '@/lib/i18n';
import { haversineKm } from '@/lib/taxi-utils';
import { resolveAppUrl, copyToClipboard } from '@/lib/standalone-shim';
import { toast } from 'sonner';

export default function PassengerRidingPage() {
  const { order, isLoggedIn } = useOrder();
  const navigate = useNavigate();
  const { t } = useI18n();
  const [showChat, setShowChat] = useState(false);
  const [showCall, setShowCall] = useState(false);
  const [showShare, setShowShare] = useState(false);
  const [callDuration, setCallDuration] = useState(0);
  const callTimerRef = useState<number | null>(null);

  useEffect(() => {
    if (!isLoggedIn) {
      navigate('/passenger/login', { replace: true });
      return;
    }
    if (!order) {
      navigate('/passenger');
      return;
    }
    if (order.status === 'completed' || order.status === 'paid') {
      navigate('/passenger/payment');
      return;
    }
    if (order.status === 'searching') {
      navigate('/passenger/waiting');
      return;
    }
  }, [order, navigate, isLoggedIn]);

  if (!order || !order.driver) return null;

  const isPickedUp = order.status === 'picked_up';
  const statusLabel = isPickedUp ? t.passengerRiding.headingToDest : t.passengerRiding.driverOnTheWay;
  const statusColor = isPickedUp ? 'text-blue-600 bg-blue-50' : 'text-emerald-600 bg-emerald-50';
  // 真實去程距離：司機當前位置 → 乘客上車點（唔再用「全程距離」當「去緊你」）
  const dLat = order.driver.currentLat;
  const dLng = order.driver.currentLng;
  const pLat = order.pickup?.lat;
  const pLng = order.pickup?.lng;
  const toPickupKm = (dLat != null && dLng != null && pLat != null && pLng != null)
    ? haversineKm({ lat: dLat, lng: dLng }, { lat: pLat, lng: pLng })
    : null;
  // 剩餘距離：
  //  未接到客（趕去上車點）＝ 司機當前位置 → 上車點 真實距離
  //  已接到客（去目的地）＝ 起點 → 終點 全程距離
  const remainingKm = isPickedUp
    ? (order.distanceKm && order.distanceKm > 0 ? order.distanceKm : (toPickupKm ?? 0))
    : (toPickupKm ?? (order.distanceKm ?? 0));
  // ETA：剩餘距離 × 行車時間（去程市區較塞 ~25km/h，全程 ~40km/h）
  const eta = remainingKm > 0
    ? Math.max(1, Math.round(remainingKm * (isPickedUp ? 1.5 : 2.4)))
    : (isPickedUp ? 8 : 3);

  const handleCall = () => {
    setShowCall(true);
    setCallDuration(0);
    toast.info(`${t.chat.calling} ${order.driver!.name}...`);
  };

  const handleHangUp = () => {
    setShowCall(false);
    toast.success(t.chat.hangupToast);
  };

  const formatCallDuration = (s: number) => {
    const m = Math.floor(s / 60);
    const sec = s % 60;
    return `${m.toString().padStart(2, '0')}:${sec.toString().padStart(2, '0')}`;
  };

  const driverLat = order.driver.currentLat;
  const driverLng = order.driver.currentLng;

  const shareUrl = resolveAppUrl(`/share/${order.id}`);

  const handleCopyShareLink = async () => {
    try {
      await copyToClipboard(shareUrl);
      toast.success(t.passengerRiding.shareLinkCopied);
    } catch {
      toast.error('Copy failed');
    }
  };

  const handleShareWhatsapp = () => {
    const text = encodeURIComponent(`🚕 的道行程位置提供\n由 ${order.pickup?.name || '上車點'} 去 ${order.destination?.name || '目的地'}\n實時追蹤：${shareUrl}`);
    window.open(`https://wa.me/?text=${text}`, '_blank');
  };

  return (
    <div className="min-h-screen bg-gradient-to-b from-sky-50 via-white to-slate-50 pb-6">
      {/* Header status */}
      <div className="px-4 pt-4 pb-2">
        <motion.div
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          className="flex items-center gap-2"
        >
          <Badge className={`${statusColor} border-0 text-sm font-medium px-3 py-1`}>
            <Clock className="size-3.5 mr-1" />
            {statusLabel}
          </Badge>
           <span className="text-xs text-muted-foreground">
             {t.common.etaPrefix.replace('{time}', String(eta))}
           </span>
        </motion.div>
      </div>

      {/* Map */}
      <div className="px-4 pt-2">
        <AMapView
          pickupName={isPickedUp ? undefined : (order.pickup?.name || '上車點')}
          destinationName={order.destination?.name || '目的地'}
          driverLat={driverLat}
          driverLng={driverLng}
          passengerLat={order.pickup.lat}
          passengerLng={order.pickup.lng}
          showRoute
          height="h-72"
        />
      </div>

      {/* ETA big display */}
      <div className="px-4 mt-4">
        <Card className="bg-gradient-to-br from-primary to-primary/90 text-primary-foreground shadow-lg shadow-primary/20 border-0">
          <CardContent className="p-5">
            <div className="flex items-center justify-between">
              <div>
                 <div className="text-xs opacity-80 mb-1">{t.passengerRiding.eta}</div>
                <div className="text-4xl font-black tabular-nums">
                   {eta}<span className="text-lg font-medium ml-1">{t.common.minute}</span>
                </div>
              </div>
              <div className="text-right">
                <div className="text-xs opacity-80 mb-1">{t.passengerRiding.remainingDist}</div>
                <div className="text-2xl font-bold">
                  {remainingKm.toFixed(1)}<span className="text-sm font-medium ml-1">km</span>
                </div>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Driver info card */}
      <div className="px-4 mt-4">
        <Card className="shadow-sm">
          <CardContent className="p-4">
            <div className="flex items-center gap-3">
              <Avatar className="size-14 border-2 border-primary/20">
                <AvatarImage src={order.driver?.imageUrl} alt={order.driver?.name || '司機'} />
                <AvatarFallback>{order.driver.name[0]}</AvatarFallback>
              </Avatar>
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 flex-wrap">
                  <span className="font-semibold text-foreground">{order.driver?.name || '司機'}</span>
                  {order.driver.isVvip && <VvipBadge size="sm" />}
                  <div className="flex items-center gap-0.5 text-amber-500">
                    <Star className="size-3 fill-amber-400" />
                    <span className="text-xs font-medium">{order.driver.rating}</span>
                  </div>
                </div>
                <div className="text-sm text-muted-foreground mt-0.5">
                  {t.passengerHome.carModels[order.driver.carModel as keyof typeof t.passengerHome.carModels] ?? order.driver.carModel}
                </div>
                <div className="flex items-center gap-2 mt-1">
                  <Badge variant="outline" className="text-xs font-mono">
                    {order.driver.plate}
                  </Badge>
                   <Badge variant="secondary" className="text-xs">
                     {order.carType === '6-seater' ? t.passengerHome.carType6 : t.passengerHome.carType4}
                   </Badge>
                  {order.tip > 0 && (
                    <Badge variant="secondary" className="text-xs bg-amber-50 text-amber-700 border-amber-200">
                    {t.passengerHome.tipService} HK${order.tip}
                    </Badge>
                  )}
                </div>
              </div>
               <div className="flex gap-2">
                 <button
                   onClick={handleCall}
                   className="size-10 rounded-full bg-green-50 hover:bg-green-100 flex items-center justify-center transition-colors"
                   aria-label={t.chat.callAria}
                 >
                   <Phone className="size-4 text-green-600" />
                 </button>
                 <button
                   onClick={() => setShowChat(true)}
                   className="size-10 rounded-full bg-primary/10 hover:bg-primary/20 flex items-center justify-center transition-colors relative"
                   aria-label={t.chat.sendAria}
                 >
                   <MessageCircle className="size-4 text-primary" />
                   {(order.messages?.length ?? 0) > 0 && (
                     <span className="absolute -top-1 -right-1 size-4 rounded-full bg-red-500 text-white text-[10px] font-bold flex items-center justify-center">
                       {order.messages.length}
                     </span>
                   )}
                 </button>
               </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* 分享行程 */}
      <div className="px-4 mt-3">
        <button
          onClick={() => setShowShare(true)}
          className="w-full flex items-center gap-3 p-4 rounded-2xl bg-gradient-to-r from-primary/10 to-rose-50 border border-primary/20 hover:border-primary/40 transition-all text-left"
        >
          <div className="size-10 rounded-full bg-primary text-primary-foreground flex items-center justify-center shrink-0">
            <Share2 className="size-5" />
          </div>
          <div className="flex-1 min-w-0">
            <div className="font-semibold text-foreground">{t.passengerRiding.shareTrip}</div>
            <div className="text-xs text-muted-foreground mt-0.5">{t.passengerRiding.shareTripDesc}</div>
          </div>
          <ExternalLink className="size-4 text-primary shrink-0" />
        </button>
      </div>

      {/* Route summary */}
      <div className="px-4 mt-4">
        <Card className="shadow-sm">
          <CardContent className="p-4">
            <div className="flex items-center gap-3">
              <div className="flex flex-col items-center">
                <MapPin className="size-4 text-emerald-500" />
                <div className="w-px h-8 bg-slate-200 my-1" />
                <Navigation className="size-4 text-red-500" />
              </div>
              <div className="flex-1 space-y-3">
                <div className="flex items-center justify-between">
                   <span className="text-sm font-medium text-foreground">
                     {isPickedUp ? `${t.passengerRiding.pickedUp} · ` : ''}{order.pickup?.name || '上車點'}
                   </span>
                   {!isPickedUp && (
                     <Badge variant="secondary" className="text-xs">{t.passengerRiding.pickupPoint}</Badge>
                   )}
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-sm font-medium text-foreground">
                    {order.destination?.name || '目的地'}
                  </span>
                   <Badge variant="secondary" className="text-xs">{t.passengerRiding.destinationLabel}</Badge>
                </div>
              </div>

              {/* 乘客備注 */}
              {order.passengerNotes && (order.passengerNotes.tags.length > 0 || order.passengerNotes.text) && (
                <div className="pt-3 mt-3 border-t border-slate-100">
                  <div className="text-xs text-muted-foreground mb-2 flex items-center gap-1">
                  <MessageSquare className="size-3" />
                  {t.passengerHome.passengerNotes}
                </div>
                  {order.passengerNotes.tags.length > 0 && (
                    <div className="flex flex-wrap gap-1 mb-2">
                      {order.passengerNotes.tags.map((tag) => {
                        const opt = NOTE_TAG_OPTIONS.find((o) => o.value === tag);
                        return (
                          <Badge
                            key={tag}
                            variant="secondary"
                            className="text-[11px] bg-violet-50 text-violet-700 border-violet-200/50"
                          >
                            {opt?.emoji} {t.passengerHome.noteTags[tag as keyof typeof t.passengerHome.noteTags] ?? tag}
                          </Badge>
                        );
                      })}
                    </div>
                  )}
                  {order.passengerNotes.text && (
                    <div className="text-xs text-foreground/80 bg-violet-50/50 p-2.5 rounded-lg">
                      {order.passengerNotes.text}
                    </div>
                  )}
                </div>
              )}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* 聊天彈層 */}
      <ChatSheet
        open={showChat}
        onClose={() => setShowChat(false)}
        role="passenger"
        otherName={order.driver?.name || '司機'}
        otherAvatar={order.driver.imageUrl}
        otherIsVvip={order.driver.isVvip}
      />

      {/* 通話中 Dialog */}
      {showCall && (
        <div className="fixed inset-0 z-[60] bg-black/80 backdrop-blur-md flex items-center justify-center">
          <div className="text-center text-white">
            <div className="size-24 rounded-full bg-green-500/20 flex items-center justify-center mx-auto mb-5 animate-pulse">
              <div className="size-16 rounded-full bg-green-500/30 flex items-center justify-center">
                <Phone className="size-7 text-green-400" />
              </div>
            </div>
            <div className="text-lg font-semibold mb-1">{order.driver?.name || '司機'}</div>
            <div className="text-sm text-white/60 mb-1">
               {callDuration === 0 ? t.chat.callingStatus : t.chat.onCall}
            </div>
            {callDuration > 0 && (
              <div className="text-xs text-white/50 tabular-nums mb-6">
                {formatCallDuration(callDuration)}
              </div>
            )}
            {callDuration === 0 && <div className="h-6 mb-6" />}
            <button
              onClick={handleHangUp}
              className="size-14 rounded-full bg-red-500 flex items-center justify-center mx-auto hover:bg-red-600 transition-colors shadow-lg shadow-red-500/30"
               aria-label={t.chat.hangupAria}
            >
              <PhoneOff className="size-6 text-white" />
            </button>
             <div className="text-xs text-white/40 mt-2">{t.chat.hangupAria}</div>
          </div>
        </div>
      )}

      {/* 分享行程 Sheet */}
      <Sheet open={showShare} onOpenChange={setShowShare}>
        <SheetContent side="bottom" className="rounded-t-3xl max-w-md mx-auto px-6 pb-10 pt-6">
          <SheetHeader className="text-left">
            <SheetTitle className="text-xl">{t.passengerRiding.shareTrip}</SheetTitle>
            <SheetDescription>{t.passengerRiding.shareTripDesc}</SheetDescription>
          </SheetHeader>

          <div className="mt-5 space-y-3">
            <div className="p-4 rounded-2xl bg-muted/50 border border-border/60">
              <div className="text-xs text-muted-foreground mb-1">Share Link</div>
              <div className="text-sm font-mono text-foreground break-all">{shareUrl}</div>
            </div>

            <button
              onClick={handleCopyShareLink}
              className="w-full flex items-center gap-3 p-4 rounded-2xl bg-card border border-border hover:border-primary/30 hover:bg-primary/5 transition-all text-left"
            >
              <div className="size-10 rounded-full bg-blue-50 flex items-center justify-center shrink-0">
                <Copy className="size-5 text-blue-600" />
              </div>
              <div className="flex-1">
                <div className="font-semibold text-foreground">{t.passengerRiding.shareViaCopy}</div>
              </div>
            </button>

            <button
              onClick={handleShareWhatsapp}
              className="w-full flex items-center gap-3 p-4 rounded-2xl bg-emerald-50 border border-emerald-200 hover:bg-emerald-100/70 transition-all text-left"
            >
              <div className="size-10 rounded-full bg-emerald-500 flex items-center justify-center shrink-0">
                <svg viewBox="0 0 24 24" fill="white" className="size-5">
                  <path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413z"/>
                </svg>
              </div>
              <div className="flex-1">
                <div className="font-semibold text-emerald-800">{t.passengerRiding.shareViaWhatsapp}</div>
              </div>
            </button>
          </div>
        </SheetContent>
      </Sheet>
    </div>
  );
}
