import { createContext, useContext, useState, useEffect, useCallback, type ReactNode } from 'react';
import { scopedStorage, logger } from '@/lib/standalone-shim';

export type NotificationType = 'new_order' | 'order_status' | 'system' | 'rating' | 'withdraw' | 'complaint';

export interface INotification {
  id: string;
  type: NotificationType;
  title: string;
  content: string;
  read: boolean;
  createdAt: number;
  data?: Record<string, any>;
}

interface INotificationContext {
  notifications: INotification[];
  unreadCount: number;
  pushNotification: (n: Omit<INotification, 'id' | 'createdAt' | 'read'>) => void;
  markAsRead: (id: string) => void;
  markAllAsRead: () => void;
  clearAll: () => void;
}

const NotificationContext = createContext<INotificationContext | null>(null);

const STORAGE_KEY = 'hktaxi_notifications';

function loadNotifications(): INotification[] {
  try {
    const raw = scopedStorage.getItem(STORAGE_KEY);
    if (raw) return JSON.parse(raw);
  } catch (e) {
    logger.error('Failed to load notifications:', String(e));
  }
  // 初始化 mock 幾條歷史通知
  const now = Date.now();
  const seed: INotification[] = [
    {
      id: 'n_seed_1',
      type: 'system',
      title: '',
      content: '',
      read: false,
      createdAt: now - 3600 * 1000,
    },
    {
      id: 'n_seed_2',
      type: 'order_status',
      title: '',
      content: '',
      read: true,
      createdAt: now - 86400 * 1000,
    },
    {
      id: 'n_seed_3',
      type: 'rating',
      title: '',
      content: '',
      read: false,
      createdAt: now - 86400 * 2 * 1000,
    },
  ];
  return seed;
}

function saveNotifications(list: INotification[]) {
  try {
    scopedStorage.setItem(STORAGE_KEY, JSON.stringify(list));
  } catch (e) {
    logger.error('Failed to save notifications:', String(e));
  }
}

export function NotificationProvider({ children }: { children: ReactNode }) {
  const [notifications, setNotifications] = useState<INotification[]>(() => loadNotifications());

  useEffect(() => {
    saveNotifications(notifications);
  }, [notifications]);

  const unreadCount = notifications.filter((n) => !n.read).length;

  const pushNotification = useCallback((n: Omit<INotification, 'id' | 'createdAt' | 'read'>) => {
    const item: INotification = {
      ...n,
      id: `n_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
      createdAt: Date.now(),
      read: false,
    };
    setNotifications((prev) => [item, ...prev].slice(0, 100));
  }, []);

  const markAsRead = useCallback((id: string) => {
    setNotifications((prev) =>
      prev.map((n) => (n.id === id ? { ...n, read: true } : n)),
    );
  }, []);

  const markAllAsRead = useCallback(() => {
    setNotifications((prev) => prev.map((n) => ({ ...n, read: true })));
  }, []);

  const clearAll = useCallback(() => {
    setNotifications([]);
  }, []);

  return (
    <NotificationContext.Provider
      value={{ notifications, unreadCount, pushNotification, markAsRead, markAllAsRead, clearAll }}
    >
      {children}
    </NotificationContext.Provider>
  );
}

export function useNotifications() {
  const ctx = useContext(NotificationContext);
  if (!ctx) throw new Error('useNotifications must be used within NotificationProvider');
  return ctx;
}
