import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { ArrowLeft, Phone, Globe, Loader2, ShieldCheck } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { toast } from 'sonner';
import { useOrder } from '@/lib/order-context';
import { useI18n } from '@/lib/i18n';
import { useTheme } from '@/lib/theme-context';
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from '@/components/ui/sheet';
import { Image } from '@/components/ui/image';

const LOGO_URL = 'https://aka.doubaocdn.com/s/pKMrCCXYov';

export default function PassengerLoginPage() {
  const navigate = useNavigate();
  const { t, lang, setLang } = useI18n();
  const { primaryColor } = useTheme();
  const [phone, setPhone] = useState('');
  const [password, setPassword] = useState('');
  const [mode, setMode] = useState<'quick' | 'pwd'>('quick');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [langSheetOpen, setLangSheetOpen] = useState(false);
  const orderCtx = useOrder();

  const validatePhone = (p: string) => /^[569]\d{7}$/.test(p);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validatePhone(phone)) {
      setError(t.passengerLogin.phoneInvalid);
      return;
    }
    if (mode === 'pwd' && !password) {
      setError(t.passengerLogin.pwdError);
      return;
    }
    setError('');
    setLoading(true);
    try {
      if (mode === 'pwd') {
        // 密碼登入：電話號碼＋密碼
        const { passengerLogin } = await import('@/lib/api');
        const data = await passengerLogin({ username: phone, password });
        orderCtx.login('passenger', data.user, data.token);
      } else {
        // 電話登入：電話號碼即登入（唔需要輸入驗證碼，直接用萬能碼）
        const { passengerPhoneLogin } = await import('@/lib/api');
        const data = await passengerPhoneLogin(phone, '123456');
        orderCtx.login('passenger', data.user, data.token);
      }
      toast.success(t.passengerLogin.loginSuccess);
      navigate('/passenger');
    } catch {
      setError(mode === 'pwd' ? t.passengerLogin.pwdError : t.passengerLogin.codeError);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-b from-slate-50 via-white to-background text-foreground flex flex-col relative overflow-hidden">
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <div
          className="absolute top-16 left-8 size-72 rounded-full blur-3xl"
          style={{ backgroundColor: primaryColor, opacity: 0.08 }}
        />
        <div className="absolute bottom-48 right-6 size-80 rounded-full bg-amber-300/20 blur-3xl" />
      </div>

      <div className="relative z-10 pt-4 px-4 flex items-center gap-2">
        <Button variant="ghost" size="icon" onClick={() => navigate('/')}>
          <ArrowLeft className="size-5" />
        </Button>
        <div className="flex-1" />
        <Sheet open={langSheetOpen} onOpenChange={setLangSheetOpen}>
          <SheetTrigger asChild>
            <Button variant="ghost" size="icon">
              <Globe className="size-5" />
            </Button>
          </SheetTrigger>
          <SheetContent side="bottom" className="rounded-t-2xl">
            <SheetHeader>
              <SheetTitle>{t.language.current}</SheetTitle>
            </SheetHeader>
            <div className="mt-4 space-y-2">
              {(['zh-Hant', 'en', 'ja'] as const).map((l) => (
                <button
                  key={l}
                  onClick={() => { setLang(l); setLangSheetOpen(false); }}
                  className={`w-full px-4 py-3 rounded-xl text-left transition-colors ${
                    lang === l
                      ? 'bg-primary text-primary-foreground font-medium'
                      : 'bg-accent/50 hover:bg-accent'
                  }`}
                >
                  {t.language[l]}
                </button>
              ))}
            </div>
          </SheetContent>
        </Sheet>
      </div>

      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6, ease: [0.16, 1, 0.3, 1] }}
        className="flex-1 flex flex-col items-center justify-center px-6 py-8"
      >
        <div className="w-full max-w-sm space-y-6">
          <div className="text-center space-y-3">
            <Image src={LOGO_URL} alt="logo" className="size-16 mx-auto rounded-2xl shadow-lg" />
            <h1 className="text-2xl font-bold">{t.passengerLogin.title}</h1>
            <p className="text-sm text-muted-foreground">{t.passengerLogin.subtitle}</p>
          </div>

          <Card className="shadow-xl border-border/40">
            <CardContent className="pt-6">
              <form onSubmit={handleLogin} className="space-y-4">
                {/* 登入方式切換 */}
                <div className="grid grid-cols-2 rounded-full bg-muted p-1">
                  <button
                    type="button"
                    onClick={() => { setMode('quick'); setError(''); }}
                    className={`py-2 rounded-full text-sm font-medium transition-colors ${mode === 'quick' ? 'bg-white text-foreground shadow' : 'text-muted-foreground'}`}
                  >
                    {t.passengerLogin.quickLogin}
                  </button>
                  <button
                    type="button"
                    onClick={() => { setMode('pwd'); setError(''); }}
                    className={`py-2 rounded-full text-sm font-medium transition-colors ${mode === 'pwd' ? 'bg-white text-foreground shadow' : 'text-muted-foreground'}`}
                  >
                    {t.passengerLogin.pwdLogin}
                  </button>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="phone">{t.passengerLogin.phoneLabel}</Label>
                  <div className="relative">
                    <Phone className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                    <Input
                      id="phone"
                      type="tel"
                      inputMode="numeric"
                      maxLength={8}
                      value={phone}
                      onChange={(e) => setPhone(e.target.value.replace(/\D/g, ''))}
                      placeholder={t.passengerLogin.phonePlaceholder}
                      className="pl-10 h-12"
                    />
                  </div>
                </div>

                {mode === 'pwd' && (
                  <div className="space-y-2">
                    <Label htmlFor="password">{t.passengerLogin.passwordLabel}</Label>
                    <Input
                      id="password"
                      type="password"
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      placeholder={t.passengerLogin.passwordPlaceholder}
                      className="h-12"
                    />
                    <p className="text-xs text-muted-foreground">{t.passengerLogin.setPasswordHint}</p>
                  </div>
                )}

                <div className="flex items-start gap-2 rounded-xl bg-muted/40 px-3 py-2.5">
                  <ShieldCheck className="mt-0.5 size-4 shrink-0 text-emerald-600" />
                  <p className="text-xs text-muted-foreground leading-relaxed">
                    私隱保障：你嘅電話號碼只會喺師傅接咗單之後先顯示畀師傅，未接單前唔會公開。
                  </p>
                </div>

                {error && (
                  <div className="text-sm text-destructive text-center">{error}</div>
                )}

                <Button
                  type="submit"
                  disabled={loading}
                  className="w-full h-12 rounded-full text-base font-semibold"
                >
                  {loading && <Loader2 className="size-4 mr-2 animate-spin" />}
                  {t.passengerLogin.loginBtn}
                </Button>

                <p className="text-xs text-muted-foreground text-center leading-relaxed">
                  {t.passengerLogin.terms}
                </p>
              </form>
            </CardContent>
          </Card>

          <p className="text-center text-xs text-muted-foreground/80 leading-relaxed mt-4">
            政府法定收費＋附加費，平台只係方便大家網約。
          </p>

          <p className="text-center text-xs text-muted-foreground/70 leading-relaxed mt-2 px-4">
            本平台只係資訊配對工具，唔係的士營運商；只容許持有香港政府持有的士牌照嘅司機註冊；平台唔收取任何車資、唔控制車資金額。
          </p>

          <div className="text-center">
            <button
              type="button"
              onClick={() => navigate('/privacy')}
              className="text-xs text-muted-foreground underline"
            >
              收集個人資料聲明及私隱政策
            </button>
          </div>
        </div>
      </motion.div>
    </div>
  );
}
