import { useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Battery, Utensils, Car, Navigation2, MapPin, Loader2, Flame } from 'lucide-react';
import { useI18n } from '@/lib/i18n';
import { MAP_POIS } from '@/data/mapPois';

// 全港地圖：電站／廁所／的士站／氣站（真實全港各區主要地點，新界大幅擴充）
// 司機方便睇全港邊度有充電、廁所、的士站、加氣，仲可以導航過去

const AMAP_KEY = '75e09e701f85fabf849e5ff5ef36c01f';

interface Poi {
  name: string;
  address: string;
  lat: number;
  lng: number;
  district: string;
  distance: number | null; // 米
}

type MapType = 'ev' | 'toilet' | 'taxi' | 'gas';

const TYPES: { key: MapType }[] = [
  { key: 'ev' },
  { key: 'toilet' },
  { key: 'taxi' },
  { key: 'gas' },
];

let amapLoadPromise: Promise<typeof window.AMap> | null = null;
function loadAMap(): Promise<typeof window.AMap> {
  if (amapLoadPromise) return amapLoadPromise;
  amapLoadPromise = new Promise((resolve, reject) => {
    if (window.AMap) { resolve(window.AMap); return; }
    const script = document.createElement('script');
    script.type = 'text/javascript';
    script.async = true;
    script.src = `https://webapi.amap.com/maps?v=2.0&key=${AMAP_KEY}&plugin=AMap.AutoComplete,AMap.PlaceSearch,AMap.Scale,AMap.ToolBar,AMap.Geolocation`;
    script.onerror = () => reject(new Error('amap load failed'));
    script.onload = () => { if (window.AMap) resolve(window.AMap); else reject(new Error('amap init failed')); };
    document.head.appendChild(script);
  });
  return amapLoadPromise;
}

function haversineM(lat1: number, lng1: number, lat2: number, lng2: number): number {
  const R = 6371000;
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLng = ((lng2 - lng1) * Math.PI) / 180;
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos((lat1 * Math.PI) / 180) * Math.cos((lat2 * Math.PI) / 180) * Math.sin(dLng / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

export default function DriverMapPage() {
  const { lang } = useI18n();
  const navigate = useNavigate();
  const mapRef = useRef<any>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const markersRef = useRef<any[]>([]);
  const [type, setType] = useState<MapType>('ev');
  const [pois, setPois] = useState<Poi[]>([]);
  const [loading, setLoading] = useState(false);
  const [myLat, setMyLat] = useState<number | null>(null);
  const [myLng, setMyLng] = useState<number | null>(null);
  const [err, setErr] = useState('');
  const [ready, setReady] = useState(false);

  // 初始化地圖
  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        const AMap = await loadAMap();
        if (!alive || !containerRef.current) return;
        const map = new AMap.Map(containerRef.current, {
          zoom: 11,
          center: [114.1694, 22.3193], // 香港中心
          mapStyle: 'amap://styles/light',
        });
        map.addControl(new AMap.Scale());
        mapRef.current = map;
        setReady(true);
      } catch {
        if (alive) setErr('地圖載入失敗');
      }
    })();
    return () => { alive = false; };
  }, []);

  // 攞司機位置（授權到就用嚟計距離）
  useEffect(() => {
    if (!navigator.geolocation) return;
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        setMyLat(pos.coords.latitude);
        setMyLng(pos.coords.longitude);
      },
      () => { /* 唔授權就算，距離用地圖中心 */ },
      { timeout: 5000, enableHighAccuracy: true }
    );
  }, []);

  // 切換分類 → 顯示全港工具地點（本地真實數據，穩定可用）
  useEffect(() => {
    if (!ready || !mapRef.current) return;
    let alive = true;
    setLoading(true);
    setErr('');
    (async () => {
      try {
        const AMap = await loadAMap();
        if (!alive) return;
        const centerLat = myLat ?? 22.3193;
        const centerLng = myLng ?? 114.1694;
        const list: Poi[] = MAP_POIS
          .filter((p) => p.type === type)
          .map((p) => ({
            name: p.name,
            address: '',
            lat: p.lat,
            lng: p.lng,
            district: p.district,
            distance: haversineM(centerLat, centerLng, p.lat, p.lng),
          }))
          .sort((a, b) => (a.distance ?? 0) - (b.distance ?? 0));
        setPois(list);
        markersRef.current.forEach((m) => m.setMap(null));
        markersRef.current = [];
        const map2 = mapRef.current;
        if (map2) {
          const color = type === 'ev' ? '#10b981' : type === 'toilet' ? '#3b82f6' : type === 'taxi' ? '#f59e0b' : '#ec4899';
          list.forEach((p, idx) => {
            const marker = new AMap.Marker({
              position: [p.lng, p.lat],
              content: `<div style="background:${color};color:#fff;border-radius:50%;width:24px;height:24px;display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:700;box-shadow:0 2px 6px rgba(0,0,0,.3)">${idx + 1}</div>`,
              offset: new AMap.Pixel(-12, -12),
            });
            marker.setMap(map2);
            markersRef.current.push(marker);
          });
          if (list.length) map2.setFitView(markersRef.current, false, [40, 40, 40, 40]);
        }
        setLoading(false);
      } catch {
        if (alive) { setErr('地圖載入失敗'); setLoading(false); }
      }
    })();
    return () => { alive = false; };
  }, [type, myLat, myLng, ready]);

  const openNav = (p: Poi) => {
    const url = `https://uri.amap.com/navigation?to=${p.lng},${p.lat},${encodeURIComponent(p.name)}&mode=car&policy=2`;
    window.open(url, '_blank');
  };

  const fmtDist = (d: number | null) => {
    if (d == null) return '';
    if (d < 1000) return `${Math.round(d)}m`;
    return `${(d / 1000).toFixed(1)}km`;
  };

  const labels: Record<MapType, string> = {
    ev: lang === 'en' ? 'EV Charging' : lang === 'ja' ? '充電スタンド' : '電站',
    toilet: lang === 'en' ? 'Toilet' : lang === 'ja' ? 'トイレ' : '廁所',
    taxi: lang === 'en' ? 'Taxi Stand' : lang === 'ja' ? 'タクシー乗り場' : '的士站',
    gas: lang === 'en' ? 'Gas (LPG)' : lang === 'ja' ? 'ガススタンド' : '氣站',
  };
  const icons: Record<MapType, any> = {
    ev: Battery,
    toilet: Utensils,
    taxi: Car,
    gas: Flame,
  };
  const L = {
    title: lang === 'en' ? 'HK Map' : lang === 'ja' ? '全港地図' : '全港地圖',
    subtitle: lang === 'en' ? 'EV · Toilet · Taxi · Gas' : lang === 'ja' ? '充電・トイレ・タクシー・ガス' : '電站・廁所・的士站・氣站 全港大數據',
    distance: lang === 'en' ? 'Distance' : lang === 'ja' ? '距離' : '距離',
    navigate: lang === 'en' ? 'Nav' : lang === 'ja' ? 'ナビ' : '導航',
    noResult: lang === 'en' ? 'No places found' : lang === 'ja' ? '該当する場所が見つかりません' : '暫時搵唔到相關地點',
  };

  return (
    <div className="min-h-screen bg-zinc-950 text-zinc-100 flex flex-col">
      {/* Header */}
      <div className="sticky top-0 z-30 bg-zinc-950/95 backdrop-blur border-b border-zinc-800">
        <div className="px-4 pt-4 pb-3 flex items-center gap-3">
          <button
            onClick={() => navigate('/driver')}
            className="size-9 rounded-full bg-zinc-800 flex items-center justify-center active:scale-95 transition-transform"
          >
            <ArrowLeft className="size-4" />
          </button>
          <div className="flex-1">
            <h1 className="text-lg font-black">{L.title}</h1>
            <p className="text-[11px] text-zinc-400">{L.subtitle}</p>
          </div>
        </div>
        {/* 分類 tab */}
        <div className="px-4 pb-3 flex gap-2">
          {TYPES.map(({ key }) => {
            const Icon = icons[key];
            const active = key === type;
            const color = key === 'ev' ? 'bg-emerald-500' : key === 'toilet' ? 'bg-sky-500' : 'bg-amber-500';
            return (
              <button
                key={key}
                onClick={() => setType(key)}
                className={`flex-1 py-2.5 rounded-xl text-sm font-bold flex items-center justify-center gap-2 transition-all ${
                  active ? `${color} text-white shadow-lg` : 'bg-zinc-800 text-zinc-400'
                }`}
              >
                <Icon className="size-4" />
                {labels[key]}
              </button>
            );
          })}
        </div>
      </div>

      {/* 地圖 */}
      <div ref={containerRef} className="flex-1 w-full relative" style={{ minHeight: 280 }}>
        {loading && (
          <div className="absolute inset-0 z-10 flex items-center justify-center bg-black/30 pointer-events-none">
            <Loader2 className="size-7 animate-spin text-white" />
          </div>
        )}
        {err && (
          <div className="absolute top-2 left-1/2 -translate-x-1/2 z-10 bg-red-600 text-white text-xs px-3 py-1.5 rounded-lg">
            {err}
          </div>
        )}
      </div>

      {/* POI 列表 */}
      <div className="flex-1 min-h-[200px] max-h-[45vh] overflow-y-auto border-t border-zinc-800">
        {pois.length === 0 && !loading && (
          <div className="py-10 text-center text-zinc-500 text-sm">
            {L.noResult}
          </div>
        )}
        {pois.map((p, idx) => {
          const Icon = icons[type];
          const color = type === 'ev' ? 'text-emerald-400 bg-emerald-500/10' : type === 'toilet' ? 'text-sky-400 bg-sky-500/10' : type === 'taxi' ? 'text-amber-400 bg-amber-500/10' : type === 'gas' ? 'text-pink-400 bg-pink-500/10' : 'text-violet-400 bg-violet-500/10';
          return (
            <button
              key={`${p.name}-${idx}`}
              onClick={() => { const map = mapRef.current; if (map) map.setCenter([p.lng, p.lat]); map?.setZoom(15); }}
              className="w-full flex items-center gap-3 px-4 py-3 border-b border-zinc-800/60 active:bg-zinc-900 transition-colors text-left"
            >
              <div className={`size-10 rounded-full ${color} flex items-center justify-center shrink-0`}>
                <Icon className="size-5" />
              </div>
              <div className="flex-1 min-w-0">
                <div className="text-sm font-bold truncate">{p.name}</div>
                <div className="text-[11px] text-zinc-500 truncate flex items-center gap-1">
                  <MapPin className="size-3 shrink-0" />
                  {p.district}{p.address ? ` · ${p.address}` : ''}
                </div>
                <div className="text-[11px] text-zinc-600 mt-0.5">
                  {L.distance} {fmtDist(p.distance)}
                </div>
              </div>
              <span
                onClick={(e) => { e.stopPropagation(); openNav(p); }}
                className="shrink-0 px-3 py-1.5 rounded-lg bg-zinc-800 text-white text-xs font-bold flex items-center gap-1.5 active:scale-95 transition-transform"
              >
                <Navigation2 className="size-3.5" />
                {L.navigate}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
}
